/* On-device AI for alerts the rules cannot place (stubbed DuitfulKit, as the
   receipt tests do). The AI labels; amounts come from the text. */
const aiCap = await S(async () => {
  const MBB = 'com.maybank2u.life', TNG = 'my.com.tngdigital.ewallet';
  const old = Date.now() - 30 * 60 * 1000;
  const keepCap = window.Capacitor;
  const run = async (items, reply, opts = {}) => {
    state.pendingTxns = []; state.ownAccounts = [];
    const asked = [];
    const plugins = { NotificationListener: { drainCaptured: async () => ({ items }) } };
    if (reply !== undefined) plugins.DuitfulKit = {
      aiStatus: async () => ({ available: opts.available !== false }),
      aiReadAlert: (o) => { asked.push(o.text); return opts.hang ? new Promise(() => {}) : Promise.resolve(typeof reply === 'function' ? reply(o.text) : reply); },
    };
    window.Capacitor = { isNativePlatform: () => true, getPlatform: () => 'android', Plugins: plugins };
    try { await drainCaptured(); } finally { window.Capacitor = keepCap; }
    const out = { asked: asked.length, pending: state.pendingTxns.map((p) => ({ kind: p.kind || 'spend', amount: p.amount, merchant: p.merchant, sender: p.sender, category: p.category, from: p.from && p.from.providerId })) };
    state.pendingTxns = [];
    return out;
  };
  const odd = (tx) => [{ p: MBB, ti: '', tx, t: old }];
  const json = (o) => ({ json: '```json\n' + JSON.stringify(o) + '\n```' });
  const r = {};
  r.spend = await run(odd('Kad 1234: RM 30.00 @ KEDAI RUNCIT MAJU, 15/11'), json({ direction: 'spend', counterparty: 'KEDAI RUNCIT MAJU', category: 'groceries', is_promo_or_security: false, amount: 999 }));
  r.income = await run(odd('Akaun ***1234: +RM 40.00 (ALI BIN ABU)'), json({ direction: 'income', counterparty: 'ALI BIN ABU', category: '', is_promo_or_security: false }));
  r.move = await run(odd('RM 15.00 → TNG eWallet ***5678'), json({ direction: 'move', counterparty: '', category: '', is_promo_or_security: false }));
  r.invented = await run(odd('Akaun ***1234: +RM 40.00'), json({ direction: 'income', counterparty: 'SOMEONE ELSE', category: 'Lottery', is_promo_or_security: false, total: 4000 }));
  r.promo = await run(odd('Weekend treat: RM 5.00 back for you, tap now'), json({ direction: 'income', counterparty: '', category: '', is_promo_or_security: true }));
  r.rule = await run([{ p: TNG, ti: '', tx: 'You have successfully transferred RM 9.00 to KEDAI RUNCIT MAJU.', t: old }], json({ direction: 'income', counterparty: 'ALI BIN ABU', category: 'Food', is_promo_or_security: false }));
  r.noAi = await run(odd('Kad 1234: RM 30.00 @ KEDAI RUNCIT MAJU, 15/11'), undefined);
  r.unavailable = await run(odd('Kad 1234: RM 30.00 @ KEDAI RUNCIT MAJU, 15/11'), json({ direction: 'spend' }), { available: false });
  const t0 = Date.now();
  r.timeout = await run(odd('Kad 1234: RM 30.00 @ KEDAI RUNCIT MAJU, 15/11'), json({ direction: 'spend' }), { hang: true });
  r.timeoutMs = Date.now() - t0;
  r.otp = await run(odd('Your TAC for RM 500.00 is 482913. Do not share.'), json({ direction: 'spend', counterparty: '', category: '', is_promo_or_security: false }));
  save(); renderAll();
  return r;
});
check('AI: an unknown-format alert becomes a spend, with the name it prints and a category from the app\'s list',
  aiCap.spend.asked >= 1 && aiCap.spend.pending.length === 1 && aiCap.spend.pending[0].kind === 'spend' && aiCap.spend.pending[0].amount === 30
  && aiCap.spend.pending[0].merchant === 'KEDAI RUNCIT MAJU' && aiCap.spend.pending[0].category === 'Groceries', JSON.stringify(aiCap.spend));
check('AI: an unknown-format credit becomes income; an AI "move" becomes a move card',
  aiCap.income.pending.length === 1 && aiCap.income.pending[0].kind === 'income' && aiCap.income.pending[0].amount === 40 && aiCap.income.pending[0].sender === 'ALI BIN ABU'
  && aiCap.move.pending.length === 1 && aiCap.move.pending[0].kind === 'move' && aiCap.move.pending[0].amount === 15, JSON.stringify([aiCap.income, aiCap.move]));
check('AI: its amount (999, 4000) is ignored, and a name or category not in the text / the list is dropped',
  aiCap.spend.pending[0].amount === 30 && aiCap.invented.pending.length === 1 && aiCap.invented.pending[0].amount === 40
  && aiCap.invented.pending[0].sender === '', JSON.stringify(aiCap.invented));
check('AI: "promo or security" drops the alert', aiCap.promo.asked === 1 && aiCap.promo.pending.length === 0, JSON.stringify(aiCap.promo));
check('AI: a confident rule wins — a TNG transfer stays a spend to its rule-read payee whatever the AI says',
  aiCap.rule.pending.length === 1 && aiCap.rule.pending[0].kind === 'spend' && aiCap.rule.pending[0].merchant === 'KEDAI RUNCIT MAJU' && aiCap.rule.pending[0].amount === 9, JSON.stringify(aiCap.rule));
check('AI: with no AI, or AI unavailable, an unknown alert does what it did before (nothing without the entity reader)',
  aiCap.noAi.pending.length === 0 && aiCap.unavailable.pending.length === 0 && aiCap.unavailable.asked === 0, JSON.stringify([aiCap.noAi, aiCap.unavailable]));
check('AI: a model that never answers times out and falls back cleanly', aiCap.timeout.asked === 1 && aiCap.timeout.pending.length === 0 && aiCap.timeoutMs < 9000, JSON.stringify(aiCap.timeout) + ' ' + aiCap.timeoutMs);
check('AI: never asked about an OTP / TAC text', aiCap.otp.asked === 0 && aiCap.otp.pending.length === 0, JSON.stringify(aiCap.otp));

/* ── On-device AI: the Settings row, the switch, the one-time card, the tag (1.56.1) ── */
const aiUi = await S(async () => {
  const keepCap = window.Capacitor;
  const snap = { en: state.aiEnabled, seen: state.aiIntroSeen, on: state.aiIntroShownOn };
  const $ = (id) => document.getElementById(id);
  const kitWith = (impl, extra = {}) => ({ isNativePlatform: () => true, getPlatform: () => 'android', Plugins: { DuitfulKit: impl ? { aiStatus: impl, ...extra } : {}, ...(extra.NL ? { NotificationListener: extra.NL } : {}) } });
  const row = async (cap) => { window.Capacitor = cap; await refreshAiStatus(); return { shown: !$('ai-card').hidden, text: $('ai-status').textContent, checked: $('pref-ai').checked }; };
  const out = {};
  state.aiEnabled = true; state.aiIntroSeen = true;
  try {
    out.on = await row(kitWith(async () => ({ available: true })));
    out.ready = await row(kitWith(async () => ({ available: false, reason: 'downloading' })));
    out.none = await row(kitWith(async () => ({ available: false, reason: 'unsupported' })));
    out.missing = await row(kitWith(null));
    out.web = await row(keepCap && keepCap.isNativePlatform && keepCap.isNativePlatform() ? { isNativePlatform: () => false } : keepCap);
    // The switch: off means no AI call for receipts or alerts.
    window.Capacitor = kitWith(async () => ({ available: true }));
    await refreshAiStatus();
    $('pref-ai').checked = false; $('pref-ai').dispatchEvent(new Event('change'));
    out.offState = { en: state.aiEnabled, text: $('ai-status').textContent };
    const asks = [];
    window.Capacitor = kitWith(async () => ({ available: true }), {
      aiReadReceipt: async () => { asks.push('receipt'); return { json: '{"total": 7.9}' }; },
      aiReadAlert: async () => { asks.push('alert'); return { json: '{"direction":"spend"}' }; },
      NL: { drainCaptured: async () => ({ items: [{ p: 'com.maybank2u.life', ti: '', tx: 'Kad 1234: RM 30.00 @ KEDAI RUNCIT MAJU, 15/11', t: Date.now() - 1800000 }] }) },
    });
    state.pendingTxns = [];
    await receiptSecondOpinion({ amount: null, amountConfidence: 'low', vendor: '', date: '' }, 'KEDAI\nTOTAL 7.90');
    await drainCaptured();
    out.offAsks = asks.slice();
    out.offPending = state.pendingTxns.length;
    state.aiEnabled = true;
    state.pendingTxns = [];
    await receiptSecondOpinion({ amount: null, amountConfidence: 'low', vendor: '', date: '' }, 'KEDAI\nTOTAL 7.90');
    await drainCaptured();
    out.onAsks = asks.slice(out.offAsks.length);
    // The capture-card tag: an AI-read card has it, a rule card doesn't.
    renderAll();
    out.tagAi = [...document.querySelectorAll('#pending-list li')].map((li) => li.querySelector('.pending-ai')?.textContent || '');
    state.pendingTxns = [];
    window.duitfulIncoming({ package: 'com.maybank2u.life', text: 'You have received RM 12.00 from ALI BIN ABU.', postedAt: Date.now() - 1800000 });
    renderAll();
    out.tagRule = [...document.querySelectorAll('#pending-list li')].map((li) => li.querySelector('.pending-ai')?.textContent || '');
    state.pendingTxns = [];
    // The one-time Home card.
    window.Capacitor = kitWith(async () => ({ available: true }));
    state.aiIntroSeen = false; state.aiIntroShownOn = '';
    await refreshAiStatus();
    out.introFirst = !$('ai-intro').hidden && /on-device AI/.test($('ai-intro').textContent);
    $('ai-intro-close').click();
    await refreshAiStatus();
    out.introAfter = { hidden: $('ai-intro').hidden, seen: state.aiIntroSeen };
    state.aiIntroSeen = false; state.aiIntroShownOn = '2020-01-01';
    await refreshAiStatus();
    out.introOldDay = $('ai-intro').hidden;
    state.aiIntroSeen = false; state.aiIntroShownOn = '';
    window.Capacitor = kitWith(async () => ({ available: false, reason: 'unsupported' }));
    await refreshAiStatus();
    out.introNoAi = $('ai-intro').hidden;
    // CSV keeps the switch.
    state.aiEnabled = false;
    out.csvOff = fromCSV(toCSV()).aiEnabled;
    state.aiEnabled = true;
    out.csvOn = fromCSV(toCSV()).aiEnabled;
  } finally {
    window.Capacitor = keepCap;
    Object.assign(state, { aiEnabled: snap.en, aiIntroSeen: true, aiIntroShownOn: snap.on, pendingTxns: [] });
    aiStatusCache = null;
    save(); renderAll();
  }
  return out;
});
check('AI Settings row: "On · runs on this phone" when the model is there',
  aiUi.on.shown && aiUi.on.text === 'On · runs on this phone' && aiUi.on.checked, JSON.stringify(aiUi.on));
check('AI Settings row: "Getting ready" while it downloads; "Not available on this phone; Duitful uses its rules." without it or without the kit',
  aiUi.ready.text === 'Getting ready' && aiUi.none.text === 'Not available on this phone; Duitful uses its rules.' && aiUi.missing.text === aiUi.none.text, JSON.stringify([aiUi.ready, aiUi.none, aiUi.missing]));
check('AI Settings row: hidden on the plain web', aiUi.web.shown === false, JSON.stringify(aiUi.web));
check('AI switch off: saved, says "Off · Duitful uses its rules.", and neither receipts nor bank alerts ask the AI',
  aiUi.offState.en === false && /^Off/.test(aiUi.offState.text) && aiUi.offAsks.length === 0 && aiUi.offPending === 0, JSON.stringify([aiUi.offState, aiUi.offAsks, aiUi.offPending]));
check('AI switch on: both paths ask again', aiUi.onAsks.includes('receipt') && aiUi.onAsks.includes('alert'), JSON.stringify(aiUi.onAsks));
check('a capture card the AI helped read says "Read by your phone\'s AI"; a rule-read card does not',
  aiUi.tagAi.length === 1 && aiUi.tagAi[0] === "Read by your phone's AI" && aiUi.tagRule.length === 1 && aiUi.tagRule[0] === '', JSON.stringify([aiUi.tagAi, aiUi.tagRule]));
check('the on-device AI card shows on Home once, and never after it is dismissed (or on a later day, or without AI)',
  aiUi.introFirst && aiUi.introAfter.hidden && aiUi.introAfter.seen && aiUi.introOldDay && aiUi.introNoAi, JSON.stringify(aiUi));
check('the AI switch survives a CSV round-trip', aiUi.csvOff === false && aiUi.csvOn === true, JSON.stringify([aiUi.csvOff, aiUi.csvOn]));

/* ── On-device AI badge in the header (1.61.0) ──
   Shown only when the phone's own model is ready AND the switch is on; a tap
   lands on Settings → On-device AI, which sits right under the Pro card. */
const aiBadge = await S(async () => {
  const keepCap = window.Capacitor;
  const snap = { en: state.aiEnabled, seen: state.aiIntroSeen };
  const $ = (id) => document.getElementById(id);
  const kitWith = (impl) => ({ isNativePlatform: () => true, getPlatform: () => 'android', Plugins: { DuitfulKit: impl ? { aiStatus: impl } : {} } });
  const look = async (cap) => { window.Capacitor = cap; await refreshAiStatus(); return !$('ai-badge').hidden; };
  const out = {};
  state.aiIntroSeen = true; state.aiEnabled = true;
  try {
    out.on = await look(kitWith(async () => ({ available: true })));
    out.label = $('ai-badge').getAttribute('aria-label');
    out.svg = !!$('ai-badge').querySelector('svg path[stroke="currentColor"]');
    $('pref-ai').checked = false; $('pref-ai').dispatchEvent(new Event('change'));
    out.off = !$('ai-badge').hidden;
    $('pref-ai').checked = true; $('pref-ai').dispatchEvent(new Event('change'));
    out.backOn = !$('ai-badge').hidden;
    out.ready = await look(kitWith(async () => ({ available: false, reason: 'downloading' })));
    out.none = await look(kitWith(async () => ({ available: false, reason: 'unsupported' })));
    out.missing = await look(kitWith(null));
    out.web = await look({ isNativePlatform: () => false });
    // A tap opens the "What on-device AI does" sheet; its AI settings button
    // lands on Settings at the AI card.
    await look(kitWith(async () => ({ available: true })));
    document.getElementById('tabbtn-dashboard').click();
    $('ai-badge').click();
    out.sheet = { open: $('ai-info-dialog').open, settings: !$('ai-info-settings').hidden, tab: document.querySelector('.tab.active')?.dataset.tab };
    $('ai-info-settings').click();
    await new Promise((r) => setTimeout(r, 400));
    const card = $('ai-card').getBoundingClientRect();
    out.tap = { closed: !$('ai-info-dialog').open, tab: document.querySelector('.tab.active')?.dataset.tab, cardShown: !$('ai-card').hidden, inView: card.top < innerHeight && card.bottom > 0 };
    // Order in Settings: the AI card comes straight after the Pro card.
    let prev = $('ai-card').previousElementSibling;
    out.after = prev && prev.id;
    await I18N.loadAll();
    out.ms = I18N.tables.ms['On-device AI is on'] || '';
    out.zh = I18N.tables.zh['On-device AI is on'] || '';
  } finally {
    window.Capacitor = keepCap;
    Object.assign(state, { aiEnabled: snap.en, aiIntroSeen: snap.seen });
    aiStatusCache = null;
    save(); renderAll(); renderAiBadge();
    document.getElementById('tabbtn-dashboard').click();
  }
  return out;
});
check('AI badge: shown in the header when the phone\'s AI is ready and switched on, labelled "On-device AI is on" (Malay and Chinese rows too), drawn with currentColor',
  aiBadge.on && aiBadge.label === 'On-device AI is on' && aiBadge.svg && !!aiBadge.ms && !!aiBadge.zh, JSON.stringify(aiBadge));
check('AI badge: hidden when switched off, back when switched on again',
  !aiBadge.off && aiBadge.backOn, JSON.stringify(aiBadge));
check('AI badge: hidden while the model downloads, on a phone without it, without the kit, and on the web',
  !aiBadge.ready && !aiBadge.none && !aiBadge.missing && !aiBadge.web, JSON.stringify(aiBadge));
check('AI badge: a tap opens the "What on-device AI does" sheet (with an AI settings button), not Settings',
  aiBadge.sheet.open && aiBadge.sheet.settings && aiBadge.sheet.tab === 'dashboard', JSON.stringify(aiBadge.sheet));
check('AI sheet: "AI settings" closes it and opens Settings at the On-device AI card',
  aiBadge.tap.closed && aiBadge.tap.tab === 'data' && aiBadge.tap.cardShown && aiBadge.tap.inView, JSON.stringify(aiBadge.tap));
check('Settings: the On-device AI card sits directly below the Pro card', aiBadge.after === 'pro-card', aiBadge.after);
{
  const idx = readFileSync(path.join(REPO_ROOT, 'app', 'index.html'), 'utf8');
  check('AI badge: on the web it is hidden in the markup and the page never shows it unasked',
    /<button[^>]*id="ai-badge"[^>]*\shidden>/.test(idx) && !(await S(() => !document.getElementById('ai-badge').hidden)));
}

/* ── On-device AI: "What it does" sheet (1.61.1) ──
   One item per AI path that really runs on the platform: receipts and the
   English recap on both; bank alerts and statement suggestions Android only
   (iPhone's DuitfulKit has no aiReadAlert). Never reachable on the web. */
const aiInfo = await S(async () => {
  const keepCap = window.Capacitor;
  const snap = { en: state.aiEnabled, seen: state.aiIntroSeen };
  const $ = (id) => document.getElementById(id);
  const kitWith = (platform, impl) => ({ isNativePlatform: () => true, getPlatform: () => platform, Plugins: { DuitfulKit: impl ? { aiStatus: impl } : {} } });
  const items = () => [...document.querySelectorAll('#ai-info-list li')].filter((li) => !li.hidden).map((li) => li.querySelector('strong').textContent);
  const look = () => ({ open: $('ai-info-dialog').open, items: items(), model: $('ai-info-model').textContent, status: $('ai-info-status').textContent,
    never: [...document.querySelectorAll('.ai-info-never li')].map((li) => li.textContent.trim()), settings: !$('ai-info-settings').hidden,
    summary: $('ai-summary').textContent, label: $('pref-ai-label').textContent, row: !$('ai-card').hidden && !!$('ai-info-open').offsetParent });
  const out = {};
  state.aiIntroSeen = true; state.aiEnabled = true;
  try {
    window.Capacitor = kitWith('android', async () => ({ available: true }));
    await refreshAiStatus();
    document.getElementById('tabbtn-data').click();
    await new Promise((r) => setTimeout(r, 100));
    $('ai-info-open').click();
    out.android = look();
    $('pref-ai').checked = false; $('pref-ai').dispatchEvent(new Event('change'));
    out.androidOff = $('ai-info-status').textContent;
    $('pref-ai').checked = true; $('pref-ai').dispatchEvent(new Event('change'));
    $('ai-info-close').click();
    out.closed = !$('ai-info-dialog').open;
    window.Capacitor = kitWith('ios', async () => ({ available: true }));
    await refreshAiStatus();
    $('ai-info-open').click();
    out.ios = look();
    $('ai-info-dialog').close();
    window.Capacitor = kitWith('android', async () => ({ available: false, reason: 'unsupported' }));
    await refreshAiStatus();
    out.noneOpened = openAiInfo('card');
    out.none = look();
    $('ai-info-dialog').close();
    window.Capacitor = { isNativePlatform: () => false };
    await refreshAiStatus();
    out.webOpened = openAiInfo('badge');
    out.webOpen = $('ai-info-dialog').open;
    out.webCard = !$('ai-card').hidden;
    out.ms = ['What it does', 'What on-device AI does', 'What it never does', 'Model: {m}'].every((k) => !!I18N.tables.ms[k] && !!I18N.tables.zh[k]);
  } finally {
    window.Capacitor = keepCap;
    if ($('ai-info-dialog').open) $('ai-info-dialog').close();
    Object.assign(state, { aiEnabled: snap.en, aiIntroSeen: snap.seen });
    aiStatusCache = null;
    save(); renderAll(); renderAiBadge();
    document.getElementById('tabbtn-dashboard').click();
  }
  return out;
});
check('AI card: a summary line and a "What it does" row that opens the sheet (no AI settings button from the card itself)',
  aiInfo.android.row && /receipts, bank alerts, statements, tax relief and your monthly recap/.test(aiInfo.android.summary) && aiInfo.android.open && !aiInfo.android.settings && aiInfo.closed, JSON.stringify(aiInfo.android));
check('AI sheet on Android: receipts, bank alerts, bank statements, tax relief, monthly recap; Gemini Nano; the live status (and "Off" when switched off)',
  JSON.stringify(aiInfo.android.items) === JSON.stringify(['Receipts', 'Bank alerts', 'Bank statements', 'Tax relief', 'Monthly recap'])
  && aiInfo.android.model === 'Model: Gemini Nano' && aiInfo.android.status === 'On · runs on this phone' && /^Off/.test(aiInfo.androidOff), JSON.stringify([aiInfo.android, aiInfo.androidOff]));
check('AI sheet on iPhone: receipts and monthly recap only (no bank alerts, statements or tax relief); Apple\'s on-device model; summary and switch label say so',
  JSON.stringify(aiInfo.ios.items) === JSON.stringify(['Receipts', 'Monthly recap']) && aiInfo.ios.model === "Model: Apple's on-device model"
  && aiInfo.ios.summary === 'Helps with receipts and your monthly recap.' && aiInfo.ios.label === "Use this phone's AI for receipts and your recap" && aiInfo.android.label === "Use this phone's AI for receipts and bank alerts", JSON.stringify(aiInfo.ios));
check('AI sheet: "What it never does" lists no upload, no made-up amounts, no chat or advice, nothing saved without your OK',
  aiInfo.android.never.length === 4 && /uploaded/.test(aiInfo.android.never[0]) && /amount/.test(aiInfo.android.never[1]) && /chat.*advice/.test(aiInfo.android.never[2]) && /OK/.test(aiInfo.android.never[3]), JSON.stringify(aiInfo.android.never));
check('AI sheet: on a phone without the model it still opens and says "Not available on this phone; Duitful uses its rules."',
  aiInfo.noneOpened && aiInfo.none.status === 'Not available on this phone; Duitful uses its rules.', JSON.stringify(aiInfo.none));
check('AI sheet: never opens on the web (no card, no badge, openAiInfo refuses)', aiInfo.webOpened === false && !aiInfo.webOpen && !aiInfo.webCard, JSON.stringify(aiInfo));
check('AI sheet: its words have Malay and Chinese rows', aiInfo.ms);

/* ── On-device AI thinking state & sempoa mark (1.62.1) ── */
{
  const aiThink = await S(async () => {
    const keepCap = window.Capacitor;
    const snap = { en: state.aiEnabled, seen: state.aiIntroSeen };
    const $ = (id) => document.getElementById(id);
    const resolvers = [];
    const deferred = () => new Promise((r) => resolvers.push(r));
    state.aiIntroSeen = true;
    state.aiEnabled = true;
    window.Capacitor = {
      isNativePlatform: () => true,
      getPlatform: () => 'android',
      Plugins: {
        DuitfulKit: {
          aiStatus: async () => ({ available: true }),
          aiReadReceipt: () => deferred(),
          aiReadAlert: () => deferred(),
        },
      },
    };
    const out = {};
    try {
      await refreshAiStatus();
      const badge = $('ai-badge');
      const live = $('ai-live');
      out.idle = !badge.classList.contains('is-thinking') && live.textContent === '';
      out.liveRole = live.getAttribute('aria-live');
      out.beads = badge.querySelectorAll('svg.sempoa .ai-bead').length;

      // Single AI call: adds .is-thinking and announces "AI is reading…", then clears on finish.
      const p1 = receiptSecondOpinion({ amount: null, amountConfidence: 'low', vendor: '', date: '' }, 'KEDAI KOPI RM 8.50');
      await new Promise((r) => setTimeout(r, 30));
      out.duringSingle = badge.classList.contains('is-thinking');
      out.liveDuring = live.textContent;
      out.motionAnim = getComputedStyle(badge.querySelector('.sp-el1')).animationName;
      resolvers.shift()({ json: '{"total": 8.5}' });
      await p1;
      out.afterSingle = !badge.classList.contains('is-thinking') && live.textContent === '';

      // Overlapping calls: stays active until the last call finishes (even when one rejects).
      const kit = duitfulKit('aiReadAlert');
      const o1 = askAiAboutAlert(kit, 'Paid RM 12.00 at KEDAI A', ['Food']);
      const o2 = askAiAboutAlert(kit, 'Paid RM 15.00 at KEDAI B', ['Food']);
      await new Promise((r) => setTimeout(r, 30));
      out.overlapBoth = badge.classList.contains('is-thinking');
      resolvers.shift()({ json: '{"direction":"spend"}' });
      await o1;
      out.overlapAfterFirst = badge.classList.contains('is-thinking');
      resolvers.shift()(Promise.reject(new Error('boom')));
      await o2;
      out.overlapAfterLast = !badge.classList.contains('is-thinking') && live.textContent === '';

      // Hard timeout clears a hung call so the badge never spins forever.
      out.timeoutConst = AI_THINK_TIMEOUT_MS;
      aiThinkStart(120);
      out.beforeTimeout = badge.classList.contains('is-thinking');
      await new Promise((r) => setTimeout(r, 180));
      out.afterTimeout = !badge.classList.contains('is-thinking') && live.textContent === '';

      // i18n rows for screen reader announcement.
      for (let i = 0; i < 40 && $('ai-think').open; i++) await new Promise((r) => setTimeout(r, 50));
      out.overlayClosedAfter = !$('ai-think').open;
      out.msLive = I18N.tables.ms['AI is reading…'] || '';
      out.zhLive = I18N.tables.zh['AI is reading…'] || '';
    } finally {
      window.Capacitor = keepCap;
      Object.assign(state, { aiEnabled: snap.en, aiIntroSeen: snap.seen });
      aiStatusCache = null;
      save(); renderAll(); renderAiBadge();
    }
    return out;
  });
  check('AI thinking: the sempoa mark has six beads on two rods, is static at idle, and uses an aria-live="polite" region',
    aiThink.beads === 6 && aiThink.idle && aiThink.liveRole === 'polite', JSON.stringify(aiThink));
  check('AI thinking: gets .is-thinking and announces "AI is reading…" during a call, clears after finish',
    aiThink.duringSingle && aiThink.liveDuring === 'AI is reading…' && aiThink.motionAnim === 'ai-sp-el1' && aiThink.afterSingle, JSON.stringify(aiThink));
  check('AI thinking: overlapping calls keep .is-thinking on until the last one ends (including failures)',
    aiThink.overlapBoth && aiThink.overlapAfterFirst && aiThink.overlapAfterLast, JSON.stringify(aiThink));
  check('AI thinking: hard safety timeout (~8s default) clears a hung call',
    aiThink.timeoutConst === 8000 && aiThink.beforeTimeout && aiThink.afterTimeout, JSON.stringify(aiThink));
  check('AI thinking: "AI is reading…" has Malay and Chinese translations',
    !!aiThink.msLive && !!aiThink.zhLive, JSON.stringify({ ms: aiThink.msLive, zh: aiThink.zhLive }));

  // Reduced motion: uses soft opacity breathe on the badge, no bead movement.
  await page.emulateMedia({ reducedMotion: 'reduce' });
  const rmCheck = await S(async () => {
    const keepCap = window.Capacitor;
    const snap = { en: state.aiEnabled, seen: state.aiIntroSeen };
    state.aiIntroSeen = true; state.aiEnabled = true;
    window.Capacitor = { isNativePlatform: () => true, getPlatform: () => 'android', Plugins: { DuitfulKit: { aiStatus: async () => ({ available: true }) } } };
    let out = {};
    try {
      await refreshAiStatus();
      const tok = aiThinkStart(5000);
      const badge = document.getElementById('ai-badge');
      out = {
        badgeAnim: getComputedStyle(badge).animationName,
        beadAnim: getComputedStyle(badge.querySelector('.sp-el1')).animationName,
      };
      aiThinkEnd(tok);
    } finally {
      window.Capacitor = keepCap;
      Object.assign(state, { aiEnabled: snap.en, aiIntroSeen: snap.seen });
      aiStatusCache = null;
      renderAiBadge();
    }
    return out;
  });
  await page.emulateMedia({ reducedMotion: 'no-preference' });
  check('AI thinking: prefers-reduced-motion uses opacity breathe on the badge and keeps beads still',
    rmCheck.badgeAnim === 'ai-badge-breathe' && rmCheck.beadAnim === 'none', JSON.stringify(rmCheck));

  // Header layout at 360px with the AI badge visible in English, Malay and Chinese.
  const keepVp = page.viewportSize();
  await page.setViewportSize({ width: 360, height: 740 });
  const header360 = await S(async () => {
    const keepCap = window.Capacitor;
    const keepLang = I18N.lang;
    const snap = { en: state.aiEnabled, seen: state.aiIntroSeen };
    state.aiIntroSeen = true; state.aiEnabled = true;
    window.Capacitor = { isNativePlatform: () => true, getPlatform: () => 'android', Plugins: { DuitfulKit: { aiStatus: async () => ({ available: true }) } } };
    const results = {};
    try {
      await refreshAiStatus();
      for (const lang of ['en', 'ms', 'zh']) {
        await I18N.set(lang);
        renderAll();
        renderAiBadge();
        const hdr = document.querySelector('.app-header .brand').getBoundingClientRect();
        const badge = document.getElementById('ai-badge').getBoundingClientRect();
        const docOverflow = document.documentElement.scrollWidth > window.innerWidth + 1;
        results[lang] = {
          shown: badge.width > 0,
          inside: badge.right <= hdr.right + 1 && badge.right <= window.innerWidth + 1,
          docOverflow,
        };
      }
    } finally {
      await I18N.set(keepLang);
      window.Capacitor = keepCap;
      Object.assign(state, { aiEnabled: snap.en, aiIntroSeen: snap.seen });
      aiStatusCache = null;
      renderAll(); renderAiBadge();
    }
    return results;
  });
  if (keepVp) await page.setViewportSize(keepVp);
  check('AI badge: header fits without overflow at 360px in English, Malay and Chinese',
    ['en', 'ms', 'zh'].every((l) => header360[l].shown && header360[l].inside && !header360[l].docOverflow),
    JSON.stringify(header360));

  /* The thinking sheet (1.62.1): a call you wait on floats the mark into
     #ai-think; background calls only move the badge. */
  const sheet = async (reduced) => S(async (reduced) => {
    const keepCap = window.Capacitor;
    const snap = { en: state.aiEnabled, seen: state.aiIntroSeen };
    const $ = (id) => document.getElementById(id);
    const wait = (ms) => new Promise((r) => setTimeout(r, ms));
    const closed = async () => { for (let i = 0; i < 120 && $('ai-think').open; i++) await wait(50); return !$('ai-think').open; };
    const resolvers = [];
    const deferred = () => new Promise((r) => resolvers.push(r));
    state.aiIntroSeen = true; state.aiEnabled = true;
    window.Capacitor = { isNativePlatform: () => true, getPlatform: () => 'android', Plugins: { DuitfulKit: {
      aiStatus: async () => ({ available: true }), aiReadReceipt: () => deferred(), aiReadAlert: () => deferred() } } };
    const out = {};
    try {
      await refreshAiStatus();
      document.getElementById('tabbtn-dashboard').click();
      // Foreground: opens, says what it is doing, the badge glyph lifts out.
      window.scrollTo(0, 0);
      out.fromBadge = !!aiThinkHome().badge;   // else it starts at the top centre (side layouts, scrolled away)
      const t0 = Date.now();
      const p1 = receiptSecondOpinion({ amount: null, amountConfidence: 'low', vendor: '', date: '' }, 'KEDAI KOPI RM 8.50');
      await wait(60);
      out.fgOpen = $('ai-think').open;
      out.busy = $('ai-think').getAttribute('aria-busy');
      out.task = $('ai-think-task').textContent;
      out.title = $('ai-think-title').textContent;
      out.lifted = $('ai-badge').classList.contains('is-lifted');
      out.flying = $('ai-think').querySelector('.ai-think-mark').getAnimations().some((a) => !(a instanceof CSSAnimation));
      out.bigBead = getComputedStyle($('ai-think').querySelector('.sp-el1')).animationName;
      out.markAnim = getComputedStyle($('ai-think').querySelector('.ai-think-mark')).animationName;
      resolvers.shift()({ json: '{"total": 8.5}' });   // ends fast …
      await p1;
      await wait(250);
      out.stillOpenAtMin = $('ai-think').open;          // … but the sheet stays its minimum
      out.closedAfter = await closed();
      out.shownFor = Date.now() - t0;
      out.landed = !$('ai-badge').classList.contains('is-lifted');
      // Background: badge only, no sheet.
      const kit = duitfulKit('aiReadAlert');
      const b1 = askAiAboutAlert(kit, 'Paid RM 12.00 at KEDAI A', ['Food']);
      await wait(60);
      out.bgThinking = $('ai-badge').classList.contains('is-thinking');
      out.bgOpen = $('ai-think').open;
      resolvers.shift()({ json: '{"direction":"spend"}' });
      await b1;
      // The hard timeout closes it too.
      aiThinkStart(150, { overlay: true, label: 'Reading your receipt' });
      await wait(40);
      out.toOpen = $('ai-think').open;
      out.toClosed = await closed();
      out.toBadge = !$('ai-badge').classList.contains('is-thinking');
      // Escape hides it; the call carries on and its result still lands.
      const p2 = receiptSecondOpinion({ amount: null, amountConfidence: 'low', vendor: '', date: '' }, 'KEDAI KOPI RM 9.90');
      await wait(60);
      out.escOpen = $('ai-think').open;
      $('ai-think').dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
      $('ai-think').dispatchEvent(new Event('cancel', { cancelable: true }));
      out.escClosed = await closed();
      out.escStillThinking = $('ai-badge').classList.contains('is-thinking');
      resolvers.shift()({ json: '{"total": 9.9}' });
      const r2 = await p2;
      out.escResult = r2 && r2.parsed ? r2.parsed.amount : null;
      out.escStaysShut = !$('ai-think').open && !$('ai-badge').classList.contains('is-thinking');
      out.words = ["Your phone's AI is reading…", 'Reading your receipt', 'Sorting your statement', 'Checking tax relief', 'Hide'].every((k) => !!I18N.tables.ms[k] && !!I18N.tables.zh[k]);
    } finally {
      await closed();
      window.Capacitor = keepCap;
      Object.assign(state, { aiEnabled: snap.en, aiIntroSeen: snap.seen });
      aiStatusCache = null;
      save(); renderAll(); renderAiBadge();
    }
    return out;
  }, reduced);
  const th = await sheet(false);
  check('AI sheet: a call you wait on (receipt) opens #ai-think, aria-busy, "Reading your receipt", the mark flies out of the badge and counts',
    th.fgOpen && th.busy === 'true' && th.task === 'Reading your receipt' && th.title === "Your phone's AI is reading…" && th.lifted === th.fromBadge && th.flying && th.bigBead === 'ai-sp-el1', JSON.stringify(th));
  check('AI sheet: a fast call still shows it for its minimum, then it floats back and the badge glyph returns',
    th.stillOpenAtMin && th.closedAfter && th.shownFor >= 700 && th.landed, JSON.stringify(th));
  check('AI sheet: a background call (bank alert) only moves the badge, never opens the sheet', th.bgThinking && !th.bgOpen, JSON.stringify(th));
  check('AI sheet: the hard timeout closes it and stops the badge', th.toOpen && th.toClosed && th.toBadge, JSON.stringify(th));
  check('AI sheet: Escape hides it while the call carries on; the result still lands and it does not come back',
    th.escOpen && th.escClosed && th.escStillThinking && th.escResult === 9.9 && th.escStaysShut, JSON.stringify(th));
  check('AI sheet: its words have Malay and Chinese rows', th.words);
  await page.emulateMedia({ reducedMotion: 'reduce' });
  const thr = await sheet(true);
  await page.emulateMedia({ reducedMotion: 'no-preference' });
  check('AI sheet: reduced motion opens it with no flight (the mark breathes, beads still) and still closes',
    thr.fgOpen && !thr.flying && thr.markAnim === 'ai-badge-breathe' && thr.bigBead === 'none' && thr.closedAfter, JSON.stringify(thr));
}

/* ── Bank statement import, read on the phone (1.57.0) ─────────────────────
   Synthetic statements only (tests/fixtures/statement-pdfs.mjs): invented
   names and numbers in each bank's layout. Real statements never enter the repo. */
{
  const b64 = (pages, opts) => buildPdf(pages, opts).toString('base64');
  const parseIt = (data, pw) => S(async ({ data, pw }) => {
    const bin = Uint8Array.from(atob(data), (c) => c.charCodeAt(0));
    try {
      const read = await readStatementPdf(bin.buffer, pw);
      const p = parseStatement(read); const r = reconcileStatement(p);
      return { layout: p.layout, bank: p.bank, kind: p.kind, status: r.status, problems: r.problems.map((x) => `${x.what}@${x.page}`),
        rows: p.rows.map((x) => [x.date, x.payee, x.amount, x.dir].join('|')) };
    } catch (e) { return { error: e.code || e.message }; }
  }, { data, pw });
  const F = STATEMENT_FIXTURES;
  const mb = await parseIt(b64(F.maybankCard()));
  check('statement: Maybank card layout → 7 rows (dd/mm dates, CR credits, location column dropped), and it checks out',
    mb.layout === 'maybank-card' && mb.kind === 'card' && mb.status === 'ok' && mb.rows.length === 7
    && mb.rows[0] === '2026-09-15|KEDAI RUNCIT MAJU|23.4|debit' && mb.rows.includes('2026-09-29|ALI BIN ABU|800|credit') && mb.rows.includes('2026-10-07|CASH REBATE|5.4|credit'), JSON.stringify(mb));
  const pb = await parseIt(b64(F.publicBankCard()));
  check('statement: Public Bank card layout → 4 rows (DD MON dates, posting-date-only charges, wrapped lines), and it checks out',
    pb.layout === 'pbb-card' && pb.status === 'ok' && pb.rows.length === 4 && pb.rows[3] === '2026-10-20|FINANCE CHARGE-18.00%|12.8|debit', JSON.stringify(pb));
  const al = await parseIt(b64(F.allianceCard()));
  check('statement: Alliance Bank card layout → 5 rows across two accounts (undated interest on the statement date), and it checks out',
    al.layout === 'alliance-card' && al.status === 'ok' && al.rows.length === 5 && al.rows.includes('2026-10-18|INTEREST ON RETAIL TRANSACTION|30|debit'), JSON.stringify(al));
  const cb = await parseIt(b64(F.cimbCard()));
  check('statement: CIMB card history → 4 rows from multi-line blocks, debit/credit by column; no balances printed, so nothing to check',
    cb.layout === 'cimb-card' && cb.status === 'none' && cb.rows.length === 4 && cb.rows[1] === '2026-10-03|Ewallet Topup Contoh KUALA LUMPUR MY|7.3|debit'
    && cb.rows[0].endsWith('|1250|credit') && cb.rows[2].endsWith('|13.05|credit'), JSON.stringify(cb));
  const gn = await parseIt(b64(F.genericAccount()));
  check('statement: an unknown bank\'s account statement → rows with direction from the running balance, and the balances chain',
    gn.layout === 'generic' && gn.kind === 'account' && gn.status === 'ok' && gn.rows.length === 4 && gn.rows[0] === '2026-10-01|SALARY CONTOH SDN BHD|3000|credit', JSON.stringify(gn));
  // Tampered: one amount changed — the check fails and names the page.
  const tampered = F.maybankCard();
  tampered[1] = tampered[1].map((sg) => (sg[2] === '45.00' ? [sg[0], sg[1], '54.00'] : sg));
  const tp = await parseIt(b64(tampered));
  check('statement: a tampered amount fails the check (totals and closing), flagged by page — nothing is adjusted',
    tp.status === 'mismatch' && tp.problems.some((x) => x.startsWith('debits@')) && tp.problems.some((x) => x.startsWith('closing@')) && tp.rows.includes('2026-10-09|STREAMING CONTOH|54|debit'), JSON.stringify(tp));
  const gnBad = F.genericAccount();
  gnBad[0] = gnBad[0].map((sg) => (sg[2] === '3,954.80' ? [sg[0], sg[1], '3,950.80'] : sg));
  const gb = await parseIt(b64(gnBad));
  check('statement: a running balance that doesn\'t follow is flagged', gb.status === 'mismatch' && gb.problems.some((x) => x.startsWith('balance@')), JSON.stringify(gb));
  const enc = b64(F.maybankCard(), { password: 'rahsia123' });
  const e1 = await parseIt(enc), e2 = await parseIt(enc, 'salah'), e3 = await parseIt(enc, 'rahsia123');
  check('statement: an encrypted PDF asks for its password, says when it is wrong, and opens with the right one',
    e1.error === 'password' && e2.error === 'wrong-password' && e3.status === 'ok' && e3.rows.length === 7, JSON.stringify([e1, e2, e3.status]));

  // The screen, from the Settings entry point (works on the plain web).
  const pickFile = async (pages, name = 'statement.pdf') => {
    await page.setInputFiles('#stmt-file', { name, mimeType: 'application/pdf', buffer: buildPdf(pages) });
    await page.waitForFunction(() => !document.getElementById('stmt-review').hidden || /PDF|statement/.test(document.getElementById('stmt-status').textContent), null, { timeout: 15000 });
  };
  await S(() => {
    state.pro = false; state.proTrialStartedAt = Date.now() - 30 * 864e5; state.statementUsage = { month: '', imports: 0 };
    state.ownAccounts = []; state.pendingTxns = [];
    // Already in Duitful: the Maybank card's first purchase, logged a day later.
    state.dailyExpenses.push({ id: 'stmt-dupe', kind: 'expense', date: '2026-09-16', amount: 23.4, category: 'Food', note: 'Kedai Runcit Maju', createdAt: 1 });
    save(); renderAll();
    document.getElementById('tabbtn-data').click();
  });
  const entry = await S(() => !!document.getElementById('btn-stmt-import') && document.getElementById('btn-stmt-import').getBoundingClientRect().height > 0);
  await page.click('#btn-stmt-import');
  const opened = await S(() => ({ open: document.getElementById('stmt-dialog').open, privacy: document.querySelector('#stmt-dialog .stmt-privacy').textContent }));
  await pickFile(F.maybankCard());
  const rv = await S(() => ({
    summary: document.getElementById('stmt-summary').textContent,
    rows: [...document.querySelectorAll('#stmt-list .stmt-row')].map((li) => ({ on: li.querySelector('input[type=checkbox]').checked, payee: li.querySelector('.stmt-payee').value, tag: li.querySelector('.stmt-tag')?.textContent || '', amt: li.querySelector('.stmt-amt').textContent })),
    count: document.getElementById('stmt-count').textContent,
    free: document.querySelector('#stmt-dialog [data-free-count="statements"]').textContent,
  }));
  check('statement screen: Settings → "Import bank statement" opens it on the web, with "Read on your phone. Nothing is uploaded."',
    entry && opened.open && opened.privacy === 'Read on your phone. Nothing is uploaded.', JSON.stringify(opened));
  check('statement screen: the summary names the bank and says "Checks out ✓"', /^Maybank card · .* · Checks out ✓$/.test(rv.summary), rv.summary);
  check('statement screen: the row already in Duitful (± 1 day, same amount, similar name) is shown unticked as "Already in Duitful"',
    rv.rows[0].payee === 'KEDAI RUNCIT MAJU' && rv.rows[0].on === false && rv.rows[0].tag === 'Already in Duitful', JSON.stringify(rv.rows[0]));
  check('statement screen: the card payment is not counted (a move), the cash rebate is income, purchases are spends',
    rv.rows[3].tag === 'Card payment · not counted' && rv.rows[3].on === false && /^\+/.test(rv.rows[4].amt) && /^−/.test(rv.rows[1].amt), JSON.stringify(rv.rows));
  check('statement screen: the free limit shows before the wall', rv.free === '1 free statement import a month · 1 left' && rv.count === '5 to import', JSON.stringify([rv.free, rv.count]));
  // Cancel: nothing booked, nothing counted.
  await page.click('#stmt-cancel');
  const afterCancel = await S(() => state.statementUsage.imports || 0);
  // Import as a free user: counted once, rows marked from the statement.
  await page.click('#btn-stmt-import');
  await pickFile(F.maybankCard());
  const before = await S(() => ({ d: state.dailyExpenses.length, i: state.income.length }));
  await page.click('#stmt-import');
  const imp1 = await S(() => ({
    closed: !document.getElementById('stmt-dialog').open,
    spends: state.dailyExpenses.filter((e) => e.source === 'statement').map((e) => [e.date, e.amount, e.note].join('|')),
    incomes: state.income.filter((x) => x.source === 'statement').map((x) => [x.month, x.day, x.amount, x.category].join('|')),
    used: state.statementUsage.imports,
  }));
  check('statement import: a cancelled import costs nothing; importing books 4 spends and 1 income marked from the statement, the duplicate and the card payment skipped',
    afterCancel === 0 && imp1.closed && imp1.spends.length === 4 && imp1.incomes.length === 1 && imp1.incomes[0] === '2026-10|7|5.4|Cashback'
    && !imp1.spends.some((x) => x.startsWith('2026-09-15')) && imp1.used === 1, JSON.stringify(imp1));
  // 0 left: the preview still works, Import opens the paywall.
  await page.click('#btn-stmt-import');
  await pickFile(F.publicBankCard());
  const wall = await S(() => {
    const free = document.querySelector('#stmt-dialog [data-free-count="statements"]').textContent;
    const rows = document.querySelectorAll('#stmt-list .stmt-row').length;
    const n = state.dailyExpenses.length;
    document.getElementById('stmt-import').click();
    const out = { free, rows, paywall: document.getElementById('paywall-dialog').open, reason: document.getElementById('paywall-reason').textContent, booked: state.dailyExpenses.length - n, used: state.statementUsage.imports };
    closePaywall();
    return out;
  });
  check('statement import: with 0 left the statement still opens and previews; Import shows the paywall and books nothing',
    wall.rows === 4 && wall.free === '1 free statement import a month · 0 left' && wall.paywall && wall.reason === 'Free imports 1 statement a month. Pro imports every statement.' && wall.booked === 0 && wall.used === 1, JSON.stringify(wall));
  // Pro, and the trial, are unlimited.
  const unlimited = await S(() => {
    const out = {};
    state.pro = true; renderAll();
    out.proOk = canImportStatement(); out.proText = freeCountText('statements');
    const n = state.dailyExpenses.length;
    document.getElementById('stmt-import').click();
    out.proBooked = state.dailyExpenses.length - n; out.usedAfterPro = state.statementUsage.imports;
    state.pro = false; state.proTrialStartedAt = Date.now() - 864e5;
    out.trialOk = canImportStatement();
    state.proTrialStartedAt = Date.now() - 30 * 864e5;
    return out;
  });
  check('statement import: Pro and the trial import without a limit (and Pro\'s imports are not counted)',
    unlimited.proOk && unlimited.proText === '' && unlimited.proBooked > 0 && unlimited.usedAfterPro === 1 && unlimited.trialOk, JSON.stringify(unlimited));
  // Own-account transfers on an account statement are moves.
  const own = await S(async (data) => {
    state.ownAccounts = ['ALI BIN ABU'];
    const bin = Uint8Array.from(atob(data), (c) => c.charCodeAt(0));
    const p = parseStatement(await readStatementPdf(bin.buffer));
    const items = statementItems(p, reconcileStatement(p));
    state.ownAccounts = [];
    return items.map((it) => `${it.payee}|${it.kind}|${it.on}`);
  }, b64(F.genericAccount()));
  check('statement: a transfer to a saved own-account name imports as nothing (a move); salary is income',
    own.includes('TRANSFER TO ALI BIN ABU|move|false') && own.includes('SALARY CONTOH SDN BHD|income|true'), JSON.stringify(own));
  // On-device AI: categories and payees only, never amounts or dates.
  const ai = await S(async (data) => {
    const keepCap = window.Capacitor;
    const asked = [];
    const run = async () => {
      const bin = Uint8Array.from(atob(data), (c) => c.charCodeAt(0));
      const p = parseStatement(await readStatementPdf(bin.buffer));
      const items = statementItems(p, reconcileStatement(p));
      for (const it of items) it.category = '';
      await statementAiSuggest(items);
      return items.filter((it) => it.kind === 'spend').map((it) => `${it.date}|${it.amount}|${it.category}|${it.payee}`);
    };
    window.Capacitor = { isNativePlatform: () => true, getPlatform: () => 'android', Plugins: { DuitfulKit: {
      aiStatus: async () => ({ available: true }),
      aiReadAlert: async (o) => { asked.push(o.text); return { json: JSON.stringify({ direction: 'income', counterparty: 'KEDAI', category: 'groceries', is_promo_or_security: false, amount: 999, date: '2020-01-01' }) }; },
    } } };
    try {
      const on = await run();
      const n = asked.length;
      state.aiEnabled = false;
      const off = await run();
      state.aiEnabled = true;
      return { on, asked: n, off, askedOff: asked.length - n };
    } finally { window.Capacitor = keepCap; }
  }, b64(F.genericAccount()));
  check('statement AI: suggests a category from the app\'s list and a payee the description contains; amounts and dates never change',
    ai.asked >= 1 && ai.on.includes('2026-10-03|45.2|Groceries|KEDAI') && ai.on.every((x) => !/999|2020-01-01/.test(x)), JSON.stringify(ai.on));
  check('statement AI: off in Settings means it is never asked', ai.askedOff === 0 && ai.off.every((x) => x.split('|')[2] === ''), JSON.stringify(ai.off));
  // AI in the background (1.62.1): the sheet shows, tucks into the badge, the
  // badge fills as answers land, the review stays usable, it pauses while the
  // app is away, and Import never waits for it.
  const bg = await S(async (data) => {
    const keepCap = window.Capacitor;
    const snap = { pro: state.pro, en: state.aiEnabled, seen: state.aiIntroSeen, usage: state.statementUsage,
      daily: state.dailyExpenses.slice(), income: state.income.slice(), last: (state.statementLast || []).slice() };
    const $ = (id) => document.getElementById(id);
    const wait = (ms) => new Promise((r) => setTimeout(r, ms));
    const resolvers = [];
    let avail = false;
    const asked = [];
    window.Capacitor = { isNativePlatform: () => true, getPlatform: () => 'android', Plugins: { DuitfulKit: {
      aiStatus: async () => ({ available: avail }),
      aiReadAlert: (o) => { asked.push(o.text); return new Promise((r) => resolvers.push(r)); } } } };
    const answer = (cat, who) => resolvers.shift()({ json: JSON.stringify({ direction: 'spend', counterparty: who || '', category: cat || '', is_promo_or_security: false }) });
    const hiddenDoc = (on) => {
      if (on) Object.defineProperty(document, 'visibilityState', { configurable: true, get: () => 'hidden' });
      else delete document.visibilityState;
      document.dispatchEvent(new Event('visibilitychange'));
    };
    const out = {};
    state.pro = true; state.aiEnabled = true; state.aiIntroSeen = true;
    try {
      openStatementImport();
      const bin = Uint8Array.from(atob(data), (c) => c.charCodeAt(0));
      await statementFromFile(new File([bin], 'bank.pdf', { type: 'application/pdf' }));   // AI not ready yet: rules only
      avail = true;
      await refreshAiStatus();
      // Six spends with no category, as a long statement would have.
      const base = stmtUi.items.filter((it) => it.kind === 'spend');
      for (let i = 0; base.length + i < 6; i++) stmtUi.items.push({ ...base[i % base.length], row: { ...base[i % base.length].row }, payee: base[i % base.length].payee });
      for (const it of stmtUi.items) if (it.kind === 'spend') { it.category = ''; it.ai = false; it.aiAsked = false; }
      renderStatementReview();
      const spends = stmtUi.items.filter((it) => it.kind === 'spend');
      const items = stmtUi.items;
      const run = statementAiSuggest(items, { alive: () => stmtUi.items === items && !!$('stmt-dialog').open, onAnswer: stmtShowAiRow });
      await wait(80);
      out.sheetFirst = $('ai-think').open && !$('ai-think-progress').hidden && $('ai-think-count').textContent === '0 of 6';
      const tucking = () => !$('ai-think').open || $('ai-think').classList.contains('is-out');
      for (let i = 0; i < 160 && !tucking(); i++) await wait(50);   // tucks away after ~1.2s
      const badge = $('ai-badge');
      out.minimised = tucking() && badge.classList.contains('is-thinking') && badge.classList.contains('has-progress');
      for (let i = 0; i < 160 && $('ai-think').open; i++) await wait(50);
      out.stmtOpen = $('stmt-dialog').open;
      // First answer lands in its row, in place.
      const i0 = stmtUi.items.indexOf(spends[0]);
      const li0 = $('stmt-list').querySelector(`[data-stmt-on="${i0}"]`).closest('.stmt-row');
      answer('groceries', 'KEDAI');
      await wait(60);
      out.inPlace = li0.isConnected && li0.querySelector('[data-stmt-cat]').value === 'Groceries' && !!li0.querySelector('.stmt-ai');
      out.progress = badge.style.getPropertyValue('--ai-progress');
      out.label = badge.getAttribute('aria-label');
      out.live = $('ai-live').textContent;
      out.fillOn = getComputedStyle(badge.querySelector('.ai-badge-fill')).opacity;
      // The review stays usable: change a later row yourself; the AI won't overwrite it.
      const i3 = stmtUi.items.indexOf(spends[3]);
      const sel3 = $('stmt-list').querySelector(`[data-stmt-cat="${i3}"]`);
      sel3.value = 'Transport'; sel3.dispatchEvent(new Event('change', { bubbles: true }));
      out.userKept0 = $('stmt-list').querySelector(`[data-stmt-cat="${i3}"]`).value === 'Transport';
      // Tap the busy badge: the sheet comes back with the same progress.
      badge.click();
      await wait(80);
      out.reopened = $('ai-think').open && $('ai-think-count').textContent === '1 of 6' && $('ai-think-progress').style.getPropertyValue('--ai-progress') !== '';
      $('ai-think-hide').click();
      for (let i = 0; i < 40 && $('ai-think').open; i++) await wait(50);
      out.hiddenAgain = !$('ai-think').open;
      // App to the background: the call in flight lands, nothing new starts.
      hiddenDoc(true);
      answer('', '');
      await wait(80);
      out.pausedAsks = asked.length;
      out.pausedPending = resolvers.length;
      hiddenDoc(false);
      await wait(80);
      out.resumedAsks = asked.length;
      answer('groceries', '');                       // spends[2]
      await wait(60);
      // spends[3] was set by hand, so it is skipped; spends[4] is asked next.
      out.skippedUser = asked.length === 4;
      // Import mid-run: never waits for the AI.
      const before = state.dailyExpenses.filter((e) => e.source === 'statement').length;
      out.imported = statementImportNow();
      out.bookedNow = state.dailyExpenses.filter((e) => e.source === 'statement').length - before;
      out.user3 = state.dailyExpenses.filter((e) => e.source === 'statement' && e.category === 'Transport').length;
      while (resolvers.length) answer('groceries', '');
      await run;
      out.done = badge.classList.contains('is-done') && badge.style.getPropertyValue('--ai-progress') === '1';
      out.askedTotal = asked.length;
      await wait(900);
      out.idle = !badge.classList.contains('is-done') && !badge.classList.contains('is-thinking') && !badge.classList.contains('has-progress') && badge.getAttribute('aria-label') === 'On-device AI is on' && $('ai-live').textContent === '';
      for (let i = 0; i < 40 && $('ai-think').open; i++) await wait(50);
      out.sheetShut = !$('ai-think').open;
    } finally {
      if ($('stmt-dialog').open) $('stmt-dialog').close();
      delete document.visibilityState;
      window.Capacitor = keepCap;
      Object.assign(state, { pro: snap.pro, aiEnabled: snap.en, aiIntroSeen: snap.seen, statementUsage: snap.usage,
        dailyExpenses: snap.daily, income: snap.income, statementLast: snap.last });
      aiStatusCache = null;
      save(); renderAll(); renderAiBadge();
    }
    return out;
  }, b64(F.genericAccount()));
  check('statement AI in the background: the sheet shows "0 of 6", then tucks into the header badge, which keeps counting with a progress fill; the review stays open',
    bg.sheetFirst && bg.minimised && bg.stmtOpen, JSON.stringify(bg));
  check('statement AI in the background: an answer fills its row in place (same element, category set, AI tag); the badge fills to 1/6 and says "AI is sorting your statement · 1 of 6" (announcements throttled)',
    bg.inPlace && Math.abs(Number(bg.progress) - 1 / 6) < 0.001 && bg.label === 'AI is sorting your statement · 1 of 6' && /^AI is sorting your statement · [01] of 6$/.test(bg.live) && bg.fillOn === '1', JSON.stringify(bg));
  check('statement AI in the background: tapping the busy badge reopens the sheet with "1 of 6" and a bar; Hide tucks it away again',
    bg.reopened && bg.hiddenAgain, JSON.stringify(bg));
  check('statement AI in the background: the app going to the background pauses it (the call in flight lands, nothing new starts) and it resumes when the app is back',
    bg.pausedAsks === 2 && bg.pausedPending === 0 && bg.resumedAsks === 3, JSON.stringify(bg));
  check('statement AI in the background: a row you changed yourself is kept and never asked about; Import works mid-run and books your choice',
    bg.userKept0 && bg.skippedUser && bg.imported && bg.bookedNow > 0 && bg.user3 === 1, JSON.stringify(bg));
  check('statement AI in the background: after Import it stops asking; the badge plays one "done" (tint full) and goes idle',
    bg.askedTotal <= 4 && bg.done && bg.idle && bg.sheetShut, JSON.stringify(bg));
  await page.emulateMedia({ reducedMotion: 'reduce' });
  const bgRm = await S(async () => {
    const keepCap = window.Capacitor;
    const snap = { en: state.aiEnabled, seen: state.aiIntroSeen };
    state.aiEnabled = true; state.aiIntroSeen = true;
    window.Capacitor = { isNativePlatform: () => true, getPlatform: () => 'android', Plugins: { DuitfulKit: { aiStatus: async () => ({ available: true }) } } };
    const out = {};
    try {
      await refreshAiStatus();
      const b = aiBatchStart({ label: 'Checking tax relief', say: 'AI is checking tax relief', total: 4 });
      aiBatchStep(b, 2);
      const badge = document.getElementById('ai-badge');
      out.fill = getComputedStyle(badge.querySelector('.ai-badge-fill')).display;
      out.label = badge.getAttribute('aria-label');
      out.anim = getComputedStyle(badge).animationName;
      aiBatchEnd(b);
      out.doneAnim = getComputedStyle(badge.querySelector('.ai-badge-fill')).animationName;
      await new Promise((r) => setTimeout(r, 900));
      out.idle = !badge.classList.contains('is-thinking');
    } finally {
      window.Capacitor = keepCap;
      Object.assign(state, { aiEnabled: snap.en, aiIntroSeen: snap.seen });
      aiStatusCache = null; renderAiBadge();
    }
    return out;
  });
  await page.emulateMedia({ reducedMotion: 'no-preference' });
  check('AI progress, reduced motion: no fill and no fill animation, the progress is in words ("AI is checking tax relief · 2 of 4"), the badge breathes',
    bgRm.fill === 'none' && bgRm.label === 'AI is checking tax relief · 2 of 4' && bgRm.anim === 'ai-badge-breathe' && bgRm.doneAnim === 'none' && bgRm.idle, JSON.stringify(bgRm));
  // Words built in script (not markup) go through tr() too: capture cards,
  // the scan sheet's button, the "Matches …" line and the item count.
  const msWords = await S(async () => {
    const keepCap = window.Capacitor, keepLang = I18N.lang;
    const out = {};
    try {
      window.Capacitor = { isNativePlatform: () => true, getPlatform: () => 'android', Plugins: {} };
      await I18N.set('ms');
      out.ai = pendingAiTag({ ai: true });
      out.wrong = pendingWrongBtn({ id: 'x' });
      out.match = receiptAgreeLabel({ agree: ['total', 'payment'], candidates: [{ kind: 'payment', label: 'CASH' }] });
      out.visa = receiptAgreeLabel({ agree: ['total', 'payment'], candidates: [{ kind: 'payment', label: 'VISA 1234' }] });
      out.items = trn(3, '{n} item', '{n} items');
      const keepVal = scanAmount.value; window.scanApplyTarget = '';
      scanAmount.value = '23.40'; updateScanApplyLabel();
      out.apply = scanApply.textContent;
      scanAmount.value = keepVal; updateScanApplyLabel();
    } finally { await I18N.set(keepLang); window.Capacitor = keepCap; }
    return out;
  });
  check('Malay: words built in script are translated — "Dibaca oleh AI telefon anda", "Salah?", "Sama dengan Jumlah & tunai" (a card name stays as printed), "3 barang", "Tambah RM 23.40"',
    /Dibaca oleh AI telefon anda/.test(msWords.ai) && /Salah\?/.test(msWords.wrong) && msWords.match === 'Sama dengan Jumlah & tunai'
    && msWords.visa === 'Sama dengan Jumlah & VISA' && msWords.items === '3 barang' && /^Tambah RM\s?23\.40$/.test(msWords.apply), JSON.stringify(msWords));
  // CSV import cannot reset the monthly count.
  const kept = await S(async () => {
    state.pro = false; state.statementUsage = { month: currentMonthISO(), imports: 1 };
    const csv = toCSV();
    await importCsvFile(new File([csv], 'x.csv', { type: 'text/csv' }), { ask: false });
    return state.statementUsage.imports;
  });
  check('statement import: the monthly count survives a CSV import', kept === 1, String(kept));
  await S(() => {
    document.getElementById('stmt-dialog')?.close();
    state.dailyExpenses = state.dailyExpenses.filter((e) => e.source !== 'statement' && e.id !== 'stmt-dupe');
    state.income = state.income.filter((x) => x.source !== 'statement');
    state.statementUsage = { month: '', imports: 0 };
    state.statementLast = [];
    save(); renderAll();
  });
}

/* ── Scanned statements and photos of pages, read with OCR (1.57.15) ───────
   A PDF with no text layer goes through OCR. The OCR here is a stand-in that
   returns word boxes where the synthetic statement prints its text (one box
   per word, ~Helvetica widths), so the test covers rendering, rebuilding
   rows from boxes, the same layout rules, and the rule that a scan only
   imports when its figures add up. */
{
  const F = STATEMENT_FIXTURES;
  const segsOf = (pages) => pages.map((segs) => segs.map(([x, y, t, size]) => [x, y, t, size || 8]));
  const scanCase = (fixture, edit) => S(async ({ blank, pages, edit }) => {
    const bin = Uint8Array.from(atob(blank), (c) => c.charCodeAt(0));
    const keep = window.stmtOcrImage;
    let page = 0;
    const calls = [];
    // Word boxes in the rendered picture's pixels, from where the PDF would print them.
    window.stmtOcrImage = async (canvas) => {
      const segs = pages[page++] || [];
      calls.push([canvas.width, canvas.height]);
      const k = canvas.width / 595;
      const words = [];
      for (const [x, y, t, size] of segs) {
        let at = x;
        for (const w0 of String(t).split(/ +/)) {
          const w = edit && edit[w0] ? edit[w0] : w0;
          const wpt = w0.length * size * 0.52;
          const cy = 842 - y - size * 0.35;
          words.push({ text: w, x0: at * k, x1: (at + wpt) * k, y0: (cy - size * 0.5) * k, y1: (cy + size * 0.5) * k });
          at += wpt + size * 0.28;
        }
      }
      return { words, width: canvas.width };
    };
    try {
      let noText = null;
      try { await readStatementPdf(bin.buffer); } catch (e) { noText = e.code; }
      const read = await readStatementScanPdf(bin.buffer);
      const parsed = parseStatement(read);
      const recon = reconcileStatement(parsed);
      return { noText, calls, scanned: parsed.scanned, layout: parsed.layout, status: recon.status,
        rows: parsed.rows.map((x) => [x.date, x.amount, x.dir].join('|')),
        bad: [...recon.badRows].map((x) => x.amount) };
    } finally {
      window.stmtOcrImage = keep;
    }
  }, { blank: buildPdf(fixture().map(() => [])).toString('base64'), pages: segsOf(fixture()), edit });
  const text = await S(async (data) => {
    const bin = Uint8Array.from(atob(data), (c) => c.charCodeAt(0));
    const p = parseStatement(await readStatementPdf(bin.buffer));
    return p.rows.map((x) => [x.date, x.amount, x.dir].join('|'));
  }, buildPdf(F.genericAccount()).toString('base64'));
  const gen = await scanCase(F.genericAccount);
  check('statement scan: a PDF with no text layer is rendered page by page and read with OCR into the same rows as the text PDF, and it checks out',
    gen.noText === 'scanned' && gen.calls.length === 1 && gen.calls[0][0] > 1400 && gen.scanned && gen.layout === 'generic'
      && gen.status === 'ok' && JSON.stringify(gen.rows) === JSON.stringify(text) && text.length === 4, JSON.stringify({ gen, text }));
  const mb = await scanCase(F.maybankCard);
  check('statement scan: a two-page Maybank card scan finds its layout and checks out',
    mb.calls.length === 2 && mb.layout === 'maybank-card' && mb.status === 'ok' && mb.rows.length === 7, JSON.stringify(mb));
  const miss = await scanCase(F.genericAccount, { '45.20': '46.20' });
  check('statement scan: a misread digit breaks the running balance and flags that row, never a guessed fix',
    miss.status === 'mismatch' && JSON.stringify(miss.bad) === '[46.2]', JSON.stringify(miss));

  // Through the dialog: blocked while it doesn't add up, imports once corrected.
  const ui = await S(async ({ blank, pages }) => {
    const keep = window.stmtOcrImage;
    const snap = { pro: state.pro, usage: state.statementUsage, d: state.dailyExpenses.length, i: state.income.length };
    state.pro = false; state.statementUsage = { month: '', imports: 0 };
    window.stmtOcrImage = async (canvas) => {
      const k = canvas.width / 595;
      const words = [];
      for (const [x, y, t, size] of pages[0]) {
        let at = x;
        for (const w0 of String(t).split(/ +/)) {
          const w = w0 === '45.20' ? '46.20' : w0;
          const wpt = w0.length * size * 0.52, cy = 842 - y - size * 0.35;
          words.push({ text: w, x0: at * k, x1: (at + wpt) * k, y0: (cy - size * 0.5) * k, y1: (cy + size * 0.5) * k });
          at += wpt + size * 0.28;
        }
      }
      return { words, width: canvas.width };
    };
    const out = {};
    try {
      openStatementImport();
      const bin = Uint8Array.from(atob(blank), (c) => c.charCodeAt(0));
      await statementFromFile(new File([bin], 'scan.pdf', { type: 'application/pdf' }));
      const btn = document.getElementById('stmt-import');
      out.summary = document.getElementById('stmt-summary').textContent;
      out.blocked = btn.disabled;
      out.count = document.getElementById('stmt-count').textContent;
      out.refused = statementImportNow();
      const flagged = document.querySelector('.stmt-row.is-flagged [data-stmt-amt]');
      out.flaggedValue = flagged && flagged.value;
      if (flagged) { flagged.value = '45.20'; flagged.dispatchEvent(new Event('change', { bubbles: true })); }
      out.after = document.getElementById('stmt-import').disabled;
      out.status = stmtUi.recon.status;
      out.imported = statementImportNow();
      out.booked = state.dailyExpenses.filter((e) => e.source === 'statement').map((e) => e.amount).sort((a, b) => a - b);
      // Photos of the pages take the same road.
      const c = document.createElement('canvas'); c.width = 1240; c.height = 1754;
      const g = c.getContext('2d'); g.fillStyle = '#fff'; g.fillRect(0, 0, c.width, c.height);
      window.stmtOcrImage = async (canvas) => ({ words: [], width: canvas.width });
      try { await readStatementPhotos([c.toDataURL('image/png')]); out.photo = 'read'; } catch (e) { out.photo = e.code; }
    } finally {
      window.stmtOcrImage = keep;
      document.getElementById('stmt-dialog')?.close();
      state.dailyExpenses = state.dailyExpenses.filter((e) => e.source !== 'statement');
      state.income = state.income.filter((x) => x.source !== 'statement');
      Object.assign(state, { pro: snap.pro, statementUsage: snap.usage, statementLast: [] });
      save(); renderAll();
    }
    return out;
  }, { blank: buildPdf([[]]).toString('base64'), pages: segsOf(F.genericAccount()) });
  check('statement scan review: says "Read from a scan" and refuses to import while the figures don\'t add up',
    /Read from a scan/.test(ui.summary) && ui.blocked && ui.refused === false && /Fix the figures/.test(ui.count) && ui.flaggedValue === '46.20', JSON.stringify(ui));
  check('statement scan review: correcting the flagged amount re-runs the check, then it imports the user\'s figure',
    ui.after === false && ui.status === 'ok' && ui.imported === true && JSON.stringify(ui.booked) === '[45.2,120,500]', JSON.stringify(ui));
  check('statement scan: a photo with no readable text says so instead of importing anything', ui.photo === 'no-text', JSON.stringify(ui.photo));
}

/* ── Statements every month: easy to find, and a nudge when the next is due (1.57.16) ── */
{
  const r = await S(() => {
    const out = {};
    const keep = { last: state.statementLast };
    try {
      const dlg = document.getElementById('stmt-dialog');
      document.getElementById('btn-stmt-import-daily').click();
      out.fromDaily = dlg.open; dlg.close();
      const f = SEARCH_FEATURES.find((x) => x.title === 'Import bank statement');
      if (f) f.run();
      out.fromSearch = !!f && dlg.open; dlg.close();
      out.settingsLabel = document.getElementById('btn-stmt-import').textContent.trim();
      out.inBackupCard = !!document.getElementById('btn-stmt-import').closest('.card').querySelector('#btn-export');
      // An import is remembered by bank, at the last date it covered; an older one never winds it back.
      state.statementLast = [];
      const day = (n) => { const d = new Date(); d.setDate(d.getDate() + n); return d.toISOString().slice(0, 10); };
      rememberStatement({ layout: 'maybank-card', bank: 'Maybank', kind: 'card', rows: [{ date: day(-50) }, { date: day(-40) }] });
      rememberStatement({ layout: 'maybank-card', bank: 'Maybank', kind: 'card', rows: [{ date: day(-80) }] });
      out.kept = state.statementLast.map((x) => `${x.key}|${x.end === day(-40)}`);
      renderAll();
      const card = document.getElementById('stmt-nudge');
      out.shown = !card.hidden;
      out.title = document.getElementById('stmt-nudge-title').textContent;
      document.getElementById('stmt-nudge-import').click();
      out.importOpens = dlg.open; dlg.close();
      document.getElementById('stmt-nudge-later').click();
      out.afterLater = card.hidden;
      renderAll();
      out.staysHidden = card.hidden;
      // Not due yet: no card, but the phone is told for that morning.
      state.statementLast = [];
      rememberStatement({ layout: 'generic', bank: '', kind: 'account', rows: [{ date: day(-10) }] });
      renderAll();
      out.notYet = card.hidden;
      const rem = statementNativeReminders();
      out.remind = rem.map((n) => [n.title, Math.round((n.at - Date.now()) / 86400000)]);
      out.inBuild = buildReminders(state).some((n) => n.title === 'Your bank statement should be out');
      // Survives a reload of the vault shape.
      out.coerced = coerceStatementLast([{ key: 'x', end: '2026-01-31', bank: 'B', kind: 'card' }, { key: 'bad', end: 'nope' }, null]).length;
    } finally {
      state.statementLast = keep.last || [];
      save(); renderAll();
    }
    return out;
  });
  check('statement import is on All entries and in search, and Settings has it in its own card ("Import bank statement")',
    r.fromDaily && r.fromSearch && r.settingsLabel === 'Import bank statement' && !r.inBackupCard, JSON.stringify(r));
  check('statements every month: an import is remembered per bank at its last date, and an older one never winds it back',
    JSON.stringify(r.kept) === '["maybank-card|true"]', JSON.stringify(r.kept));
  check('statements every month: about a month on, Home asks "Your Maybank card statement should be out"; Import opens the import; Not now asks no more for that statement',
    r.shown && r.title === 'Your Maybank card statement should be out' && r.importOpens && r.afterLater && r.staysHidden, JSON.stringify(r));
  check('statements every month: not due yet means no card, and one reminder for the morning it is due (in the phone\'s reminder list)',
    r.notYet && r.remind.length === 1 && r.remind[0][0] === 'Your bank statement should be out' && r.remind[0][1] >= 22 && r.remind[0][1] <= 24 && r.inBuild && r.coerced === 1, JSON.stringify(r));
}

/* ── Open with Duitful: a PDF or photos shared from another app (1.57.17) ── */
{
  const pdf64 = buildPdf(STATEMENT_FIXTURES.maybankCard()).toString('base64');
  const r = await S(async (pdf64) => {
    const out = {};
    const keepCap = window.Capacitor;
    const keepOcr = window.stmtOcrImage;
    const c = document.createElement('canvas'); c.width = 40; c.height = 40;
    const png64 = c.toDataURL('image/png').split(',')[1];
    let queue = [];
    const readCalls = [];
    let takeCalls = 0;
    window.Capacitor = { isNativePlatform: () => true, getPlatform: () => 'android', Plugins: { DuitfulKit: {
      takeSharedFiles: async () => { takeCalls++; const files = queue; queue = []; return { files }; },
      readSharedFile: async ({ url }) => { readCalls.push(url); return { files: [{ name: 'IMG_1.jpg', mime: 'image/png', base64: png64 }] }; },
    } } };
    const wait = (ms) => new Promise((res) => setTimeout(res, ms));
    try {
      // A statement PDF from the bank app goes straight to the statement review.
      queue = [{ name: 'Statement Oct.pdf', mime: 'application/pdf', base64: pdf64 }];
      await drainSharedFiles();
      for (let i = 0; i < 40 && document.getElementById('stmt-review').hidden; i++) await wait(100);
      out.pdfOpen = document.getElementById('stmt-dialog').open;
      out.pdfSummary = document.getElementById('stmt-summary').textContent;
      document.getElementById('stmt-dialog').close();
      // Nothing waiting: nothing opens.
      await drainSharedFiles();
      out.emptyQuiet = !document.querySelector('dialog[open]');
      // Photos ask: a receipt, or statement pages?
      queue = [{ name: 'a.png', mime: 'image/png', base64: png64 }, { name: 'b.png', mime: 'image/png', base64: png64 }];
      await drainSharedFiles();
      const ask = document.getElementById('shared-in-dialog');
      out.askOpen = ask.open;
      out.askText = document.getElementById('shared-in-what').textContent;
      window.stmtOcrImage = async (cv) => ({ words: [], width: cv.width });
      document.getElementById('shared-in-statement').click();
      for (let i = 0; i < 40 && !/Couldn't read any text/.test(document.getElementById('stmt-status').textContent); i++) await wait(100);
      out.photosToStatement = document.getElementById('stmt-dialog').open && /Couldn't read any text/.test(document.getElementById('stmt-status').textContent);
      document.getElementById('stmt-dialog').close();
      // Cancel forgets them.
      queue = [{ name: 'a.png', mime: 'image/png', base64: png64 }];
      await drainSharedFiles();
      document.getElementById('shared-in-cancel').click();
      out.cancelled = !ask.open && sharedIn.files.length === 0;
      // Anything else is refused with a word.
      queue = [{ name: 'x.txt', mime: 'text/plain', base64: btoa('hi') }];
      await drainSharedFiles();
      out.otherQuiet = !document.querySelector('dialog[open]');
      // iPhone: a file URL from appUrlOpen is read once by DuitfulKit.readSharedFile.
      sharedIn.urls.push('file:///var/mobile/Containers/Data/Application/X/Documents/Inbox/IMG_1.jpg');
      await drainSharedFiles();
      out.iosRead = readCalls.length === 1 && ask.open && sharedIn.urls.length === 0;
      document.getElementById('shared-in-cancel').click();
      out.notFile = sharedUrlIsFile('https://duitful.app/split/#DFS2.x') === false && sharedUrlIsFile('file:///a.pdf') === true;
      out.takeCalls = takeCalls;
    } finally {
      window.Capacitor = keepCap;
      window.stmtOcrImage = keepOcr;
      document.querySelectorAll('dialog[open]').forEach((d) => d.close());
    }
    return out;
  }, pdf64);
  check('open with Duitful: a statement PDF shared from another app opens the statement review',
    r.pdfOpen && /^Maybank card · /.test(r.pdfSummary) && r.emptyQuiet, JSON.stringify(r));
  check('open with Duitful: shared photos ask "receipt or statement pages?"; statement pages go to the import (read with OCR); Cancel forgets them',
    r.askOpen && r.askText === '2 photos shared to Duitful.' && r.photosToStatement && r.cancelled && r.otherQuiet, JSON.stringify(r));
  check('open with Duitful: on iPhone a file URL is read once through DuitfulKit.readSharedFile; split links are not files',
    r.iosRead && r.notFile, JSON.stringify(r));
  const kitSrc = readFileSync(path.join(REPO_ROOT, 'native/duitful-kit/android/DuitfulKitPlugin.java'), 'utf8');
  const swift = readFileSync(path.join(REPO_ROOT, 'native/duitful-kit/ios/Sources/DuitfulKitPlugin/DuitfulKitPlugin.swift'), 'utf8');
  const iosPatch = readFileSync(path.join(REPO_ROOT, 'scripts/patch-ios.mjs'), 'utf8');
  const { SHARE_FILTERS } = await import(pathToFileURL(path.join(REPO_ROOT, 'scripts/install-duitful-kit.mjs')).href);
  check('open with Duitful (native): Android accepts SEND of a PDF or image, SEND_MULTIPLE images and VIEW of a PDF, and the plugin hands files over once',
    /action\.SEND"[\s\S]*mimeType="application\/pdf"[\s\S]*mimeType="image\/\*"/.test(SHARE_FILTERS) && /SEND_MULTIPLE[\s\S]*image\/\*/.test(SHARE_FILTERS)
      && /action\.VIEW[\s\S]*scheme="content"[\s\S]*application\/pdf/.test(SHARE_FILTERS)
      && /handleOnNewIntent/.test(kitSrc) && /public void takeSharedFiles/.test(kitSrc) && /shared\.clear\(\)/.test(kitSrc), '');
  check('open with Duitful (native): iPhone declares PDF and image document types (copied, not opened in place) and reads only files inside the app, then deletes them',
    /CFBundleDocumentTypes[\s\S]*com\.adobe\.pdf[\s\S]*public\.image[\s\S]*LSSupportsOpeningDocumentsInPlace[\s\S]*<false\/>/.test(iosPatch)
      && /CAPPluginMethod\(name: "readSharedFile"/.test(swift) && /hasPrefix\(home \+ "\/"\)/.test(swift) && /removeItem\(at: url\)/.test(swift), '');
}

/* ── Monthly recap on Reports: figures from code, AI may only reword (1.58.1) ── */
{
  const r = await S(async () => {
    const out = {};
    const keep = { d: state.dailyExpenses, x: state.expenses, p: state.budgetPools, cap: window.Capacitor, ai: state.aiEnabled };
    const e = (date, amount, category) => ({ id: uid(), kind: 'expense', date, amount, category, note: '' });
    try {
      state.dailyExpenses = [
        e('2026-10-02', 300, 'Food'), e('2026-10-05', 100, 'Groceries'), e('2026-10-20', 999, 'Travel'),
        e('2026-11-02', 280, 'Food'), e('2026-11-06', 220, 'Groceries'), e('2026-11-09', 40, 'Transport'),
      ];
      state.expenses = [{ id: 'b1', name: 'Internet', amount: 129, month: '2026-11', day: 25 }];
      state.budgetPools = [];
      // Mid-month: this month so far against the same days last month (the 20 Oct trip is outside them).
      const f = recapFacts('2026-11-10');
      out.mid = { spent: f.spent, prev: f.prevSpent, top: f.top && f.top.name, rise: f.rise && [f.rise.name, f.rise.delta], bills: f.billsLeft, full: f.full };
      out.midText = recapTemplate(f);
      // The 1st–3rd: last month in full.
      const g = recapFacts('2026-11-02');
      out.early = { month: g.month, full: g.full, spent: g.spent };
      out.none = recapFacts('2026-08-15') === null;
      // The guard: only the facts' numbers, no advice, short.
      const lines = recapFactLines(f);
      out.okGood = recapTextOk('You have spent RM 540 so far this month, RM 140.00 more than last time. Groceries rose the most.', lines);
      out.okInvented = recapTextOk('You spent RM 540.00, about 35% more than last month.', lines);
      out.okAdvice = recapTextOk('You spent RM 540.00. You should cut back on Groceries.', lines);
      // On the card, with a stand-in phone model.
      state.aiEnabled = true;
      let asked = 0;
      const make = (reply) => ({ isNativePlatform: () => true, getPlatform: () => 'android', Plugins: { DuitfulKit: {
        aiStatus: async () => ({ available: true }),
        aiWriteRecap: async () => { asked++; return { json: reply }; },
      } } });
      const today = todayISO();
      const thisM = today.slice(0, 7), lastM = shiftMonth(thisM, -1);
      state.dailyExpenses = [e(`${lastM}-01`, 50, 'Food'), e(`${thisM}-01`, 80, 'Food')];
      const facts = recapFacts();
      const allowedNum = recapFactLines(facts).match(/RM\s?[\d,.]+/)[0];
      window.Capacitor = make(`A calm month: ${allowedNum} on Food.`);
      recapAiCache.clear();
      renderRecap();
      await new Promise((res) => setTimeout(res, 300));
      out.aiText = document.getElementById('recap-text').textContent;
      out.aiTag = !document.getElementById('recap-tag').hidden;
      out.template = recapTemplate(facts);
      window.Capacitor = make('You spent RM 12,345.67 and should save more.');
      recapAiCache.clear();
      renderRecap();
      await new Promise((res) => setTimeout(res, 300));
      out.badFallsBack = document.getElementById('recap-text').textContent === out.template && document.getElementById('recap-tag').hidden;
      state.aiEnabled = false;
      recapAiCache.clear();
      const before = asked;
      renderRecap();
      await new Promise((res) => setTimeout(res, 200));
      out.offNotAsked = asked === before;
      out.cardShown = !document.getElementById('recap-card').hidden;
    } finally {
      window.Capacitor = keep.cap;
      Object.assign(state, { dailyExpenses: keep.d, expenses: keep.x, budgetPools: keep.p, aiEnabled: keep.ai });
      recapAiCache.clear();
      save(); renderAll();
    }
    return out;
  });
  check('recap: mid-month compares the same days of last month, names the top category and the biggest rise, and counts bills still due',
    r.mid.spent === 540 && r.mid.prev === 400 && r.mid.top === 'Food' && JSON.stringify(r.mid.rise) === '["Groceries",120]' && r.mid.bills === 1 && !r.mid.full
      && /spent .*540\.00 so far/.test(r.midText) && /140\.00 more than the same days of October 2026/.test(r.midText) && /Groceries rose the most, up .*120\.00/.test(r.midText) && /1 recurring bill is still due/.test(r.midText),
    JSON.stringify(r));
  check('recap: on the 1st–3rd it recaps last month in full; a month with no spending gets no card',
    r.early.month === '2026-10' && r.early.full && r.early.spent === 1399 && r.none, JSON.stringify(r.early));
  check('recap guard: the phone\'s AI text is kept only if every number is one of the facts\' and it gives no advice',
    r.okGood && !r.okInvented && !r.okAdvice, JSON.stringify([r.okGood, r.okInvented, r.okAdvice]));
  check('recap on Reports: a good AI rewording shows with "Written by your phone\'s AI"; an invented figure or advice falls back to the template; AI off never asks',
    r.cardShown && /^A calm month: /.test(r.aiText) && r.aiTag && r.badFallsBack && r.offNotAsked, JSON.stringify(r));
}

