// v1.55: make scan + split just work (Phase 1 fixes).
{
  const p1 = await S(async () => {
    const out = {};
    // A card-paid receipt: the VISA line restates the total, it is not an item.
    const card = splitParseReceiptItems('POPULAR BOOKSTORE\nNovel A 30.00\nAtlas B 74.90\nTOTAL 104.90\nVISA 104.90\nAPPROVAL CODE 0412\nTNG eWallet 0.00');
    out.cardItems = card.items.map((i) => i.name + ':' + i.price);
    // Split -> Request -> Split keeps everyone and the bill.
    splitOpenCompose({ mode: 'split', title: 'Steamboat', total: 150 });
    splitCompose.people = [{ key: 'a', name: 'Ali', amount: 0 }, { key: 'b', name: 'Mei', amount: 0 }, { key: 'c', name: 'Raju', amount: 0 }];
    splitRenderCompose();
    splitSetMode('request'); splitSetMode('split');
    out.afterSwitch = { n: splitCompose.people.length, total: splitCompose.total, names: splitCompose.people.map((p) => p.name).join(',') };
    // Equal split is automatic: 150 / 4 each, and a new total re-divides.
    out.autoEach = splitCompose.people.map((p) => p.amount);
    const totalEl = document.querySelector('#split-compose-body [name=total]');
    totalEl.value = '200'; totalEl.dispatchEvent(new Event('input', { bubbles: true }));
    out.autoAfterTotal = [...document.querySelectorAll('#split-compose-body [data-person-amount]')].map((e) => e.value);
    // Typing a share by hand stops it.
    const a0 = document.querySelector('#split-compose-body [data-person-amount]');
    a0.value = '80'; a0.dispatchEvent(new Event('input', { bubbles: true }));
    totalEl.value = '240'; totalEl.dispatchEvent(new Event('input', { bubbles: true }));
    out.manualKept = document.querySelector('#split-compose-body [data-person-amount]').value;
    document.getElementById('split-compose-dialog').close();
    // A late joiner shares the shared dishes only.
    splitOpenCompose({ mode: 'split', title: 'Lunch' });
    splitCompose.method = 'item';
    splitCompose.people = [{ key: 'a', name: 'Ali', amount: 0 }];
    splitCompose.items = [{ key: 'i1', name: 'Nasi', price: 10, who: ['a'] }, { key: 'i2', name: 'Teh', price: 6, who: ['you', 'a'] }];
    splitRenderCompose();
    document.querySelector('#split-compose-body [data-action="split-person-add"]').click();
    const newKey = splitCompose.people[1].key;
    out.lateJoin = splitCompose.items.map((it) => it.who.includes(newKey));
    document.getElementById('split-compose-dialog').close();
    // Scanning from the composer leaves it open underneath.
    const realScan = window.startReceiptScan;
    window.startReceiptScan = () => {};
    splitOpenCompose({ mode: 'split', title: 'Kept' });
    splitStartScan();
    out.composerStillOpen = document.getElementById('split-compose-dialog').open && splitCompose && splitCompose.title === 'Kept';
    window.startReceiptScan = realScan;
    window.scanApplyTarget = null;
    document.getElementById('split-compose-dialog').close();
    // A blank read says so and keeps Add off.
    openScanDialog();
    scanAmount.value = ''; scanOriginalAmount = null;
    scanResult.hidden = false; scanApply.hidden = false;
    await applyScanConversion();
    out.blank = { status: scanStatus.textContent, disabled: scanApply.disabled };
    closeScanDialog();
    out.quota = ocrScansLeftText();
    return out;
  });
  check('a card-paid receipt keeps its items and never books the VISA line as one',
    JSON.stringify(p1.cardItems) === JSON.stringify(['Novel A:30', 'Atlas B:74.9']), JSON.stringify(p1.cardItems));
  check('Split → Request → Split keeps all three people and the RM 150 bill',
    p1.afterSwitch.n === 3 && p1.afterSwitch.total === 150 && p1.afterSwitch.names === 'Ali,Mei,Raju', JSON.stringify(p1.afterSwitch));
  check('an equal split divides itself among everyone plus you (150 ÷ 4)',
    p1.autoEach.every((a) => a === 37.5), JSON.stringify(p1.autoEach));
  check('a new total re-divides the equal split on the spot',
    p1.autoAfterTotal.every((v) => v === '50.00'), JSON.stringify(p1.autoAfterTotal));
  check('a share typed by hand is never overwritten',
    p1.manualKept === '80', p1.manualKept);
  check('a late joiner shares the shared dishes, not one already narrowed to someone',
    JSON.stringify(p1.lateJoin) === JSON.stringify([false, true]), JSON.stringify(p1.lateJoin));
  check('scanning from the split composer leaves the bill open underneath',
    p1.composerStillOpen === true);
  check('a blank read asks for the total and keeps Add off',
    /Couldn't find the total/.test(p1.blank.status) && p1.blank.disabled === true, JSON.stringify(p1.blank));
  check('free users see how many scans are left; Pro and the trial see nothing',
    typeof p1.quota === 'string', p1.quota);
}


// v1.55.1: a real photo (Nyonya Tingkat, Bangsar) on a tiled table. The
// browser reader got single digits wrong all over it; the receipt's own sums
// put the total right.
{
  const ny = await S(async () => {
    const raw = [
      'NYONYA TINGKAT, BANGSAR UTAMA', 'NYONYA NOOK SDN BHD',
      '2 LS02 NYONYA ASAM LAKSA (18.90) 37.80', '1 LS05 NASI KERABU AYAM PERCIK 26.90',
      '1 LS03 CHICKEN HOR FUN SOUP 19.90', '1 LS05 NASI KERABU AYAM PERCIK 26.98',
      '1 LS02 NYONYA ASAM LAKSA 18.96', '1 LS04 NASI LEMAK AYAM PENYET 20.96',
      'Subtotal 154.30', 'SERVICE CHARGE (10%) 15.13', 'Bill rounding 0.02',
      'Total (MYR) 166.48', 'VISA 196.45', 'Change 0.00',
    ].join('\n');
    const c = receiptConsensusTotal(raw, 166.48, null);
    const clean = receiptConsensusTotal('Nasi lemak 12.00\nTeh 3.00\nTOTAL 15.00\nVISA 15.00', 15, null);
    // The paper on a patterned table is found and cropped to.
    const cv = document.createElement('canvas'); cv.width = 600; cv.height = 800;
    const x = cv.getContext('2d');
    for (let i = 0; i < 600; i += 40) for (let j = 0; j < 800; j += 40) { x.fillStyle = (i + j) % 80 ? '#1d4fa0' : '#e0a030'; x.fillRect(i, j, 40, 40); }
    x.fillStyle = '#f4f4f2'; x.fillRect(150, 60, 300, 680);
    const crop = receiptFindPaper(cv);
    const whole = document.createElement('canvas'); whole.width = 400; whole.height = 600;
    const wx = whole.getContext('2d'); wx.fillStyle = '#fff'; wx.fillRect(0, 0, 400, 600);
    return {
      value: c && c.value, clean: clean && clean.value,
      near: [receiptDigitsNear(151.3, 154.3), receiptDigitsNear(166.45, 196.45), receiptDigitsNear(166.45, 166.4), receiptDigitsNear(166.45, 177.45)],
      cat: scanGuessCategory('NYONYA NOOK SDN BHD', raw),
      crop: crop && [Math.round(crop.x), Math.round(crop.y), Math.round(crop.w), Math.round(crop.h)],
      noCrop: receiptFindPaper(whole),
    };
  });
  const nyItems = await S(() => {
    const raw = ['NYONYA VOOK SDN BHD', '2 LS02 NYONYA ASAM LAKSA (18.90/ 37.89', 'ea)', '1 L.EOS NASI KERABJ AYAM PERCIK 26.90', '(26.90/ea)',
      '1 LS03 CHICKEN HCR FON SOUP 19.90', '(19.90/ea)', '1 Ls05 NASI KERABU AYAM PERCIK 26.23', '(26.90/ea)', '1 LS02 NYCONYA ASAMLAKSA (18.90/ 18.90', 'ea)',
      '1 LS04 NASI LEMAK AYAM FENYET 20.90', '(20.90/ea)', '7 Qty', 'Subtotal 151.30', 'SERVICE CHARGE (10%) 15.13', 'Eill Tounding 0.02',
      'Total (MYR) 166.45', 'VISA 166.45', 'Change 0.00'].join('\n');
    const x = splitParseReceiptItems(raw);
    return { items: x.items.map((i) => `${i.name}:${i.price}`), sum: x.itemSum, charges: x.charges };
  });
  check('a "2 ×" row with its unit price becomes two plates to tick, each at the unit price',
    nyItems.items.filter((i) => i === 'NYONYA ASAM LAKSA:18.9').length === 2, JSON.stringify(nyItems));
  check('misread item prices are repaired from the printed unit prices and the subtotal (37.89 → 2 × 18.90, 26.23 → 26.90)',
    nyItems.items.length === 7 && nyItems.sum === 151.3, JSON.stringify(nyItems));
  check('"Bill rounding" read as "Eill Tounding" is a charge, not a dish; no menu codes or unit prices in the names',
    Math.abs(nyItems.charges - 15.15) < 0.001 && !nyItems.items.some((i) => /ounding|LS0|\(/i.test(i)), JSON.stringify(nyItems));
  check('a misread total is put right by the receipt\'s own sums (10% service charge → 151.30 + 15.13 + 0.02 = 166.45)',
    ny.value === 166.45, JSON.stringify(ny));
  check('a total the card line agrees with is left exactly as read', ny.clean === 15, JSON.stringify(ny));
  check('"near" means one digit off, or one digit dropped — never two',
    JSON.stringify(ny.near) === '[true,true,true,false]', JSON.stringify(ny.near));
  check('a Nyonya lunch guesses Food, not Bills ("Bill rounding" is on every restaurant receipt)', ny.cat === 'Food', ny.cat);
  check('the receipt is cropped out of a patterned table, and a photo that is all receipt is left whole',
    ny.crop && Math.abs(ny.crop[0] - 150) < 20 && Math.abs(ny.crop[2] - 300) < 30 && Math.abs(ny.crop[1] - 60) < 20 && ny.noCrop === null, JSON.stringify(ny));
}

// iCloud on the web: CloudKit JS against the same private record the
// iPhone app writes. Off without a web token; with one, Sign in with Apple
// ID, then back up and restore through a stand-in CloudKit.
{
  const ck = await S(async () => {
    window.ICLOUD_WEB_CONFIG = { apiToken: '' };
    const out = { offWithoutToken: !ICloudSync.isConfigured() && !ICloudSync.isWeb() };
    const store = {}; const saves = [];
    let signIn;
    const db = {
      async fetchRecords(names) {
        const r = store[names[0]];
        if (!r) return { hasErrors: true, errors: [{ ckErrorCode: 'NOT_FOUND' }] };
        return { records: [{ recordName: names[0], recordChangeTag: r.tag, fields: { payload: { value: { downloadURL: 'https://cvws.icloud-content.com/B/' + r.tag + '/${f}' } } } }] };
      },
      async saveRecords(recs) {
        if (db.throwNext) { const e = db.throwNext; db.throwNext = null; throw e; }
        const rec = recs[0]; saves.push({ tag: rec.recordChangeTag || null, type: rec.recordType, blobType: rec.fields.payload.value.type });
        const cur = store[rec.recordName];
        if (cur && rec.recordChangeTag !== cur.tag) return { hasErrors: true, errors: [{ ckErrorCode: 'CONFLICT' }] };
        store[rec.recordName] = { tag: 't' + saves.length, text: await rec.fields.payload.value.text() };
        return { records: [rec] };
      },
    };
    const container = {
      privateCloudDatabase: db,
      setUpAuth: async () => null,
      whenUserSignsIn: () => new Promise((res) => { signIn = res; }),
      whenUserSignsOut: () => new Promise(() => {}),
      signOut: async () => {},
    };
    let configured = null;
    const realFetch = window.fetch;
    out.fetched = [];
    window.fetch = async (url, o) => {
      const m = /^https:\/\/cvws\.icloud-content\.com\/B\/(t\d+)\/(.*)$/.exec(String(url));
      if (!m) return realFetch(url, o);
      out.fetched.push(m[2]);
      const r = Object.values(store).find((x) => x.tag === m[1]);
      return new Response(r ? r.text : '', { status: r ? 200 : 404 });
    };
    window.CloudKit = { configure: (c) => { configured = c; }, getDefaultContainer: () => container };
    window.ICLOUD_WEB_CONFIG = { apiToken: 'test-token' };
    out.isWeb = ICloudSync.isWeb();
    out.before = await ICloudSync.prepareSignIn();
    out.container = configured && configured.containers[0].containerIdentifier;
    out.buttonsBound = configured && configured.containers[0].apiTokenAuth.signInButton.id;
    signIn({ userRecordName: '_u' });
    await new Promise((r) => setTimeout(r, 20));
    out.signedIn = ICloudSync.isSignedIn();
    const rec = { iv: 'abc', ct: 'def' };
    await ICloudSync.uploadEncryptedRecord(rec, { savedBy: 'web' });
    await ICloudSync.uploadEncryptedRecord({ iv: 'x', ct: 'y' }, { savedBy: 'web' });
    out.saves = saves;
    // A failed asset upload: CloudKit JS throws a CKError whose message is a
    // long dump. The user sees one short line instead.
    const inner = { ckErrorCode: 'NETWORK_ERROR', message: 'NETWORK_ERROR' };
    db.throwNext = Object.assign(new Error('UNEXPECTED_SERVER_RESPONSE: [CKError ckErrorCode: NETWORK_ERROR isCKError: true ...]'), { ckErrorCode: 'UNEXPECTED_SERVER_RESPONSE', isCKError: true, inner });
    try { await ICloudSync.uploadEncryptedRecord({ iv: 'z', ct: 'z' }, {}); out.thrownMsg = 'no throw'; }
    catch (e) { out.thrownMsg = e.message; }
    // A fresh sign-in drops the cached read, so the restore really fetches.
    signIn({ userRecordName: '_u' });
    await new Promise((r) => setTimeout(r, 20));
    const meta = await ICloudSync.getRemoteMeta();
    out.meta = meta && meta.appProperties.savedBy;
    out.back = await ICloudSync.downloadEncryptedRecord();
    // The card shows Apple's button on the web, not "sign in from Settings".
    renderDriveCard();
    out.card = {
      block: !document.getElementById('icloud-backup').hidden,
      signOutBox: !document.getElementById('apple-sign-out-wrap').hidden,
      backUpHidden: getComputedStyle(document.getElementById('btn-icloud-sync-now')).display === 'none',
      autoHidden: getComputedStyle(document.getElementById('icloud-auto').closest('label')).display === 'none',
      restoreShown: getComputedStyle(document.getElementById('btn-icloud-restore')).display !== 'none',
      noAutoPush: !cloudActive('icloud'),
      line: document.getElementById('icloud-last-synced').textContent,
    };
    await ICloudSync.signOut();
    out.afterSignOut = ICloudSync.isSignedIn();
    renderDriveCard();
    out.card.signInBox = !document.getElementById('apple-sign-in-wrap').hidden;
    out.card.recheckHidden = document.getElementById('btn-icloud-recheck').hidden;
    out.card.why = document.getElementById('icloud-off-why').textContent;
    // The start screen offers Restore from iCloud on the web too, and moves
    // Apple's Sign in button there when it's tapped.
    renderLockRestore();
    out.lock = { btn: !document.getElementById('btn-setup-restore-icloud').hidden };
    lockAppleSignIn(true);
    out.lock.moved = document.getElementById('apple-sign-in-button').parentElement.id;
    lockAppleSignIn(false);
    out.lock.back = document.getElementById('apple-sign-in-button').parentElement.id;
    window.fetch = realFetch;
    window.ICLOUD_WEB_CONFIG = { apiToken: '' };
    out.offAgain = !ICloudSync.isConfigured();
    delete window.CloudKit;
    renderDriveCard();
    return out;
  });
  check('the shipped web iCloud config carries a CloudKit web token for the iPhone app\'s container',
    /apiToken: "[0-9a-f]{64}"/.test(readFileSync(path.join(REPO_ROOT, 'app/icloud-sync.js'), 'utf8')));
  check('web iCloud is off until a CloudKit web token is set, and the iPhone app\'s container is the one used',
    ck.offWithoutToken && ck.isWeb && ck.before === false && ck.container === 'iCloud.com.aydiljoe.duitful' && ck.buttonsBound === 'apple-sign-in-button' && ck.offAgain, JSON.stringify(ck));
  check('web iCloud: after Sign in with Apple ID it backs up (second save carries the change tag) and restores the same encrypted record',
    ck.signedIn && ck.saves.length === 2 && ck.saves[0].tag === null && ck.saves[1].tag === 't1' && ck.saves[0].type === 'Backup'
      && ck.back && ck.back.iv === 'x' && ck.meta === 'web' && ck.fetched[0] === 'duitful-backup.json', JSON.stringify(ck));
  check('web iCloud: the upload is an untyped Blob (no CORS preflight), and a thrown CloudKit error reads as one short line',
    ck.saves.every((x) => x.blobType === '') && /^Couldn't save to iCloud\b[^\[]*Check your connection\.$/.test(ck.thrownMsg) && ck.thrownMsg.length < 100, JSON.stringify({ saves: ck.saves, msg: ck.thrownMsg }));
  check('web iCloud is restore-only: no Back up now, no auto-backup switch, no automatic pushes; Restore stays',
    ck.card.backUpHidden && ck.card.autoHidden && ck.card.restoreShown && ck.card.noAutoPush && /Google Drive or CSV/.test(ck.card.line), JSON.stringify(ck.card));
  check('web start screen: Restore from iCloud shows, and Apple\'s Sign in button moves there and back',
    ck.lock && ck.lock.btn && ck.lock.moved === 'lock-icloud-tile' && ck.lock.back === 'apple-sign-in-wrap', JSON.stringify(ck.lock));
  check('web iCloud card: Apple\'s Sign in button (no "Check again"), Sign out once signed in',
    ck.card.block && ck.card.signOutBox && !ck.afterSignOut && ck.card.signInBox && ck.card.recheckHidden && /Apple ID/.test(ck.card.why), JSON.stringify(ck.card));
}

// The one-time rating ask: more good moments than the last debt, and a
// Rate Duitful link in Settings.
{
  const rv = await S(async () => {
    const snap = JSON.stringify(state);
    const out = {};
    goalsSeen = null; reviewMomentNow();
    state.savings.push({ id: 'rv-goal', name: 'Rv', target: 100, current: 50 });
    reviewMomentNow();
    state.savings.find((g) => g.id === 'rv-goal').current = 100;
    out.goal = reviewMomentNow();
    out.goalOnce = reviewMomentNow();
    Object.assign(state, coerceState(JSON.parse(snap)));
    goalsSeen = null; reviewMomentNow();
    // Habit: three weeks in, ten logged days.
    state.firstRunAt = Date.now() - 22 * 86400000;
    state.budgetPools = (state.budgetPools || []).filter((p) => p.system === 'debt');
    const base = new Date(); base.setDate(1);
    for (let i = 0; i < 10; i++) {
      const d = new Date(Date.now() - i * 86400000).toISOString().slice(0, 10);
      state.dailyExpenses.push({ id: 'rv-d' + i, date: d, amount: 1, name: 'x' });
    }
    out.habit = reviewMomentNow();
    state.firstRunAt = Date.now();
    out.tooSoon = reviewMomentNow();
    Object.assign(state, coerceState(JSON.parse(snap)));
    renderAll();
    renderRateLink();
    const a = document.getElementById('btn-rate-app');
    out.link = { shown: !a.hidden, href: a.getAttribute('href') };
    // In the iPhone / iPad app the same link opens the App Store's review sheet.
    const keep = window.Capacitor;
    window.Capacitor = { isNativePlatform: () => true, getPlatform: () => 'ios', Plugins: {} };
    try { renderRateLink(); out.iosLink = { shown: !a.hidden, href: a.getAttribute('href'), target: a.getAttribute('target') }; }
    finally { window.Capacitor = keep; renderRateLink(); }
    return out;
  });
  check('rating ask: a goal reaching its target is a moment, once', rv.goal === 'goal' && rv.goalOnce !== 'goal', JSON.stringify(rv));
  check('rating ask: three weeks in with ten logged days is a moment, not before', rv.habit === 'habit' && rv.tooSoon === '', JSON.stringify(rv));
  check('Settings has Rate Duitful linking to the Play listing (off Apple devices)',
    rv.link.shown && /play\.google\.com\/store\/apps\/details\?id=com\.aydiljoe\.duitful/.test(rv.link.href), JSON.stringify(rv.link));
  check('Rate Duitful in the iPhone / iPad app opens the App Store review page (a new-window link, which the iOS shell hands to the App Store)',
    rv.iosLink.shown && rv.iosLink.href === 'https://apps.apple.com/app/id6827191645?action=write-review' && rv.iosLink.target === '_blank', JSON.stringify(rv.iosLink));
}

// Deleting is instant with Undo on the toast; alerts are toasts now.
{
  const un = await S(async () => {
    const before = state.savings.length;
    state.savings.push({ id: 'undo-probe', name: 'Undo Probe Goal', target: 1000, current: 100 });
    save(); renderAll();
    const btn = document.createElement('button');
    btn.dataset.action = 'save-delete'; btn.dataset.id = 'undo-probe';
    document.body.appendChild(btn);
    let asked = false; const realConfirm = window.confirm; window.confirm = () => { asked = true; return true; };
    btn.click();
    window.confirm = realConfirm; btn.remove();
    const gone = !state.savings.some((g) => g.id === 'undo-probe');
    const toastEl = document.getElementById('toast');
    const msg = toastEl.textContent;
    toastEl.querySelector('.toast-action')?.click();
    const back = state.savings.some((g) => g.id === 'undo-probe');
    state.savings = state.savings.filter((g) => g.id !== 'undo-probe'); save(); renderAll();
    notify('Hello toast');
    return { asked, gone, msg, back, n: state.savings.length === before, toast: document.getElementById('toast').textContent };
  });
  check('delete: no "are you sure", gone at once, Undo on the toast brings it back',
    !un.asked && un.gone && /Deleted Undo Probe Goal/.test(un.msg) && un.back && un.n, JSON.stringify(un));
  check('notify() shows a toast instead of an alert box', /Hello toast/.test(un.toast), un.toast);
  const src = readFileSync(path.join(REPO_ROOT, 'app/script.js'), 'utf8');
  check('the app no longer uses alert() or prompt() boxes',
    !/(?<![\w.])alert\(/.test(src) && !/(?<![\w.])prompt\(/.test(src));
}

// Announcements can target Apple web users ("web-apple"), and the iPhone
// app is "ios", not "android".
{
  const an = await S(() => {
    const realNative = window.isNative, realPlat = window.nativePlatform;
    const desc = Object.getOwnPropertyDescriptor(Navigator.prototype, 'userAgent');
    const ua = (s) => Object.defineProperty(navigator, 'userAgent', { value: s, configurable: true });
    const msg = (platforms) => ({ id: 'test-' + Math.random(), enabled: true, platforms });
    const out = {};
    ua('Mozilla/5.0 (iPhone; CPU iPhone OS 18_0 like Mac OS X) AppleWebKit/605.1.15 Version/18.0 Mobile/15E148 Safari/604.1');
    out.iphoneWeb = [announcePlatforms(), announceApplies(msg(['web-apple'])), announceApplies(msg(['web']))];
    ua('Mozilla/5.0 (Linux; Android 14) AppleWebKit/537.36 Chrome/126.0 Mobile Safari/537.36');
    out.androidWeb = [announcePlatforms(), announceApplies(msg(['web-apple'])), announceApplies(msg(['web']))];
    window.isNative = () => true; window.nativePlatform = () => 'ios';
    out.iosApp = [announcePlatforms(), announceApplies(msg(['android'])), announceApplies(msg(['ios']))];
    window.isNative = realNative; window.nativePlatform = realPlat;
    delete navigator.userAgent;
    if (desc) Object.defineProperty(Navigator.prototype, 'userAgent', desc);
    return out;
  });
  check('announcements: "web-apple" reaches a browser on an iPhone but not on Android; the iPhone app is "ios", not "android"',
    JSON.stringify(an) === JSON.stringify({
      iphoneWeb: [['web', 'web-apple'], true, true],
      androidWeb: [['web'], false, true],
      iosApp: [['ios'], false, true],
    }), JSON.stringify(an));
  const feed = JSON.parse(readFileSync(path.join(REPO_ROOT, 'announcements.json'), 'utf8'));
  const appleMsg = feed.messages.find((m) => m.id === '2026-11-ios-app-icloud');
  check('the "Duitful is on the App Store" message targets Apple web users only (on, or paused until the CSV fix ships), its button counted through /go/appstore/',
    appleMsg && typeof appleMsg.enabled === 'boolean' && JSON.stringify(appleMsg.platforms) === '["web-apple"]'
      && /^https:\/\/duitful\.app\/go\/appstore\/\?utm_source=webapp&/.test(appleMsg.cta_url) && appleMsg.cta_label, JSON.stringify(appleMsg));
}

// The App Store message ("cta_action": "backup-first"): in a browser the
// button opens the move sheet, and the App Store link waits until the CSV
// is saved (or the person says they already moved). Old-style messages and
// the store apps still open the link directly.
{
  const feed = JSON.parse(readFileSync(path.join(REPO_ROOT, 'announcements.json'), 'utf8'));
  const appleMsg = feed.messages.find((m) => m.id === '2026-11-ios-app-icloud');
  check('the App Store message asks for a backup first', appleMsg && appleMsg.cta_action === 'backup-first', JSON.stringify(appleMsg));
  const IPHONE_UA = 'Mozilla/5.0 (iPhone; CPU iPhone OS 18_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.0 Mobile/15E148 Safari/604.1';
  const start = async (seed) => {
    const ctx = await b.newContext({ viewport: { width: 390, height: 844 }, userAgent: IPHONE_UA, acceptDownloads: true });
    const p = await ctx.newPage();
    await p.goto(`${BASE}/app/index.html`);
    await p.waitForTimeout(400);
    await p.click('#btn-start-open');
    await p.waitForTimeout(1200);
    await p.evaluate((seed) => {
      document.querySelectorAll('dialog[open]').forEach((d) => d.close());
      window.__opened = [];
      window.open = (u) => { window.__opened.push(String(u)); return null; };
      if (seed) { state.dailyExpenses.push({ id: 'move-probe', kind: 'expense', date: '2026-11-20', amount: 12.5, category: 'Food', note: 'Probe', createdAt: 1 }); save(); }
    }, seed);
    return { ctx, p };
  };
  const look = (p) => p.evaluate(() => ({
    open: !!document.getElementById('move-dialog').open,
    announce: !!document.getElementById('announce-dialog').open,
    step2Disabled: document.getElementById('move-open').disabled,
    step2Aria: document.getElementById('move-step-app').getAttribute('aria-disabled'),
    step1Done: document.getElementById('move-step-save').classList.contains('is-done'),
    exportShown: getComputedStyle(document.getElementById('move-export')).display !== 'none',
    emptyShown: !document.getElementById('move-empty').hidden,
    skipShown: !document.getElementById('move-skip-wrap').hidden,
    saved: localStorage.getItem('duitful.moveSaved'),
    opened: window.__opened.slice(),
    overflow: (() => { const f = document.querySelector('#move-dialog form'); return f && f.scrollWidth > f.clientWidth + 1; })(),
  }));

  // With data: the button opens the sheet, not the App Store.
  const { ctx, p } = await start(true);
  await p.evaluate((m) => showAnnouncement({ ...m, id: 'move-test-' + Date.now() }), appleMsg);
  await p.click('#announce-cta');
  await p.waitForTimeout(200);
  const a = await look(p);
  check('move sheet: "Get the iPhone app" in the announcement opens the sheet, not the App Store',
    a.open && !a.announce && a.opened.length === 0, JSON.stringify(a));
  check('move sheet: step 2 is disabled until the data is saved, step 1 offers the download and "already moved"',
    a.step2Disabled && a.step2Aria === 'true' && !a.step1Done && a.exportShown && a.skipShown && !a.overflow, JSON.stringify(a));
  await p.click('#move-open', { force: true }).catch(() => {});
  const stillShut = await look(p);
  check('move sheet: tapping the greyed step 2 opens nothing', stillShut.opened.length === 0 && stillShut.open, JSON.stringify(stillShut));
  const [dl] = await Promise.all([p.waitForEvent('download', { timeout: 5000 }), p.click('#move-export')]);
  const csv = await (async () => { const f = await dl.path(); return f ? readFileSync(f, 'utf8') : ''; })();
  await p.waitForTimeout(100);
  const b2 = await look(p);
  check('move sheet: "Download my data (CSV)" downloads the same CSV as Export CSV, with the data in it',
    /^duitful-\d{4}-\d{2}-\d{2}\.csv$/.test(dl.suggestedFilename()) && /^type,name,amount/.test(csv) && /Probe/.test(csv), dl.suggestedFilename());
  check('move sheet: once saved, step 1 is ticked, step 2 is enabled and the device remembers it',
    b2.step1Done && !b2.step2Disabled && b2.step2Aria === 'false' && !b2.skipShown && b2.saved === '1', JSON.stringify(b2));
  await p.click('#move-open');
  await p.waitForTimeout(100);
  const c = await look(p);
  check('move sheet: step 2 opens the App Store link and closes the sheet',
    !c.open && c.opened.length === 1 && c.opened[0] === appleMsg.cta_url, JSON.stringify(c));
  await p.evaluate((u) => openMoveSheet(u), appleMsg.cta_url);
  const d = await look(p);
  check('move sheet: reopening remembers the download (step 2 ready at once)', d.open && !d.step2Disabled && d.step1Done, JSON.stringify(d));

  // "I've already moved my data" unlocks step 2 without a download.
  await p.evaluate(() => { document.getElementById('move-dialog').close(); localStorage.removeItem('duitful.moveSaved'); });
  await p.evaluate((u) => openMoveSheet(u), appleMsg.cta_url);
  const e1 = await look(p);
  await p.click('#move-skip');
  const e2 = await look(p);
  check('move sheet: "I\'ve already moved my data" unlocks step 2 without exporting',
    e1.step2Disabled && !e2.step2Disabled && e2.saved === 'moved', JSON.stringify([e1, e2]));

  // Old-style message (no cta_action): the button opens its link directly.
  await p.evaluate(() => document.getElementById('move-dialog').close());
  await p.evaluate(() => { window.__opened = []; showAnnouncement({ id: 'old-style-' + Date.now(), enabled: true, title: 'Old', body: ['x'], cta_label: 'Go', cta_url: 'https://duitful.app/changelog/' }); });
  await p.click('#announce-cta');
  await p.waitForTimeout(100);
  const f = await look(p);
  check('announcements without cta_action still open their link directly',
    !f.open && f.opened.length === 1 && f.opened[0] === 'https://duitful.app/changelog/', JSON.stringify(f));

  // Inside the store apps: never the sheet, the button is a plain link.
  const n = await p.evaluate((m) => {
    const real = window.isNative;
    window.isNative = () => true;
    window.__opened = [];
    showAnnouncement({ ...m, id: 'native-' + Date.now() });
    document.getElementById('announce-cta').click();
    const sheetAfterCta = document.getElementById('move-dialog').open;
    openMoveSheet(m.cta_url);
    const sheetDirect = document.getElementById('move-dialog').open;
    window.isNative = real;
    return { sheetAfterCta, sheetDirect, opened: window.__opened.slice() };
  }, appleMsg);
  check('move sheet: never inside the native apps (the button just opens the App Store)',
    !n.sheetAfterCta && !n.sheetDirect && n.opened.length === 1, JSON.stringify(n));
  await ctx.close();

  // An empty vault skips step 1.
  const fresh = await start(false);
  await fresh.p.evaluate((u) => openMoveSheet(u), appleMsg.cta_url);
  const g = await look(fresh.p);
  check('move sheet: with nothing in the vault, step 1 is skipped and step 2 is ready',
    g.open && g.step1Done && g.emptyShown && !g.exportShown && !g.step2Disabled && !g.skipShown && g.saved === null, JSON.stringify(g));
  await fresh.ctx.close();
}

// v1.55.3: Google Drive can be tucked away in the iPhone app (App Review
// can't sign in to a Google account from abroad); iCloud stays.
{
  const dh = await S(() => {
    const real = window.DriveSync;
    const shown = () => ({
      provider: !document.getElementById('drive-provider').hidden,
      lockGoogle: !document.getElementById('btn-setup-restore').hidden,
      welcomeRow: !document.getElementById('pro-welcome-drive-row').hidden,
      paywallLine: document.querySelector('.paywall-features li[data-drive-text]').textContent,
    });
    const before = shown();
    const saved = [...document.querySelectorAll('[data-drive], [data-drive-text]')].map((el) => [el, el.hidden, el.textContent]);
    const savedCopy = PAYWALL_COPY.cloudBackup;
    window.DriveSync = Object.assign({}, real, { isHidden: () => true, isConfigured: () => false });
    applyDriveVisibility();
    const after = shown();
    saved.forEach(([el, h, txt]) => { el.hidden = h; if (el.hasAttribute('data-drive-text')) el.textContent = txt; });
    const copy = PAYWALL_COPY.cloudBackup;
    PAYWALL_COPY.cloudBackup = savedCopy;
    window.DriveSync = real;
    return { before, after, copy, webHidden: real.isHidden() };
  });
  check('Drive tucked away on iPhone: no Drive card, no "Restore with Google", Pro welcome and paywall say iCloud only',
    !dh.after.provider && !dh.after.lockGoogle && !dh.after.welcomeRow
      && dh.after.paywallLine === 'Automatic encrypted backup to iCloud' && !/Google/.test(dh.copy), JSON.stringify(dh));
  check('Drive stays on the web (the switch is iPhone-only)', dh.webHidden === false && dh.before.provider, JSON.stringify(dh));
}

// v1.55.2: the confirm sheet. The total is filled in only when the receipt
// backs it (TOTAL line, what was paid, and its own sums); vendor, date,
// category and the items-vs-subtotal check come from receipt-extract.js.
{
  const NY = [
    'NYONYA TINGKAT, BANGSAR UTAMA', 'NYONYA NOOK SDN BHD (1234567-X)', 'Lot 12, Jalan Telawi 3, Bangsar Baru',
    '59100 Kuala Lumpur', 'Tel: 03-2201 1234', 'Date: 03/11/2026 Time: 13:05', 'Table: 12 Pax: 4', 'Order No: 00123',
    '2 LS02 NYONYA ASAM LAKSA (18.90/ea) 37.80', '1 LS05 NASI KERABU AYAM PERCIK 26.90', '1 LS03 CHICKEN HOR FUN SOUP 19.90',
    '1 LS05 NASI KERABU AYAM PERCIK 26.90', '1 LS02 NYONYA ASAM LAKSA 18.90', '1 LS04 NASI LEMAK AYAM PENYET 20.90', '7 Qty',
    'Subtotal 151.30', 'SERVICE CHARGE (10%) 15.13', 'Bill rounding 0.02', 'Total (MYR) 166.45', 'VISA 166.45', 'Change 0.00',
    'Tax & Charges Summary', 'Service Charge 10% Taxable 151.30 15.13', 'Thank you',
  ].join('\n');
  const rx = await S((NY) => {
    const ex = receiptExtract(NY, { today: '2026-11-06' });
    const pick = (t) => { const r = receiptChooseTotal(receiptTotalCandidates(t)); return { v: r.value, c: r.confidence, n: r.candidates.length }; };
    return {
      total: ex.total.value, conf: ex.total.confidence, agree: ex.total.agree, label: receiptAgreeLabel(ex.total),
      vendor: ex.vendor.value, date: ex.date.value, cat: ex.category.value,
      items: { match: ex.items.match, basis: ex.items.basis, sum: ex.items.sum, against: ex.items.against },
      two: pick(NY.replace('VISA 166.45', 'VISA 196.45')),
      none: pick(NY.replace('Total (MYR) 166.45', 'Total (MYR) 166.48').replace('VISA 166.45', 'VISA 196.45').replace('Subtotal 151.30', 'Subtotal 154.30')),
      onlySums: pick('Nasi lemak 12.00\nSubtotal 12.00\nSST 6% 0.72'),
      onlyTotal: pick('KEDAI\nRoti 3.00\nTOTAL 3.00'),
      cash: pick('KEDAI\nRoti 3.00\nTOTAL 18.50\nTUNAI 20.00\nBAKI 1.50'),
      taxBlock: pick('A 10.00\nSubtotal 10.00\nTOTAL 10.00\nCASH 10.00\nTax Summary\nTaxable 10.00 Total 99.00'),
      itemsOff: receiptItemsCheck('Roti 3.00\nTeh 2.00\nSubtotal 6.00\nTOTAL 6.00', 6),
      vendors: [
        receiptVendor('OLD TOWN KOPITIAM SDN BHD (716269-X)\nNo 5 Jalan SS2/24\nTOTAL 12.00').value,
        receiptVendor('MYDIN MOHAMED HOLDINGS BERHAD\n(3184-H)\nTOTAL 12.00').value,
        receiptVendor('BANGS: AR UTAMA\nTOTAL 1.00', { vendors: ['Bangsar Utama'] }).value,
        receiptVendor('NYONYA TINGKAT\nTOTAL 1.00', { vendors: ['Nyonya Tingkat Bangsar'] }).value,
      ],
      cats: [
        receiptCategory('TNB\nBil Elektrik\nJumlah 120.00', {}).value,
        receiptCategory('99 SPEED MART\nBeras 10kg 32.00\nTOTAL 32.00', { vendor: '99 Speed Mart' }).value,
        receiptCategory('KEDAI X\nNasi lemak 12.00\nBill rounding 0.02\nTOTAL 12.00', {}).value,
        receiptCategory('MAXIS BERHAD\nPostpaid 98.00', {}).value,
        receiptCategory('NYONYA TINGKAT\nTOTAL 1.00', { vendor: 'Nyonya Tingkat', history: (v) => (v === 'Nyonya Tingkat' ? 'Dates' : '') }).value,
      ],
    };
  }, NY);
  check('confirm sheet: the Nyonya receipt reads RM 166.45 with all three agreeing (Total, VISA, the sums), high confidence',
    rx.total === 166.45 && rx.conf === 'high' && rx.agree.length === 3 && rx.label === 'Matches Total & VISA', JSON.stringify(rx));
  check('confirm sheet: vendor "Nyonya Tingkat" (the trading name, not the Sdn Bhd), date 3 Nov 2026, category Food',
    rx.vendor === 'Nyonya Tingkat' && rx.date === '2026-11-03' && rx.cat === 'Food', JSON.stringify(rx));
  check('confirm sheet: the items are checked against the printed subtotal (151.30), not the total',
    rx.items.match === true && rx.items.basis === 'subtotal' && rx.items.sum === 151.3, JSON.stringify(rx.items));
  check('total selection: two of three agree → that value, medium confidence', rx.two.v === 166.45 && rx.two.c === 'medium', JSON.stringify(rx.two));
  check('total selection: none agree → no value, every printed figure offered to pick',
    rx.none.v === null && rx.none.c === 'low' && rx.none.n === 3, JSON.stringify(rx.none));
  check('total selection: the sums alone never fill in a total', rx.onlySums.v === null, JSON.stringify(rx.onlySums));
  check('total selection: a lone TOTAL line is used, marked Check', rx.onlyTotal.v === 3 && rx.onlyTotal.c === 'medium', JSON.stringify(rx.onlyTotal));
  check('total selection: cash minus change counts as the payment (20.00 − 1.50 = 18.50)', rx.cash.v === 18.5 && rx.cash.c === 'medium', JSON.stringify(rx.cash));
  check('total selection: nothing under a tax summary block is read as a total', rx.taxBlock.v === 10 && rx.taxBlock.c === 'high', JSON.stringify(rx.taxBlock));
  check('items vs subtotal: a gap is measured (5.00 of items against a 6.00 subtotal)',
    rx.itemsOff.match === false && rx.itemsOff.off === -1, JSON.stringify(rx.itemsOff));
  check('vendor cleanup: registration numbers and Sdn Bhd / Berhad go, a near match to a saved shop is used as saved',
    JSON.stringify(rx.vendors) === JSON.stringify(['Old Town Kopitiam', 'Mydin Mohamed', 'Bangsar Utama', 'Nyonya Tingkat']), JSON.stringify(rx.vendors));
  check('category rules: Bills only for utilities/telcos, Groceries for a mart, Food despite "Bill rounding", the user\'s past pick wins',
    JSON.stringify(rx.cats) === JSON.stringify(['Bills', 'Groceries', 'Food', 'Bills', 'Dates']), JSON.stringify(rx.cats));

  // The sheet itself: a receipt that disagrees with itself shows the
  // figures to pick, never a big wrong number; one control for category;
  // sentence-case badges; the sheet covers the tab bar on a phone.
  const vp0 = page.viewportSize();
  await page.setViewportSize({ width: 390, height: 844 });
  const sheet = await S(async (NY) => {
    document.querySelectorAll('dialog[open]').forEach((d) => d.close());
    const realW = window.getTesseractWorker, realP = window.receiptPreprocessImage, realS = window.receiptSecondOpinion;
    let text = NY;
    window.getTesseractWorker = async () => ({ recognize: async () => ({ data: { text } }) });
    window.receiptPreprocessImage = async () => null;
    window.receiptSecondOpinion = async (p) => ({ parsed: p, used: [] });
    const img = 'data:image/gif;base64,R0lGODlhAQABAAAAACw=';
    const read = () => ({
      amount: scanAmount.value, vendor: scanVendor.value, date: scanDate.value, cat: scanCategory.value,
      conf: document.getElementById('scan-amount-conf').hidden ? '' : document.getElementById('scan-amount-conf').textContent,
      match: document.getElementById('scan-amount-match').hidden ? '' : document.getElementById('scan-amount-match').textContent,
      picks: [...document.querySelectorAll('#scan-amount-pick [data-scan-use]')].map((b) => b.dataset.scanUse),
      items: document.getElementById('scan-items-summary').textContent,
      statusShown: !document.getElementById('scan-status').hidden,
      apply: scanApply.textContent, disabled: scanApply.disabled,
    });
    await runReceiptOcr(img, img, null);
    const good = read();
    await new Promise((res) => setTimeout(res, 450)); // the open animation
    const r = document.getElementById('scan-dialog').getBoundingClientRect();
    const tab = document.querySelector('.bottom-nav, .tabbar, nav.tabs');
    const tr = tab ? tab.getBoundingClientRect() : null;
    good.covers = r.top <= 0 && r.bottom >= innerHeight - 1 && r.left <= 0 && r.right >= innerWidth - 1;
    good.tabUnder = !tr || (tr.top >= r.top && tr.bottom <= r.bottom);
    good.catControls = document.querySelectorAll('#scan-dialog select#scan-category, #scan-dialog .scan-cat-chips').length
      + (document.getElementById('scan-cat-new').hidden ? 0 : 1);
    const cs = getComputedStyle(document.getElementById('scan-vendor-conf'));
    good.badge = { text: document.getElementById('scan-vendor-conf').textContent, tt: cs.textTransform, mono: /mono/i.test(cs.fontFamily) };
    good.rawHidden = document.getElementById('scan-raw-details').hidden;
    closeScanDialog();
    text = NY.replace('Total (MYR) 166.45', 'Total (MYR) 166.48').replace('VISA 166.45', 'VISA 196.45').replace('Subtotal 151.30', 'Subtotal 154.30');
    await runReceiptOcr(img, img, null);
    const bad = read();
    document.querySelector('#scan-amount-pick [data-scan-use="166.48"]')?.click();
    bad.afterPick = { amount: scanAmount.value, apply: scanApply.textContent, pickHidden: document.getElementById('scan-amount-pick').hidden };
    closeScanDialog();
    window.getTesseractWorker = realW; window.receiptPreprocessImage = realP; window.receiptSecondOpinion = realS;
    return { good, bad };
  }, NY);
  await page.setViewportSize(vp0);
  check('sheet: the Nyonya receipt fills RM 166.45 with "✓ Matches Total & VISA" and no Check badge or warning',
    sheet.good.amount === '166.45' && sheet.good.match === '✓ Matches Total & VISA' && sheet.good.conf === '' && !sheet.good.statusShown
      && sheet.good.vendor === 'Nyonya Tingkat' && sheet.good.date === '2026-11-03' && sheet.good.cat === 'Food', JSON.stringify(sheet.good));
  check('sheet: items say they match the subtotal', /✓ match subtotal/.test(sheet.good.items), sheet.good.items);
  check('sheet: covers the whole phone screen, tab bar included', sheet.good.covers && sheet.good.tabUnder, JSON.stringify(sheet.good));
  check('sheet: one category control (chips, More… for the rest), no second dropdown', sheet.good.catControls === 1, String(sheet.good.catControls));
  check('sheet: badges are sentence case in the body font ("✓ From receipt")',
    sheet.good.badge.text === '✓ From receipt' && sheet.good.badge.tt === 'none' && !sheet.good.badge.mono, JSON.stringify(sheet.good.badge));
  check('sheet: raw OCR text is only behind the debug flag', sheet.good.rawHidden === true);
  check('sheet: an unreadable total shows the figures to pick, with no amount filled and Add off',
    sheet.bad.amount === '' && sheet.bad.disabled && JSON.stringify(sheet.bad.picks) === JSON.stringify(['166.48', '196.45', '169.45']), JSON.stringify(sheet.bad));
  check('sheet: picking one fills it and Add says so',
    sheet.bad.afterPick.amount === '166.48' && /166\.48/.test(sheet.bad.afterPick.apply) && sheet.bad.afterPick.pickHidden, JSON.stringify(sheet.bad.afterPick));
}

/* ── 14. itemized split (Phase 2.5, v1.15.0) ────────────────────────────
   Tick who ate what. OCR is prefill, never oracle, so the parser is a pure
   function tested directly against real Malaysian receipt shapes; the
   division is largest-remainder in sen, so "the shares add up to the bill"
   is checked to the last cent on deliberately awkward figures. */

// --- the pure parser: items kept, charges bucketed, summaries dropped ---
const mamakReceipt = [
  'RESTORAN NASI KANDAR ALIF',
  'NO 12, JALAN SS2/24',
  'TEL 03-7877 1234',
  '--------------------------------',
  '1 NASI KANDAR AYAM        12.00',
  '2 TEH TARIK                7.00',
  '1 ROTI CANAI               1.60',
  '--------------------------------',
  'SUBTOTAL                  20.60',
  'SST 6%                     1.24',
  'ROUNDING                   0.01',
  'TOTAL                     21.85',
  'TUNAI                     50.00',
  'BAKI                      28.15',
].join('\n');
const mamakParse = await S((raw) => splitParseReceiptItems(raw), mamakReceipt);
// "2 TEH TARIK 7.00" is two drinks at 3.50, and two people may each want to
// claim one — so a stated quantity now expands into separate tickable rows
// (whole counts up to 4, only when the total divides into clean sen).
check('mamak receipt: item lines kept, quantity prefix expanded into claimable rows',
  JSON.stringify(mamakParse.items) === JSON.stringify([
    { name: 'NASI KANDAR AYAM', price: 12 },
    { name: 'TEH TARIK', price: 3.5 },
    { name: 'TEH TARIK', price: 3.5 },
    { name: 'ROTI CANAI', price: 1.6 },
  ]), JSON.stringify(mamakParse.items));
check('mamak receipt: the expanded rows still sum to the printed line total',
  Math.abs(mamakParse.items.filter((i) => i.name === 'TEH TARIK')
    .reduce((s, i) => s + i.price, 0) - 7) < 0.0001);
check('mamak receipt: SST + rounding land in the charges bucket (1.24 + 0.01)',
  Math.abs(mamakParse.charges - 1.25) < 0.0001 && mamakParse.chargeLines === 2,
  JSON.stringify({ charges: mamakParse.charges, lines: mamakParse.chargeLines }));
check('mamak receipt: TOTAL / SUBTOTAL / TUNAI / BAKI are dropped, never itemised',
  !mamakParse.items.some((i) => /TOTAL|TUNAI|BAKI/i.test(i.name))
  // dropped lines come back whitespace-collapsed, as the parser reads them
  && ['SUBTOTAL 20.60', 'TOTAL 21.85', 'TUNAI 50.00', 'BAKI 28.15']
    .every((l) => mamakParse.dropped.includes(l)),
  JSON.stringify(mamakParse.dropped));

const chainReceipt = [
  'THE CHICKEN RICE SHOP',
  'Bill 01/07/2026 19:32',
  'Ayam Goreng Berempah      12.00',
  'Tomyam Campur             18.50',
  'Nasi Putih x2              4.00',
  'Air Sirap Limau            6.90',
  'Subtotal                  41.40',
  'Service Charge 10%         4.14',
  'SST 8%                     3.64',
  'Rounding Adj              -0.02',
  'TOTAL                     49.16',
  'CASH                      50.00',
  'CHANGE                     0.84',
].join('\n');
const chainParse = await S((raw) => splitParseReceiptItems(raw), chainReceipt);
check('chain receipt: four dishes read, header and date line ignored',
  JSON.stringify(chainParse.items.map((i) => `${i.name} ${i.price.toFixed(2)}`)) === JSON.stringify([
    'Ayam Goreng Berempah 12.00', 'Tomyam Campur 18.50',
    'Nasi Putih x2 4.00', 'Air Sirap Limau 6.90',
  ]), JSON.stringify(chainParse.items));
check('chain receipt: service charge + SST + a NEGATIVE rounding sum to 7.76',
  Math.abs(chainParse.charges - 7.76) < 0.0001 && chainParse.chargeLines === 3,
  JSON.stringify({ charges: chainParse.charges, lines: chainParse.chargeLines }));
check('chain receipt: CASH and CHANGE never become items',
  !chainParse.items.some((i) => /CASH|CHANGE|Subtotal/i.test(i.name))
  && chainParse.items.length === 4, JSON.stringify(chainParse.items.map((i) => i.name)));

/* --- three real receipts the owner photographed, as fixtures ---------------
   Each broke the parser in a different way, and each is now pinned. The point
   is not the exact row count but the failure mode: get any of these wrong
   again and the split is wrong by real money. */

// 1. A restaurant guest check with PRICE / QTY / TOTAL columns. The old
//    parser found the items but booked "NET VALUE (EXCLD TAX) 85.00" as a
//    service charge — RM 85 added on top of a RM 90.10 bill, so everybody
//    paid roughly double. It also left the column noise in every name.
const guestCheck = [
  'NZ RETAIL (WANGSA LINK) S/B',
  'Ticket # 786',
  'GUEST CHECK',
  'DATE 23/07/2026 23:58:41',
  'DESCRIPTION PRICE QTY TOTAL',
  'Naan Cheese + Garlic D 8.10 1 8.10 SR',
  'Tandoori Ayam D 10.80 1 10.80 SR',
  'Satay Ayam 5Pcs D 11.90 1 11.90 SR',
  'Teh Tarik D 2.60 1 2.60 SR',
  'Ais Kosong D 0.30 3 0.90 SR',
  'Roti Canai D 2.00 1 2.00 SR',
  'SUB TOTAL (INCLUDE TAX) 36.30',
  'NET VALUE (EXCLD TAX) 34.24',
  'TAX 2.06',
  'TOTAL AMOUNT RM 36.30',
].join('\n');
const guest = await S((raw) => splitParseReceiptItems(raw), guestCheck);
check('guest check: names lose the D / price / qty columns',
  guest.items.slice(0, 3).map((i) => i.name).join(' | ')
  === 'Naan Cheese + Garlic | Tandoori Ayam | Satay Ayam 5Pcs',
  JSON.stringify(guest.items.map((i) => i.name)));
check('guest check: "NET VALUE (EXCLD TAX)" is never a service charge',
  guest.charges === 0, JSON.stringify({ charges: guest.charges, reconciled: guest.reconciled }));
check('guest check: items reconcile against the printed total, so nothing is added on top',
  Math.abs(guest.itemSum - 36.30) < 0.005 && guest.statedTotal === 36.30
  && guest.reconciled === true, JSON.stringify({ sum: guest.itemSum, total: guest.statedTotal }));
check('guest check: 3 ais kosong become three rows people can claim separately',
  guest.items.filter((i) => i.name === 'Ais Kosong').length === 3
  && guest.items.filter((i) => i.name === 'Ais Kosong').every((i) => Math.abs(i.price - 0.3) < 0.0001),
  JSON.stringify(guest.items.filter((i) => i.name === 'Ais Kosong')));
check('guest check: a Satay "5Pcs" is one dish, not five rows',
  guest.items.filter((i) => i.name === 'Satay Ayam 5Pcs').length === 1);

// 2. A supermarket receipt that prints the name on one line and the barcode +
//    unit*qty + line total on the next. Every item spanned two lines, so BOTH
//    halves were discarded and a perfect transcription still yielded 0 items.
const twoLineMart = [
  'BLUE KEY SELF-RAISING FLOUR 1KG',
  '9556755010012 5.20*1 5.20',
  'BUAH GAJUS 100GM',
  '1000544100 5.80*2 11.60',
  'CHN BAWANG KUNING HOLLAND (KG)',
  '0252850002250090026 2.49*0.904 2.25',
  'NZL FRZ BEEF INSIDE CUT',
  '02115540947702204 43*2.204 94.77',
  'Total Item 4 Sub Total 113.82',
  'Total 113.82',
].join('\n');
const mart = await S((raw) => splitParseReceiptItems(raw), twoLineMart);
check('two-line receipt: the name above pairs with the price below',
  mart.items.length >= 4
  && mart.items[0].name === 'BLUE KEY SELF-RAISING FLOUR 1KG'
  && Math.abs(mart.items[0].price - 5.20) < 0.0001, JSON.stringify(mart.items));
check('two-line receipt: a weighed item takes the LINE TOTAL, not the price per kg',
  mart.items.some((i) => i.name.startsWith('CHN BAWANG') && Math.abs(i.price - 2.25) < 0.0001)
  && mart.items.some((i) => i.name.startsWith('NZL FRZ BEEF') && Math.abs(i.price - 94.77) < 0.0001),
  JSON.stringify(mart.items.map((i) => `${i.name} ${i.price}`)));
check('two-line receipt: "5.80*2 11.60" becomes two rows of 5.80',
  mart.items.filter((i) => i.name === 'BUAH GAJUS 100GM').length === 2
  && Math.abs(mart.items.filter((i) => i.name === 'BUAH GAJUS 100GM')
    .reduce((s, i) => s + i.price, 0) - 11.60) < 0.0001);
check('two-line receipt: the barcode never becomes an item name',
  !mart.items.some((i) => /^\d{5,}/.test(i.name)), JSON.stringify(mart.items.map((i) => i.name)));

// 3. A hypermarket receipt with barcode | short name | price on ONE row. The
//    names are already truncated by the printer, so trimming them further
//    loses the only word that says what was bought.
const barcodeRows = [
  'LOTUSS STORES (MALAYSIA) SDN BHD',
  '0885954430039 LOTUSS CEN 0.79',
  '0955565870164 GG PROMO V 7.99',
  '0212046000219 BROKOLI CH 2.19',
  '0955521659892 LTS C.E W 10.99',
  'SUB-TOTAL 21.96',
  'BUY 3 FOR RM 2 -0.37',
  'TOTAL TO PAY 21.59',
  'Rounding 0.00',
].join('\n');
const lotus = await S((raw) => splitParseReceiptItems(raw), barcodeRows);
check('barcode rows: the leading barcode is stripped from the name',
  lotus.items.map((i) => i.name).join(' | ') === 'LOTUSS CEN | GG PROMO V | BROKOLI CH | LTS C.E W',
  JSON.stringify(lotus.items.map((i) => i.name)));
check('barcode rows: a trailing short word is kept — it is name, not a column',
  lotus.items.some((i) => i.name === 'GG PROMO V') && lotus.items.some((i) => i.name === 'BROKOLI CH'),
  JSON.stringify(lotus.items.map((i) => i.name)));
check('barcode rows: a negative promo line never becomes an item',
  !lotus.items.some((i) => i.price < 0) && lotus.items.length === 4,
  JSON.stringify(lotus.items));

// Every skipped line can say why it was skipped — this is what the
// "What did it read?" panel shows, and what makes a bad scan reportable.
check('every dropped line carries a reason',
  Array.isArray(guest.dropReasons) && guest.dropReasons.length > 0
  && guest.dropReasons.every((d) => d && typeof d.line === 'string' && typeof d.why === 'string' && d.why.length > 0)
  && guest.dropReasons.length === guest.dropped.length,
  JSON.stringify(guest.dropReasons.slice(0, 3)));
check('the tax line on a tax-inclusive bill is explained, not silently swallowed',
  guest.dropReasons.some((d) => /NET VALUE/i.test(d.line)),
  JSON.stringify(guest.dropReasons.map((d) => d.line)));

// --- a shared item divides sen-exactly among whoever is ticked ---
const shares = await S(() => {
  const people = [{ key: 'you', name: 'You' }, { key: 'a', name: 'Ali' }, { key: 'm', name: 'Mei' }];
  const two = splitComputeItems({
    people, charges: 0, chargesMode: 'equal',
    items: [{ name: 'Tomyam', price: 18.5, who: ['you', 'a'] }],
  });
  const three = splitComputeItems({
    people, charges: 0, chargesMode: 'equal',
    items: [{ name: 'Steamboat', price: 10, who: ['you', 'a', 'm'] }],
  });
  return {
    two: two.people.map((p) => p.amount),
    twoTotal: two.total,
    three: three.people.map((p) => p.amount),
    threeSum: three.people.reduce((s, p) => s + p.amount, 0),
    note: three.people[1].note,
  };
});
check('an item shared by two splits clean down the middle (18.50 → 9.25 each)',
  JSON.stringify(shares.two) === JSON.stringify([9.25, 9.25, 0]) && shares.twoTotal === 18.5,
  JSON.stringify(shares.two));
check('an item shared by three gives the odd sen to the payer (10.00 → 3.34/3.33/3.33)',
  JSON.stringify(shares.three) === JSON.stringify([3.34, 3.33, 3.33])
  && Math.abs(shares.threeSum - 10) < 1e-9, JSON.stringify(shares.three));
check('the breakdown note names the fraction that was shared',
  shares.note === '⅓ Steamboat 3.33', shares.note);

/* --- both charge modes, hand-computed ---
   Items: Ayam 12.00 (You), Tomyam 18.50 (You+Ali), Nasi 4.00 (all three),
   Sirap 6.90 (Mei). Item subtotals: You 22.59, Ali 10.58, Mei 8.23 = 41.40.
   Charges 7.76.
     equally      776 ÷ 3 = 258.67 → 259 / 259 / 258 (spare sen by position)
                  → You 25.18, Ali 13.17, Mei 10.81
     proportional 776 × 2259/4140 = 423.43 → 424 (largest remainder)
                  776 × 1058/4140 = 198.31 → 198
                  776 ×  823/4140 = 154.26 → 154
                  → You 26.83, Ali 12.56, Mei 9.77
   Both sum to 49.16 exactly. */
const modes = await S(() => {
  const base = {
    people: [{ key: 'you', name: 'You' }, { key: 'a', name: 'Ali' }, { key: 'm', name: 'Mei' }],
    items: [
      { name: 'Ayam Goreng Berempah', price: 12, who: ['you'] },
      { name: 'Tomyam Campur', price: 18.5, who: ['you', 'a'] },
      { name: 'Nasi Putih x2', price: 4, who: ['you', 'a', 'm'] },
      { name: 'Air Sirap Limau', price: 6.9, who: ['m'] },
    ],
    charges: 7.76,
  };
  const eq = splitComputeItems({ ...base, chargesMode: 'equal' });
  const pr = splitComputeItems({ ...base, chargesMode: 'proportional' });
  const sum = (c) => Math.round(c.people.reduce((s, p) => s + p.amount, 0) * 100) / 100;
  return {
    itemsOnly: eq.people.map((p) => p.items),
    eq: eq.people.map((p) => p.amount), eqSum: sum(eq), eqTotal: eq.total,
    pr: pr.people.map((p) => p.amount), prSum: sum(pr), prTotal: pr.total,
    eqNote: eq.people[1].note, prNote: pr.people[1].note,
  };
});
check('item subtotals per person are exact (22.59 / 10.58 / 8.23 = 41.40)',
  JSON.stringify(modes.itemsOnly) === JSON.stringify([22.59, 10.58, 8.23]),
  JSON.stringify(modes.itemsOnly));
check('charges split equally: 25.18 / 13.17 / 10.81, summing to the bill',
  JSON.stringify(modes.eq) === JSON.stringify([25.18, 13.17, 10.81])
  && modes.eqSum === 49.16 && modes.eqTotal === 49.16,
  JSON.stringify({ shares: modes.eq, sum: modes.eqSum }));
check('charges in proportion to items: 26.83 / 12.56 / 9.77, summing to the bill',
  JSON.stringify(modes.pr) === JSON.stringify([26.83, 12.56, 9.77])
  && modes.prSum === 49.16 && modes.prTotal === 49.16,
  JSON.stringify({ shares: modes.pr, sum: modes.prSum }));
check('each person\'s note carries their own items and their own charge share',
  modes.eqNote === '½ Tomyam Campur 9.25 · ⅓ Nasi Putih x2 1.33 · charges 2.59'
  && /charges 1\.98$/.test(modes.prNote),
  JSON.stringify({ eq: modes.eqNote, pr: modes.prNote }));

