// ── Track 3c (v1.68.1): Android DuitfulKit.recognizeText (Play Services ML Kit v2) ─
{
  const andOcrCtx = await b.newContext({ viewport: { width: 390, height: 844 } });
  await andOcrCtx.addInitScript(() => {
    window.__andOcrCalls = [];
    window.Capacitor = {
      isNativePlatform: () => true,
      getPlatform: () => 'android',
      Plugins: {
        DuitfulKit: {
          recognizeText: async (opts) => {
            window.__andOcrCalls.push(opts);
            return { text: '茶室 RM 12.50', blocks: [] };
          },
        },
      },
    };
  });
  const aop = await andOcrCtx.newPage();
  const aoErr = [];
  aop.on('pageerror', (e) => aoErr.push(e.message));
  await aop.goto(`${BASE}/app/index.html`);
  await aop.waitForTimeout(400);
  const aoRes = await aop.evaluate(async () => {
    const reader = nativeTextReader();
    const out = reader ? await reader.detectText({ base64Image: 'AAAA', rotation: 90 }) : null;
    return {
      engine: reader && reader.engine,
      text: out && out.text,
      calls: window.__andOcrCalls,
    };
  });
  check('v1.68.1: Android nativeTextReader routes through DuitfulKit.recognizeText with engine "mlkit"',
    aoRes.engine === 'mlkit' && aoRes.text === '茶室 RM 12.50'
    && aoRes.calls.length === 1 && aoRes.calls[0].base64Image === 'AAAA' && aoRes.calls[0].rotation === 90
    && aoErr.length === 0,
    JSON.stringify({ ...aoRes, aoErr }));
  await andOcrCtx.close();
}

// ── Track 3b (v1.68.2): iOS Share Extension (DuitfulShare + App Group + duitful://share) ─
{
  const patchIos = readFileSync(path.join(REPO_ROOT, 'scripts', 'patch-ios.mjs'), 'utf8');
  const swiftPlug = readFileSync(path.join(REPO_ROOT, 'native', 'duitful-kit', 'ios', 'Sources', 'DuitfulKitPlugin', 'DuitfulKitPlugin.swift'), 'utf8');
  const fastfile = readFileSync(path.join(REPO_ROOT, 'fastlane', 'Fastfile'), 'utf8');
  const iosYml = readFileSync(path.join(REPO_ROOT, '.github', 'workflows', 'ios.yml'), 'utf8');
  check('v1.68.2: iOS Share Extension target, App Group, takeSharedFiles, Fastfile signing and IPA check are all wired',
    patchIos.includes('const SHARE_NAME = "DuitfulShare"')
    && patchIos.includes('group.com.aydiljoe.duitful')
    && patchIos.includes('com.apple.share-services')
    && swiftPlug.includes('func takeSharedFiles(')
    && swiftPlug.includes('group.com.aydiljoe.duitful')
    && fastfile.includes('com.aydiljoe.duitful.DuitfulShare')
    && iosYml.includes('DuitfulShare.appex'));

  const iosShareCtx = await b.newContext({ viewport: { width: 390, height: 844 } });
  await iosShareCtx.addInitScript(() => {
    window.__urlListeners = [];
    window.__takeCalls = 0;
    window.Capacitor = {
      isNativePlatform: () => true,
      getPlatform: () => 'ios',
      Plugins: {
        App: {
          addListener: (ev, fn) => { if (ev === 'appUrlOpen') window.__urlListeners.push(fn); return { remove: () => {} }; },
          getLaunchUrl: async () => ({ url: '' }),
          getInfo: async () => ({ version: '1.68.2', build: '1' }),
        },
        DuitfulKit: {
          takeSharedFiles: async () => {
            window.__takeCalls++;
            if (window.__takeCalls === 1) {
              return { files: [{ name: 'receipt.jpg', mime: 'image/jpeg', base64: 'aGVsbG8=' }] };
            }
            return { files: [] };
          },
        },
      },
    };
  });
  const isp = await iosShareCtx.newPage();
  const isErr = [];
  isp.on('pageerror', (e) => isErr.push(e.message));
  await isp.goto(`${BASE}/app/index.html`);
  await isp.waitForTimeout(400);
  await isp.click('#btn-start-open');
  await isp.waitForTimeout(500);
  const shRes = await isp.evaluate(async () => {
    document.querySelectorAll('dialog[open]').forEach((d) => d.close());
    window.__takeCalls = 0;
    for (const fn of window.__urlListeners) fn({ url: 'duitful://share' });
    await new Promise((r) => setTimeout(r, 150));
    const dlg = document.getElementById('shared-in-dialog');
    return {
      takeCalls: window.__takeCalls,
      dlgOpen: !!(dlg && dlg.open),
      what: document.getElementById('shared-in-what')?.textContent || '',
    };
  });
  check('v1.68.2: duitful://share deep link drains DuitfulKit.takeSharedFiles and opens the shared-in sheet',
    shRes.takeCalls >= 1 && shRes.dlgOpen && /1 photo shared to Duitful/.test(shRes.what) && isErr.length === 0,
    JSON.stringify({ ...shRes, isErr }));
  await iosShareCtx.close();
}

// ── Assistant Update Phase 1 (v1.69.0): Siri, Google Assistant & Quick Controls ─
{
  const patchIos = readFileSync(path.join(REPO_ROOT, 'scripts', 'patch-ios.mjs'), 'utf8');
  const patchAnd = readFileSync(path.join(REPO_ROOT, 'scripts', 'patch-android-shortcuts.mjs'), 'utf8');
  const swiftPlug = readFileSync(path.join(REPO_ROOT, 'native', 'duitful-kit', 'ios', 'Sources', 'DuitfulKitPlugin', 'DuitfulKitPlugin.swift'), 'utf8');
  check('v1.69.0: iOS App Intents (Category enum, Wallet entity, NoSpendToday, shortcuts refreshed at launch, iOS 18 ControlWidget) and Android Assistant Actions + Quick Settings Tile are wired',
    patchIos.includes('enum DuitfulCategoryEnum')
    && patchIos.includes('struct DuitfulWalletEntity')
    && patchIos.includes('struct DuitfulNoSpendTodayIntent')
    && patchIos.includes('if #available(iOS 17.0, *) { ${SHORTCUTS_REFRESH} }')
    && patchIos.includes('struct DuitfulLogSpendControl: ControlWidget')
    && patchIos.includes('struct DuitfulScanReceiptControl: ControlWidget')
    && swiftPlug.includes('duitful.assistant.wallets')
    && patchAnd.includes('actions.intent.OPEN_APP_FEATURE')
    && patchAnd.includes('DuitfulQuickTileService')
    && patchAnd.includes('BIND_QUICK_SETTINGS_TILE'));

  const asstCtx = await b.newContext({ viewport: { width: 390, height: 844 } });
  const ap = await asstCtx.newPage();
  const aErr = [];
  ap.on('pageerror', (e) => aErr.push(e.message));
  await ap.goto(`${BASE}/app/index.html`);
  await ap.waitForTimeout(400);
  await ap.click('#btn-start-open');
  await ap.waitForTimeout(400);
  const aRes = await ap.evaluate(() => {
    document.querySelectorAll('dialog[open]').forEach((d) => d.close());
    // 1. duitful://action/no-spend checks in today's streak.
    const parsedAction = quickActionFromUrl('duitful://action/no-spend');
    state.streak = { enabled: true, reminderEnabled: true, reminderHour: 21, noSpendDates: [], freezes: [] };
    runQuickAction('no-spend');
    const markedToday = state.streak.noSpendDates.includes(todayISO());

    // 2. quickAddToPending preserves category (cat) and resolves wallet name (w).
    state.wallets = [{ id: 'w-mae', name: 'MAE', type: 'ewallet', initial: 500 }];
    const pending = quickAddToPending({ a: 18.5, c: 'Village Park', cat: 'Food', w: 'mae', s: 'shortcut', t: Date.now() });

    // 3. buildWidgetSummary exposes wallet names ONLY when unlocked, cleared to [] when locked.
    const wUnl = buildWidgetSummary({ locked: false });
    const wLck = buildWidgetSummary({ locked: true });
    return {
      parsedAction,
      markedToday,
      pending: pending && { amount: pending.amount, merchant: pending.merchant, category: pending.category, walletId: pending.walletId, providerName: pending.providerName },
      wUnlNames: wUnl.walletNames,
      wLckNames: wLck.walletNames,
    };
  });
  check('v1.69.0: no-spend deep link checks in streak, quickAddToPending keeps category & wallet, and walletNames clear on lock',
    aRes.parsedAction === 'no-spend' && aRes.markedToday
    && aRes.pending && aRes.pending.amount === 18.5 && aRes.pending.category === 'Food' && aRes.pending.walletId === 'w-mae'
    && Array.isArray(aRes.wUnlNames) && aRes.wUnlNames.length === 1 && aRes.wUnlNames[0] === 'MAE'
    && Array.isArray(aRes.wLckNames) && aRes.wLckNames.length === 0
    && aErr.length === 0,
    JSON.stringify({ ...aRes, aErr }));
  await asstCtx.close();
}

// ── Assistant Update Phases 2–4 (v1.70.0): Voice & Compound Log & Split ───
{
  const patchIos = readFileSync(path.join(REPO_ROOT, 'scripts', 'patch-ios.mjs'), 'utf8');
  const patchAnd = readFileSync(path.join(REPO_ROOT, 'scripts', 'patch-android-shortcuts.mjs'), 'utf8');
  check('v1.70.0: iOS Tell Duitful, Draft split request, NoSpend ControlWidget and Android voice action are wired',
    patchIos.includes('struct DuitfulLogBySentenceIntent')
    && patchIos.includes('struct DuitfulCreateSplitRequestIntent')
    && patchIos.includes('struct DuitfulNoSpendControl: ControlWidget')
    && patchAnd.includes('action: "voice"'));

  const vCtx = await b.newContext({ viewport: { width: 360, height: 780 } });
  const vp = await vCtx.newPage();
  const vErr = [];
  vp.on('pageerror', (e) => vErr.push(e.message));
  await vp.goto(`${BASE}/app/index.html`);
  await vp.waitForTimeout(400);
  await vp.click('#btn-start-open');
  await vp.waitForTimeout(400);

  const vRes = await vp.evaluate(async () => {
    document.querySelectorAll('dialog[open]').forEach((d) => d.close());
    state.wallets = [{ id: 'w-mae', name: 'MAE', type: 'ewallet', initial: 500 }];
    state.split.people = ['Ali', 'Siti'];
    renderAll();

    // 1. 360px layout check for Scan receipt + Voice row in EN / MS / ZH.
    const layout = {};
    for (const lang of ['en', 'ms', 'zh']) {
      await I18N.set(lang);
      renderAll();
      const scanR = document.getElementById('btn-scan').getBoundingClientRect();
      const voiceR = document.getElementById('btn-voice').getBoundingClientRect();
      layout[lang] = {
        overflow: document.documentElement.scrollWidth > window.innerWidth + 1,
        fits: voiceR.width > 0 && voiceR.right <= window.innerWidth + 1 && Math.abs(scanR.top - voiceR.top) < 4,
      };
    }
    await I18N.set('en');
    renderAll();

    // 2. Spoken Malay + wallet: "dua belas ringgit lima puluh sen nasi lemak pakai MAE"
    const pBm = parseVoiceSentence('dua belas ringgit lima puluh sen nasi lemak pakai MAE');
    // 3. Chinese spoken number: "十二块五 鸡饭"
    const pZh = parseVoiceSentence('十二块五 鸡饭');
    // 4. Compound Log & Split: "Log my RM 40 food spending and half of the amount request from Ali"
    const pComp = parseVoiceSentence('Log my RM 40 food spending and half of the amount request from Ali');
    // 5. Deep link duitful://action/voice?text=... opens #voice-dialog with preview & saves linked spend + split.
    const parsedAction = quickActionFromUrl('duitful://action/voice?text=RM%2040%20nasi%20lemak%20split%20half%20with%20Ali');
    const parsedText = quickActionTextFromUrl('duitful://action/voice?text=RM%2040%20nasi%20lemak%20split%20half%20with%20Ali');
    runQuickAction(parsedAction, parsedText);
    const dlgOpen = document.getElementById('voice-dialog').open;
    const saveBtnText = document.getElementById('voice-save').textContent.trim();
    const expBefore = state.dailyExpenses.length;
    const outBefore = state.split.out.length;
    const saved = voiceSaveConfirmed();
    const expAfter = state.dailyExpenses.length;
    const outAfter = state.split.out.length;
    const shareOpen = !!document.getElementById('split-share-dialog')?.open;

    return {
      layout,
      pBm: { a: pBm.amount, c: pBm.category, w: pBm.walletId },
      pZh: { a: pZh.amount, c: pZh.category },
      pComp: { a: pComp.amount, c: pComp.category, people: pComp.split && pComp.split.people },
      parsedAction,
      dlgOpen,
      saveBtnText,
      expAdded: expAfter - expBefore,
      outAdded: outAfter - outBefore,
      linkedId: saved && saved.splitRec && saved.splitRec.expenseId === saved.expense.id,
      shareOpen,
    };
  });

  check('v1.70.0: Voice parser handles Malay/Chinese spoken numbers, wallet matching, compound Log & Split with local math, deep link, and 360px EN/MS/ZH layout',
    ['en', 'ms', 'zh'].every((l) => !vRes.layout[l].overflow && vRes.layout[l].fits)
    && vRes.pBm.a === 12.5 && vRes.pBm.c === 'Food' && vRes.pBm.w === 'w-mae'
    && vRes.pZh.a === 12.5 && vRes.pZh.c === 'Food'
    && vRes.pComp.a === 40 && vRes.pComp.c === 'Food'
    && Array.isArray(vRes.pComp.people) && vRes.pComp.people.length === 1 && vRes.pComp.people[0].name === 'Ali' && vRes.pComp.people[0].amount === 20
    && vRes.parsedAction === 'voice' && vRes.dlgOpen && /Save & send to Ali/.test(vRes.saveBtnText)
    && vRes.expAdded === 1 && vRes.outAdded === 1 && vRes.linkedId && vRes.shareOpen
    && vErr.length === 0,
    JSON.stringify({ ...vRes, vErr }));

  await vCtx.close();
}

// ── Kira, the receipt mascot (v1.71.0) ────────────────────────────────────
{
  // The sempoa (counting) mood means on-device AI and nothing else: the only
  // caller that may ask for it is the AI thinking sheet in script.js.
  const appDir = path.join(REPO_ROOT, 'app');
  const countingCalls = [];
  for (const f of readdirSync(appDir).filter((n) => n.endsWith('.js') && !n.startsWith('i18n-'))) {
    const src = readFileSync(path.join(appDir, f), 'utf8');
    for (const m of src.matchAll(/kiraSvg\(\s*["'`]counting["'`]([^)]*)\)/g)) {
      const before = src.slice(Math.max(0, m.index - 600), m.index);
      countingCalls.push({ f, ai: /ai:\s*true/.test(m[1]), inAiSheet: /aiThinkKira|ai-think/.test(before) });
    }
  }
  check('Kira (1.71.0): the counting (sempoa) mood is drawn only by the AI thinking sheet, with { ai: true }',
    countingCalls.length === 1 && countingCalls.every((c) => c.f === 'script.js' && c.ai && c.inAiSheet),
    JSON.stringify(countingCalls));

  for (const reduced of [false, true]) {
    const kCtx = await b.newContext({ viewport: { width: 390, height: 844 }, reducedMotion: reduced ? 'reduce' : 'no-preference' });
    const kp = await kCtx.newPage();
    const kErr = [];
    kp.on('pageerror', (e) => kErr.push(e.message));
    await kp.goto(`${BASE}/app/index.html`);
    await kp.waitForTimeout(600);
    const welcome = await kp.evaluate(() => {
      const k = document.querySelector('#lock-welcome:not([hidden]) #lock-kira svg.kira');
      return { kira: !!k, waving: !!k && k.classList.contains('is-waving') };
    });
    await kp.click('#btn-start-open');
    await kp.waitForTimeout(1500);
    await kp.evaluate(() => document.querySelectorAll('dialog[open]').forEach((d) => d.close()));
    await kp.waitForTimeout(200);
    const r = await kp.evaluate(async () => {
      const wait = (ms) => new Promise((res) => setTimeout(res, ms));
      const out = { loaded: typeof kiraSvg === 'function' && typeof kiraHop === 'function' };
      // Every mood renders an aria-hidden SVG; counting needs { ai: true }.
      out.moods = KIRA_MOODS.map((m) => {
        const host = document.createElement('div');
        host.innerHTML = kiraSvg(m, { ai: true });
        const svg = host.querySelector('svg');
        return { m, ok: !!svg && svg.classList.contains('kira--' + m) && svg.getAttribute('aria-hidden') === 'true' && !!svg.querySelector('.kira-body') };
      });
      const plain = document.createElement('div');
      plain.innerHTML = kiraSvg('counting');
      out.countingWithoutAi = plain.querySelector('svg').classList.contains('kira--happy') && !plain.querySelector('.sempoa');
      // Empty Home: happy Kira beside "Nothing logged today."
      const tk = document.querySelector('#today-kira-row:not([hidden]) #today-kira svg.kira--happy');
      out.homeKira = !!tk && !document.getElementById('today-empty').hidden;
      // Empty lists: Kira in the shared empty state.
      out.debtsKira = !!document.querySelector('#list-debt .empty-block-kira svg.kira--happy');
      out.savingsKira = !!document.querySelector('#savings-list .empty-block-kira svg.kira--happy');
      // No Kira on a page outside the AI sheet holds a sempoa.
      out.sempoaOutsideAi = [...document.querySelectorAll('svg.kira .sempoa')].filter((g) => !g.closest('#ai-think')).length;
      // AI sheet: counting Kira, only there, beads on the badge's loop while open.
      const dlg = document.getElementById('ai-think');
      out.sheetKira = !!dlg.querySelector('.ai-think-mark svg.kira--counting .sempoa .sp-el1');
      aiThinkStart(3000, { overlay: true, label: 'Reading your receipt' });
      await wait(700);
      out.sheetOpen = dlg.open;
      out.bead = getComputedStyle(dlg.querySelector('.kira--counting .sp-el1')).animationName;
      out.nod = getComputedStyle(dlg.querySelector('.kira--counting .kira-nod')).animationName;
      out.title = document.getElementById('ai-think-title').textContent;
      aiThinkHide();
      for (let i = 0; i < 60 && dlg.open; i++) await wait(50);
      out.sheetClosed = !dlg.open;
      // Kira idle loop on an empty state; stops under reduced motion.
      out.idle = getComputedStyle(document.querySelector('#list-debt .kira .kira-float')).animationName;
      out.blink = getComputedStyle(document.querySelector('#list-debt .kira .kira-blink')).animationName;
      // No-spend check-in: sleepy Kira on Today and in the streak sheet.
      checkInNoSpendToday();
      await wait(100);
      out.todaySleepy = !!document.querySelector('#today-kira svg.kira--sleepy');
      openStreakDialog();
      await wait(100);
      out.streakSleepy = !!document.querySelector('#streak-kira svg.kira--sleepy');
      out.zz = getComputedStyle(document.querySelector('#streak-kira .kira-zz')).animationName;
      document.getElementById('streak-dialog').close();
      // Logging hop: a spend from Home → proud Kira + coin on the toast, then gone.
      const form = document.getElementById('form-daily');
      form.querySelector('input[name="amount"]').value = '7';
      form.requestSubmit();
      await wait(120);
      const hop = document.querySelector('.kira-hop');
      out.hop = !!hop && !!hop.querySelector('svg.kira--proud') && !!hop.querySelector('.kira-coin');
      await wait(1000);
      out.hopGone = !document.querySelector('.kira-hop');
      out.todayGone = document.getElementById('today-kira-row').hidden;
      // Streak with an entry today: proud.
      openStreakDialog();
      await wait(100);
      out.streakProud = !!document.querySelector('#streak-kira svg.kira--proud');
      document.getElementById('streak-dialog').close();
      return out;
    });
    const tag = reduced ? 'reduced motion' : 'motion';
    if (!reduced) {
      check('Kira (1.71.0): kira.js loads; all six moods render a decorative SVG; counting without { ai: true } is plain happy Kira',
        r.loaded && r.moods.every((m) => m.ok) && r.countingWithoutAi, JSON.stringify(r.moods));
      check('Kira (1.71.0): welcome waves; empty Home, Debts and Savings show happy Kira; no sempoa outside the AI sheet',
        welcome.kira && welcome.waving && r.homeKira && r.debtsKira && r.savingsKira && r.sempoaOutsideAi === 0,
        JSON.stringify({ welcome, homeKira: r.homeKira, debtsKira: r.debtsKira, savingsKira: r.savingsKira, sempoaOutsideAi: r.sempoaOutsideAi }));
      check('Kira (1.71.0): the AI thinking sheet holds counting Kira, beads on the badge\'s 2.2s loop, nodding while open, "AI is reading" text kept',
        r.sheetKira && r.sheetOpen && r.bead === 'ai-sp-el1' && r.nod === 'kira-nod' && /AI is reading/.test(r.title) && r.sheetClosed,
        JSON.stringify(r));
      check('Kira (1.71.0): a logged spend hops proud Kira with a coin on the toast once; no-spend check-in is sleepy (Today + streak sheet), a streak with a spend is proud',
        r.hop && r.hopGone && r.todayGone && r.todaySleepy && r.streakSleepy && r.streakProud
        && r.idle === 'kira-float' && r.blink === 'kira-blink' && r.zz === 'kira-zz' && kErr.length === 0,
        JSON.stringify({ ...r, kErr }));
    } else {
      check('Kira (1.71.0): reduce motion stops every Kira animation (idle, z\'s, nod, beads) and the logging hop',
        r.idle === 'none' && r.blink === 'none' && r.zz === 'none' && r.nod === 'none' && r.bead === 'none'
        && !r.hop && r.homeKira && r.sheetKira && kErr.length === 0,
        JSON.stringify({ ...r, kErr }));
    }
    await kCtx.close();
  }

  // 360px in every language: the Today row, the empty states and the streak
  // hero with Kira stay inside their cards.
  const lCtx = await b.newContext({ viewport: { width: 360, height: 780 } });
  const lp = await lCtx.newPage();
  await lp.goto(`${BASE}/app/index.html`);
  await lp.waitForTimeout(500);
  await lp.click('#btn-start-open');
  await lp.waitForTimeout(1500);
  await lp.evaluate(() => document.querySelectorAll('dialog[open]').forEach((d) => d.close()));
  const fit = {};
  for (const lang of ['en', 'ms', 'zh']) {
    await lp.evaluate((l) => { localStorage.setItem('duitful.lang', l); }, lang);
    await lp.reload();
    await lp.waitForTimeout(1500);
    fit[lang] = await lp.evaluate(() => {
      const out = [];
      if (!(document.getElementById('today-kira-row').getBoundingClientRect().width > 0)) out.push('today row not on screen');
      const inside = (el, box) => {
        const r = el.getBoundingClientRect(), c = box.getBoundingClientRect();
        return r.width === 0 || (r.left >= c.left - 1 && r.right <= c.right + 1);
      };
      for (const el of document.querySelectorAll('#today-kira-row, #today-kira-row > *')) if (!inside(el, el.closest('.card'))) out.push(el.id || el.className);
      openStreakDialog();
      const dlg = document.getElementById('streak-dialog');
      for (const el of dlg.querySelectorAll('.streak-hero-marks, .streak-hero-marks > *')) if (!inside(el, dlg)) out.push(el.className);
      dlg.close();
      return out;
    });
  }
  check('Kira (1.71.0): at 360px the Today row and the streak hero fit in English, Malay and Chinese',
    Object.values(fit).every((v) => v.length === 0), JSON.stringify(fit));
  await lCtx.close();
}

// =========================================================================
// Duitful AI+ Phase 1: full admin trim, api/ai.js in-memory
// handler with stubbed Gemini, 8 v1 task checks, 3-device pairing +
// 4th-device replace, quota fallback, on-device redaction, dual entitlement,
// and "nothing sent when AI+ is off".
// =========================================================================
{
  const { createRequire } = await import('node:module');
  const reqCjs = createRequire(import.meta.url);
  process.env.AI_MEMORY = '1';
  const aiHandler = reqCjs(path.join(REPO_ROOT, 'api/ai.js'));
  const aiKv = reqCjs(path.join(REPO_ROOT, 'api/_lib/ai/kv.js'));
  const aiModels = reqCjs(path.join(REPO_ROOT, 'api/_lib/ai/models.js'));
  aiKv.resetMemory();

  const callAiApi = async ({ method = 'POST', op = '', body = null, token = '', ip = '10.0.0.1', headers = {}, query = {} }) => {
    const req = {
      method,
      query: op ? { op, ...query } : { ...query },
      headers: {
        'content-type': 'application/json',
        'x-forwarded-for': ip,
        ...(token ? { authorization: `Bearer ${token}` } : {}),
        ...headers,
      },
      body: body || {},
    };
    let statusCode = 200;
    let payload = null;
    const res = {
      headers: {},
      setHeader(k, v) { this.headers[k.toLowerCase()] = v; },
      status(code) { statusCode = code; return this; },
      json(obj) { payload = obj; return this; },
      end() { return this; },
    };
    await aiHandler(req, res);
    return { status: statusCode, data: payload };
  };

  // 1) Unknown op -> 404
  const badOp = await callAiApi({ method: 'GET', op: 'nope' });
  check('ai+ backend: unknown ?op= returns 404 with known list',
    badOp.status === 404 && Array.isArray(badOp.data?.known) && badOp.data.known.includes('run'),
    JSON.stringify(badOp));

  // 2) verify-sub creates Device #1 + signed token + status
  const v1 = await callAiApi({
    op: 'verify-sub',
    body: { platform: 'ios', plan: 'duitful_ai_monthly', transactionId: 'tx-ai-001', deviceLabel: 'iPhone 15' },
  });
  check('ai+ backend: verify-sub issues signed device token and registers Device 1 of 3',
    v1.status === 200 && v1.data?.ok && typeof v1.data.subToken === 'string'
    && v1.data.status?.active && v1.data.status.devicesCount === 1 && v1.data.status.scansLimit === 100 && v1.data.status.textLimit === 1000,
    JSON.stringify(v1));
  const tok1 = v1.data.subToken;

  // 3) status returns active meters
  const st1 = await callAiApi({ method: 'GET', op: 'status', token: tok1 });
  check('ai+ backend: GET ?op=status returns active meters and device count',
    st1.status === 200 && st1.data?.status?.active && st1.data.status.devicesCount === 1,
    JSON.stringify(st1));

  // 4) 3-device pairing (single-use 6-digit code) + 4th-device 409 & replaceOldest
  const ps1 = await callAiApi({ op: 'pair-start', token: tok1 });
  check('ai+ backend: pair-start generates a 6-digit code with 10-min TTL',
    ps1.status === 200 && /^\d{6}$/.test(ps1.data?.code || '') && ps1.data.expiresIn === 600,
    JSON.stringify(ps1));

  const pc2 = await callAiApi({ op: 'pair-claim', body: { code: ps1.data.code, deviceLabel: 'Web Chrome' } });
  const pc2Replay = await callAiApi({ op: 'pair-claim', body: { code: ps1.data.code, deviceLabel: 'Replay' } });
  check('ai+ backend: pair-claim binds Device #2 and burns code immediately (single-use)',
    pc2.status === 200 && pc2.data?.status?.devicesCount === 2 && pc2Replay.status === 404,
    JSON.stringify({ pc2: pc2.status, replay: pc2Replay.status }));
  const tok2 = pc2.data.subToken;

  const ps2 = await callAiApi({ op: 'pair-start', token: tok1 });
  const pc3 = await callAiApi({ op: 'pair-claim', body: { code: ps2.data.code, deviceLabel: 'iPad' } });
  check('ai+ backend: pair-claim binds Device #3 (3 of 3)',
    pc3.status === 200 && pc3.data?.status?.devicesCount === 3,
    JSON.stringify(pc3));

  const ps3 = await callAiApi({ op: 'pair-start', token: tok2 });
  const pc4Blocked = await callAiApi({ op: 'pair-claim', body: { code: ps3.data.code, deviceLabel: 'Android' } });
  const pc4Replace = await callAiApi({ op: 'pair-claim', body: { code: ps3.data.code, deviceLabel: 'Android', replaceOldest: true } });
  const tok1AfterEvict = await callAiApi({ method: 'GET', op: 'status', token: tok1 });
  check('ai+ backend: 4th device returns 409 device-limit, then replaceOldest evicts oldest slot',
    pc4Blocked.status === 409 && pc4Blocked.data?.error === 'device-limit'
    && pc4Replace.status === 200 && pc4Replace.data?.status?.devicesCount === 3 && !!pc4Replace.data?.replaced
    && tok1AfterEvict.status === 401,
    JSON.stringify({ blocked: pc4Blocked.status, replaced: pc4Replace.status, evicted: tok1AfterEvict.status }));

  // 5) Task contract through real handler with stubbed Gemini
  let stubResult = null;
  let stubThrows = false;
  global.__DUITFUL_AI_GEMINI_STUB__ = async () => {
    if (stubThrows) throw new Error('timeout');
    return stubResult;
  };

  // Unknown task -> 400, no quota
  const unkTask = await callAiApi({ op: 'run', token: tok2, body: { task: 'free-chat', input: { prompt: 'hi' } } });
  // Oversize / unknown field -> 400, no quota
  const badField = await callAiApi({ op: 'run', token: tok2, body: { task: 'payee-clean', input: { raw: 'GRAB', extra: 1 } } });
  const oversize = await callAiApi({ op: 'run', token: tok2, body: { task: 'payee-clean', input: { raw: 'A'.repeat(200) } } });
  check('ai+ tasks: unknown task, unknown field, and oversize input return 400 and use no quota',
    unkTask.status === 400 && badField.status === 400 && oversize.status === 400,
    JSON.stringify({ unk: unkTask.status, field: badField.status, over: oversize.status }));

  // Valid payee-clean -> increments textUsed to 1
  stubResult = { payee: 'Grab' };
  const pcOk = await callAiApi({ op: 'run', token: tok2, body: { task: 'payee-clean', input: { raw: 'PYMT*GRAB 8812 KL' } } });
  // Hallucinated payee-clean -> dropped (result: null), textUsed stays 1
  stubResult = { payee: 'Starbucks' };
  const pcBad = await callAiApi({ op: 'run', token: tok2, body: { task: 'payee-clean', input: { raw: 'PYMT*GRAB 8812 KL' } } });
  check('ai+ tasks (payee-clean): accepts words in input, drops hallucinated names without using quota',
    pcOk.status === 200 && pcOk.data?.ok && pcOk.data.result?.payee === 'Grab' && pcOk.data.status.textUsed === 1
    && pcBad.status === 200 && !pcBad.data?.ok && pcBad.data.result === null && pcBad.data.status.textUsed === 1,
    JSON.stringify({ ok: pcOk.data, bad: pcBad.data }));

  // Valid receipt-read vs hallucinated total/category
  stubResult = { total: 12.5, vendor: 'Kedai Kopi', category: 'Food', items: [{ name: 'Nasi Lemak', amount: 12.5 }] };
  const rcOk = await callAiApi({
    op: 'run', token: tok2,
    body: { task: 'receipt-read', input: { ocrText: 'KEDAI KOPI\nNasi Lemak 12.50\nTOTAL RM 12.50', categories: ['Food', 'Transport'] } },
  });
  stubResult = { total: 99.99, vendor: 'Fake Shop', category: 'Crypto' };
  const rcBad = await callAiApi({
    op: 'run', token: tok2,
    body: { task: 'receipt-read', input: { ocrText: 'KEDAI KOPI\nTOTAL RM 12.50', categories: ['Food', 'Transport'] } },
  });
  check('ai+ tasks (receipt-read): keeps printed amounts/allowed category, drops hallucinated values without using scan quota',
    rcOk.status === 200 && rcOk.data?.ok && rcOk.data.result?.total === 12.5 && rcOk.data.status.scansUsed === 1
    && rcBad.status === 200 && !rcBad.data?.ok && rcBad.data.result === null && rcBad.data.status.scansUsed === 1,
    JSON.stringify({ ok: rcOk.data, bad: rcBad.data }));

  // Timeout uses no quota
  stubThrows = true;
  const rcTimeout = await callAiApi({ op: 'run', token: tok2, body: { task: 'payee-clean', input: { raw: 'GRAB KL' } } });
  stubThrows = false;
  check('ai+ tasks: upstream timeout returns null and consumes no quota',
    rcTimeout.status === 200 && !rcTimeout.data?.ok && rcTimeout.data.result === null && rcTimeout.data.status.textUsed === 1,
    JSON.stringify(rcTimeout.data));

  // split-match exact amount guard
  stubResult = { splitId: 's1' };
  const smOk = await callAiApi({
    op: 'run', token: tok2,
    body: { task: 'split-match', input: { sender: 'MUHAMMAD ALI BIN ABU', amount: 22.5, openSplits: [{ id: 's1', name: 'Ali', amount: 22.5 }] } },
  });
  const smMismatch = await callAiApi({
    op: 'run', token: tok2,
    body: { task: 'split-match', input: { sender: 'MUHAMMAD ALI BIN ABU', amount: 99, openSplits: [{ id: 's1', name: 'Ali', amount: 22.5 }] } },
  });
  check('ai+ tasks (split-match): enforces exact amount match',
    smOk.data?.result?.splitId === 's1' && smMismatch.data?.result?.splitId === null,
    JSON.stringify({ ok: smOk.data?.result, mis: smMismatch.data?.result }));

  // voice-entry, split-items, ea-read, loan-read, statement-read smoke checks
  stubResult = { amount: 12.5, category: 'Food', wallet: 'MAE', note: 'nasi lemak' };
  const veOk = await callAiApi({
    op: 'run', token: tok2,
    body: { task: 'voice-entry', input: { sentence: 'RM 12.50 nasi lemak pakai MAE', categories: ['Food'], wallets: ['MAE'] } },
  });
  stubResult = { items: [{ name: 'Teh O Ais', qty: 2, amount: 6 }] };
  const siOk = await callAiApi({
    op: 'run', token: tok2,
    body: { task: 'split-items', input: { lines: '2X TEH O AIS 6.00', subtotal: 6 } },
  });
  stubResult = { year: 2025, b1a: 54000, sectionB: 54000 };
  const eaOk = await callAiApi({
    op: 'run', token: tok2,
    body: { task: 'ea-read', input: { text: 'BORANG EA 2025 B1(a) 54,000.00 TOTAL 54,000.00' } },
  });
  stubResult = { lender: 'PTPTN', kind: 'loan', balance: 15000, monthly: 150, rate: 1 };
  const lnOk = await callAiApi({
    op: 'run', token: tok2,
    body: { task: 'loan-read', input: { text: 'PTPTN Balance 15,000.00 Monthly 150.00 Rate 1%', kinds: ['loan', 'standard'] } },
  });
  stubResult = { opening: 100, closing: 80, rows: [{ date: '2026-11-01', desc: 'GRAB', amount: 20, dir: 'out' }] };
  const stOk = await callAiApi({
    op: 'run', token: tok2,
    body: { task: 'statement-read', input: { text: 'Opening 100.00 2026-11-01 GRAB 20.00 Closing 80.00' } },
  });
  check('ai+ tasks: all 8 v1 tasks pass schema & guard checks through api/ai.js',
    veOk.data?.result?.amount === 12.5 && siOk.data?.result?.items?.length === 1
    && eaOk.data?.result?.b1a === 54000 && lnOk.data?.result?.balance === 15000
    && stOk.data?.result?.rows?.length === 1 && aiModels.MODELS.lite === 'gemini-2.5-flash-lite' && aiModels.MODELS.vision === 'gemini-2.5-flash',
    JSON.stringify({ ve: veOk.data?.ok, si: siOk.data?.ok, ea: eaOk.data?.ok, ln: lnOk.data?.ok, st: stOk.data?.ok }));

  // 6) Client-side Playwright checks: hidden by default, nothing sent when off,
  //    redaction, dual entitlement, live browser aiCloudRun & quota fallback.
  const aiCtx = await b.newContext({ viewport: { width: 390, height: 844 } });
  const aip = await aiCtx.newPage();
  let aiHits = 0;
  await aip.route('**/api/ai**', async (route) => {
    aiHits += 1;
    const u = new URL(route.request().url());
    const op = u.searchParams.get('op') || '';
    const hdrs = route.request().headers();
    const token = (hdrs.authorization || '').replace(/^Bearer\s+/i, '');
    const body = route.request().method() === 'POST' ? (route.request().postDataJSON() || {}) : {};
    const r = await callAiApi({ method: route.request().method(), op, body, token, ip: '10.0.0.9' });
    await route.fulfill({ status: r.status, contentType: 'application/json', body: JSON.stringify(r.data) });
  });

  await aip.goto(`${BASE}/app/index.html`);
  await aip.waitForTimeout(500);
  await aip.click('#btn-start-open');
  await aip.waitForTimeout(1500);

  const clientChecks = await aip.evaluate(async () => {
    const cardShownByDefault = document.getElementById('ai-cloud-card').hidden === false;
    const toggleOffByDefault = document.getElementById('ai-cloud-toggle').checked === false && state.aiPlusEnabled === false;
    const offRes = await aiCloudRun('payee-clean', { raw: 'PYMT*GRAB 8812 KL' });

    // On-device redaction check
    const rawSample = 'NRIC 920102-14-5678 card 4532 1234 5678 9012 email ali@example.my tel +6012-345 6789 No. 12, Jalan Bukit Bintang, 55100 Kuala Lumpur paid RM 45.90 on 2026-11-26';
    const red = redactForCloudAi({ raw: rawSample }, 'payee-clean').raw;
    const redactionOk = !red.includes('920102-14-5678') && !red.includes('4532 1234 5678 9012')
      && !red.includes('ali@example.my') && !red.includes('6012-345 6789') && !red.includes('Jalan Bukit Bintang')
      && red.includes('RM 45.90') && red.includes('2026-11-26');

    // Dual entitlement check (state.pro separate from state.aiSub)
    state.pro = false;
    state.proTrialStartedAt = 0;
    state.aiSub = { active: true, expiresAt: Date.now() + 86400000, subToken: '' };
    const proViaSub = isPro();
    state.pro = true;
    state.aiSub = { active: false, expiresAt: Date.now() - 1000, subToken: '' };
    const proKeptAfterCancel = isPro() && state.pro === true;
    const prices = {
      stdMo: aiPriceLabel('monthly', { proOwner: false }),
      stdYr: aiPriceLabel('yearly', { proOwner: false }),
      proMo: aiPriceLabel('monthly', { proOwner: true }),
      proYr: aiPriceLabel('yearly', { proOwner: true }),
    };

    return { cardShownByDefault, toggleOffByDefault, offRes, redactionOk, red, proViaSub, proKeptAfterCancel, prices };
  });

  check('ai+ client: off by default, zero network calls when off, redacts PII while keeping amounts/dates',
    clientChecks.cardShownByDefault && clientChecks.toggleOffByDefault && clientChecks.offRes === null && aiHits === 0 && clientChecks.redactionOk,
    JSON.stringify({ ...clientChecks, aiHits }));

  check('ai+ entitlement: state.pro || aiSubIsActive(), cancelling AI+ keeps Lifetime Pro, single price source',
    clientChecks.proViaSub && clientChecks.proKeptAfterCancel
    && clientChecks.prices.stdMo === 'RM 4.90/month' && clientChecks.prices.proYr === 'RM 35/year',
    JSON.stringify(clientChecks));

  // First-send redacted preview + live browser aiCloudRun via real api/ai.js
  stubResult = { payee: 'Grab' };
  const liveRun = await aip.evaluate(async (token) => {
    state.aiPlusDisclosureSeen = true;
    state.aiPlusEnabled = true;
    state.aiPlusPreviewedKinds = {};
    state.aiSub = { active: true, expiresAt: Date.now() + 86400000, subToken: token };
    renderAiCloudSettings();
    const cardShown = document.getElementById('ai-cloud-card').hidden === false;
    // Start run; first send of "payee" opens #ai-preview-dialog with redacted text
    const p = aiCloudRun('payee-clean', { raw: 'PYMT*GRAB ali@example.my 8812 KL' });
    await new Promise((r) => setTimeout(r, 50));
    const previewOpen = document.getElementById('ai-preview-dialog').open === true;
    const previewBody = document.getElementById('ai-preview-body').textContent || '';
    const previewRedacted = !previewBody.includes('ali@example.my') && previewBody.includes('[email]');
    document.getElementById('ai-preview-send').click();
    const res = await p;
    return { cardShown, previewOpen, previewRedacted, res };
  }, tok2);
  check('ai+ browser E2E: shows redacted preview before first send of each kind and succeeds via /api/ai?op=run',
    liveRun.cardShown && liveRun.previewOpen && liveRun.previewRedacted && liveRun.res?.payee === 'Grab' && aiHits >= 1,
    JSON.stringify({ liveRun, aiHits }));

  // Privacy & store-label surfaces updated in the same release
  const privFiles = [
    'privacy/index.html',
    'APP_STORE_LISTING.md',
    'PLAY_LISTING.md',
    'index.html',
    'ms/index.html',
    'llms.txt',
    'VERIFYING-PRIVACY.md',
  ];
  const privMissing = privFiles.filter((f) => !/Duitful AI\+/i.test(readFileSync(path.join(REPO_ROOT, f), 'utf8')));
  check('ai+ privacy surfaces: every policy, store listing, landing page, llms.txt, and VERIFYING-PRIVACY.md updated in same release',
    privMissing.length === 0, `missing: ${privMissing.join(', ') || 'none'}`);

  // Simulate quota exhausted (1000/1000 text calls) -> 429 -> aiCloudRun returns null cleanly
  // The meters are their own keys (ai_use:<subId>:<YYYY-MM>:<bucket>), never
  // fields on ai_sub (security review, 1.78.0).
  const kvStore = aiKv.store();
  const { verifyDeviceToken: verifyTok } = reqCjs(path.join(REPO_ROOT, 'api/_lib/ai/auth.js'));
  const quotaSubId = verifyTok(tok2).subId;
  const textUseKey = aiKv.keys.use(quotaSubId, aiKv.currentPeriodKey(), 'text');
  const subBeforeQuota = JSON.stringify(await kvStore.get(aiKv.keys.sub(quotaSubId)));
  await kvStore.set(textUseKey, 1000);
  const quotaFallback = await aip.evaluate(async () => await aiCloudRun('payee-clean', { raw: 'PYMT*GRAB 8812 KL' }));
  const quotaAfter = await kvStore.get(textUseKey);
  check('ai+ quota fallback: reaching 1,000 text cap returns null cleanly without blocking, and the refused call neither counts nor touches ai_sub',
    quotaFallback === null && Number(quotaAfter) === 1000
    && JSON.stringify(await kvStore.get(aiKv.keys.sub(quotaSubId))) === subBeforeQuota,
    JSON.stringify({ quotaFallback, quotaAfter }));

  // Phase 2: StoreKit 2 / Play Billing subscription receipt keeps state.pro separate,
  // encrypted backup reconnect syncs status, Web paywall is pair-only, and no LAUNCH100 on iOS.
  const subChecks = await aip.evaluate(async () => {
    state.pro = false;
    state.proTrialStartedAt = 0;
    state.aiSub = null;
    const isAi = isAiSubscriptionReceipt({ products: [{ id: 'duitful_ai_monthly' }] });
    const isNotAi = isAiSubscriptionReceipt({ products: [{ id: 'duitful_pro' }] });
    let finished = false;
    const res = await handleAiSubscriptionReceipt({
      products: [{ id: 'duitful_ai_monthly' }],
      transactionId: 'tx-phase2-ios-001',
      finish() { finished = true; },
    });
    const proUntouched = state.pro === false && isPro() === true && aiSubIsActive(state.aiSub);
    const reconnected = await aiReconnectAfterBackupRestore();

    // Web paywall: pair-only (native plans hidden, web pair shown, no LAUNCH100)
    openAiPaywall();
    const dlg = document.getElementById('ai-plus-dialog');
    const webPairOnly = dlg.open
      && document.getElementById('ai-plus-native-plans').hidden === true
      && document.getElementById('ai-plus-web-pair').hidden === false
      && !/LAUNCH100/i.test(dlg.textContent || '');
    closeAiPaywall();

    // Play Billing offer selection: Pro owners get pro-monthly/pro-yearly, regular users get base monthly/yearly ONLY
    const mockPlayProduct = {
      offers: [
        { id: 'monthly@pro-monthly', basePlanId: 'monthly', offerId: 'pro-monthly' },
        { id: 'monthly', basePlanId: 'monthly', offerId: null },
        { id: 'yearly@pro-yearly', basePlanId: 'yearly', offerId: 'pro-yearly' },
        { id: 'yearly', basePlanId: 'yearly', offerId: null },
      ],
    };
    const playOffersOk = pickPlayOffer(mockPlayProduct, 'monthly', false)?.id === 'monthly'
      && pickPlayOffer(mockPlayProduct, 'yearly', false)?.id === 'yearly'
      && pickPlayOffer(mockPlayProduct, 'monthly', true)?.id === 'monthly@pro-monthly'
      && pickPlayOffer(mockPlayProduct, 'yearly', true)?.id === 'yearly@pro-yearly';

    return { isAi, isNotAi, finished, ok: !!(res && res.ok), proUntouched, reconnected: !!(reconnected && reconnected.active), webPairOnly, playOffersOk };
  });
  check('ai+ Phase 2: store subscription verifies via api/ai.js, keeps state.pro separate, reconnects after backup restore, Play offers match Pro/base strictly, and Web paywall is pair-only',
    subChecks.isAi && !subChecks.isNotAi && subChecks.finished && subChecks.ok
    && subChecks.proUntouched && subChecks.reconnected && subChecks.webPairOnly && subChecks.playOffersOk,
    JSON.stringify(subChecks));

  delete global.__DUITFUL_AI_GEMINI_STUB__;
  await aiCtx.close();

  // ── AI+ store verification (1.78.0): Apple JWS chain + ES256, App Store
  // Server Notifications v2, Play RTDN re-fetch. A throwaway CA chain stands
  // in for Apple's; its root pin is honoured only in this in-memory mode.
  {
    const { iosSubId, androidSubId } = reqCjs(path.join(REPO_ROOT, 'api/_lib/ai/verify-sub.js'));
    const { resetJwksCache } = reqCjs(path.join(REPO_ROOT, 'api/_lib/ai/google-oidc.js'));
    const appleJwsSrc = readFileSync(path.join(REPO_ROOT, 'api/_lib/ai/apple-jws.js'), 'utf8');
    const webhookSrc = readFileSync(path.join(REPO_ROOT, 'api/_lib/ai/webhook.js'), 'utf8');
    const kvS = aiKv.store();
    let ipN = 0;
    const nextIp = () => `10.9.${Math.floor(ipN / 200)}.${(ipN++ % 200) + 1}`;
    const chain = makeAppleLikeChain();
    const t0 = Date.now();
    const txFor = (otid, extra = {}) => ({
      originalTransactionId: otid,
      transactionId: `${otid}-1`,
      bundleId: 'com.aydiljoe.duitful',
      productId: 'duitful_ai_monthly',
      type: 'Auto-Renewable Subscription',
      environment: 'Production',
      purchaseDate: t0 - 1000,
      expiresDate: t0 + 30 * 86400000,
      signedDate: t0,
      ...extra,
    });
    const verifyIos = (jws) => callAiApi({ op: 'verify-sub', ip: nextIp(), body: { platform: 'ios', plan: 'duitful_ai_monthly', signedTransactionInfo: jws } });
    // The entitlement is ai_sub (verify-sub) and ai_evt (webhook), newest store time wins.
    const { effectiveSub, VERIFIED } = reqCjs(path.join(REPO_ROOT, 'api/_lib/ai/entitlement.js'));
    const entOf = async (subId) => effectiveSub(await kvS.get(aiKv.keys.sub(subId)), await kvS.get(aiKv.keys.evt(subId)));
    const subOf = async (otid) => entOf(iosSubId(otid));

    // Before the test pin is set, the real Apple Root CA - G3 pin rejects the throwaway chain.
    delete process.env.AI_TEST_APPLE_ROOT_SHA256;
    const unpinned = await verifyIos(signAppleJws(txFor('otid-unpinned'), chain));
    process.env.AI_TEST_APPLE_ROOT_SHA256 = chain.rootSha256;

    const okJws = signAppleJws(txFor('otid-ok'), chain);
    const ok = await verifyIos(okJws);
    const okSub = await subOf('otid-ok');
    check('ai+ store verify (iOS): a JWS signed by the pinned chain is accepted, the plan comes from the signed productId, and the real Apple pin rejects any other root',
      unpinned.status === 400 && unpinned.data?.error === 'jws-untrusted-root' && !(await subOf('otid-unpinned'))
      && ok.status === 200 && ok.data?.ok && typeof ok.data.subToken === 'string' && ok.data.status?.active
      && okSub?.plan === 'duitful_ai_monthly' && okSub.expiresAt === t0 + 30 * 86400000
      && /63343abfb89a6a03ebb57e9b3f5fa7be7c4f5c756f3017b3a8c488c3653e9179/.test(appleJwsSrc)
      && /dsaEncoding: "ieee-p1363"/.test(appleJwsSrc),
      JSON.stringify({ unpinned: unpinned.data, ok: ok.data?.status }));

    const expiredLeaf = makeAppleLikeChain({ leafNotBefore: t0 - 10 * 86400000, leafNotAfter: t0 - 86400000 });
    const noMarkers = makeAppleLikeChain({ markers: false });
    const otherRoot = makeAppleLikeChain();
    const rejectCases = [
      ['tampered payload', tamperJwsPayload(signAppleJws(txFor('otid-tamper'), chain), { expiresDate: t0 + 900 * 86400000 }), 'jws-bad-signature', 'otid-tamper'],
      ['wrong alg', signAppleJws(txFor('otid-alg'), chain, { alg: 'ES384' }), 'jws-bad-alg', 'otid-alg'],
      ['alg none', `${Buffer.from(JSON.stringify({ alg: 'none', x5c: chain.x5c })).toString('base64url')}.${Buffer.from(JSON.stringify(txFor('otid-none'))).toString('base64url')}.`, 'jws-malformed', 'otid-none'],
      ['wrong root', signAppleJws(txFor('otid-root'), otherRoot), 'jws-untrusted-root', 'otid-root'],
      ['leaf signed by a stranger', signAppleJws(txFor('otid-leaf'), chain, { key: otherRoot.leafKey }), 'jws-bad-signature', 'otid-leaf'],
      ['wrong bundleId', signAppleJws(txFor('otid-bundle', { bundleId: 'com.example.other' }), chain), 'bundle-mismatch', 'otid-bundle'],
      ['wrong product', signAppleJws(txFor('otid-product', { productId: 'duitful_pro' }), chain), 'product-mismatch', 'otid-product'],
      ['expired subscription', signAppleJws(txFor('otid-exp', { expiresDate: t0 - 1000 }), chain), 'sub-expired', 'otid-exp'],
      ['revoked', signAppleJws(txFor('otid-rev', { revocationDate: t0 - 1000 }), chain), 'sub-revoked', 'otid-rev'],
      ['Sandbox without AI_IOS_ALLOW_SANDBOX', signAppleJws(txFor('otid-sbx', { environment: 'Sandbox' }), chain), 'sandbox-not-allowed', 'otid-sbx'],
    ];
    const rejected = [];
    for (const [label, jws, code, otid] of rejectCases) {
      const r = await verifyIos(jws);
      rejected.push({ label, status: r.status, error: r.data?.error, want: code, written: !!(await subOf(otid)), token: !!r.data?.subToken });
    }
    // Expired certificate and missing Apple marker OIDs need their own pins.
    process.env.AI_TEST_APPLE_ROOT_SHA256 = expiredLeaf.rootSha256;
    const rExpCert = await verifyIos(signAppleJws(txFor('otid-cert'), expiredLeaf));
    process.env.AI_TEST_APPLE_ROOT_SHA256 = noMarkers.rootSha256;
    const rNoMarker = await verifyIos(signAppleJws(txFor('otid-marker'), noMarkers));
    process.env.AI_TEST_APPLE_ROOT_SHA256 = chain.rootSha256;
    rejected.push({ label: 'expired certificate', status: rExpCert.status, error: rExpCert.data?.error, want: 'jws-cert-expired', written: !!(await subOf('otid-cert')), token: !!rExpCert.data?.subToken });
    rejected.push({ label: 'no Apple marker OIDs', status: rNoMarker.status, error: rNoMarker.data?.error, want: 'jws-not-apple', written: !!(await subOf('otid-marker')), token: !!rNoMarker.data?.subToken });
    const badRejects = rejected.filter((x) => x.status !== 400 || x.error !== x.want || x.written || x.token);
    check('ai+ store verify (iOS): tampered payload, wrong alg, alg none, wrong root, foreign leaf key, expired cert, no Apple markers, wrong bundleId, wrong product, expired, revoked and Sandbox are all refused with a code and nothing written',
      badRejects.length === 0, JSON.stringify(badRejects.length ? badRejects : rejected.map((x) => x.error)));

    // App Store Server Notifications v2
    const note = (type, otid, txExtra, { subtype, signedDate, renewal, env = 'Production' } = {}) => signAppleJws({
      notificationType: type,
      ...(subtype ? { subtype } : {}),
      notificationUUID: `uuid-${type}-${otid}-${signedDate}`,
      version: '2.0',
      signedDate,
      data: {
        bundleId: 'com.aydiljoe.duitful',
        environment: env,
        signedTransactionInfo: signAppleJws(txFor(otid, { signedDate, ...txExtra }), chain),
        ...(renewal ? { signedRenewalInfo: signAppleJws({ originalTransactionId: otid, signedDate, environment: env, ...renewal }, chain) } : {}),
      },
    }, chain);
    const hook = (signedPayload) => callAiApi({ op: 'webhook', ip: nextIp(), body: { signedPayload } });

    const renewTo = t0 + 60 * 86400000;
    const wRenew = await hook(note('DID_RENEW', 'otid-ok', { expiresDate: renewTo, transactionId: 'otid-ok-2' }, { signedDate: t0 + 1000 }));
    const afterRenew = await subOf('otid-ok');
    const wTamper = await callAiApi({ op: 'webhook', ip: nextIp(), body: { signedPayload: tamperJwsPayload(note('REFUND', 'otid-ok', { revocationDate: t0 }, { signedDate: t0 + 1500 }), { signedDate: t0 + 1600 }) } });
    const afterTamper = await subOf('otid-ok');
    const wRefund = await hook(note('REFUND', 'otid-ok', { expiresDate: renewTo, revocationDate: t0 + 2000 }, { signedDate: t0 + 2000 }));
    const afterRefund = await subOf('otid-ok');
    const stRefund = await callAiApi({ method: 'GET', op: 'status', token: ok.data.subToken });
    const wStale = await hook(note('DID_RENEW', 'otid-ok', { expiresDate: renewTo }, { signedDate: t0 + 1200 }));
    const afterStale = await subOf('otid-ok');
    const replay = await verifyIos(okJws);
    const afterReplay = await subOf('otid-ok');
    const legacy = await callAiApi({ op: 'webhook', ip: nextIp(), body: { subId: iosSubId('otid-ok'), active: true, expiresAt: t0 + 999 * 86400000 } });
    const afterLegacy = await subOf('otid-ok');
    check('ai+ store webhook (ASSN v2): DID_RENEW extends, REFUND switches off, a tampered payload, a stale renewal, a replayed pre-refund JWS and the old trust-the-body shape change nothing',
      wRenew.status === 200 && afterRenew?.active === true && afterRenew.expiresAt === renewTo
      && wTamper.status === 401 && wTamper.data?.error === 'jws-bad-signature' && afterTamper?.active === true
      && wRefund.status === 200 && afterRefund?.active === false && stRefund.data?.status?.active === false
      && wStale.status === 200 && wStale.data?.ignored === 'stale' && afterStale?.active === false
      && replay.status === 400 && replay.data?.error === 'sub-inactive' && afterReplay?.active === false
      && legacy.status === 400 && legacy.data?.error === 'unknown-webhook' && afterLegacy?.active === false
      && !/body\.subId/.test(webhookSrc),
      JSON.stringify({ renew: wRenew.data, tamper: wTamper.data, refund: wRefund.data, stale: wStale.data, replay: replay.data, legacy: legacy.data }));

    const vB = await verifyIos(signAppleJws(txFor('otid-b'), chain));
    const wExpired = await hook(note('EXPIRED', 'otid-b', { expiresDate: t0 - 1 }, { subtype: 'VOLUNTARY', signedDate: t0 + 3000 }));
    const afterExpired = await subOf('otid-b');
    const graceTo = t0 + 16 * 86400000;
    const wGrace = await hook(note('DID_FAIL_TO_RENEW', 'otid-b', { expiresDate: t0 - 1 }, { subtype: 'GRACE_PERIOD', signedDate: t0 + 4000, renewal: { gracePeriodExpiresDate: graceTo } }));
    const afterGrace = await subOf('otid-b');
    const wTest = await hook(signAppleJws({ notificationType: 'TEST', version: '2.0', signedDate: t0, data: { bundleId: 'com.aydiljoe.duitful', environment: 'Production' } }, chain));
    const wPro = await hook(note('REFUND', 'otid-b', { productId: 'duitful_pro', type: 'Non-Consumable', revocationDate: t0 }, { signedDate: t0 + 5000 }));
    const afterPro = await subOf('otid-b');
    check('ai+ store webhook (ASSN v2): EXPIRED switches off, DID_FAIL_TO_RENEW / GRACE_PERIOD keeps AI+ until the grace date, TEST is acknowledged, and a Lifetime Pro refund never touches AI+',
      vB.status === 200 && wExpired.status === 200 && afterExpired?.active === false
      && wGrace.status === 200 && afterGrace?.active === true && afterGrace.expiresAt === graceTo
      && wTest.status === 200 && wTest.data?.test === true
      && wPro.status === 200 && wPro.data?.ignored === 'not-ai-plus' && afterPro?.active === true,
      JSON.stringify({ expired: wExpired.data, grace: wGrace.data, test: wTest.data, pro: wPro.data }));

    // ── Security review fixes (1.78.0) ──────────────────────────────────────
    const { signDeviceToken } = reqCjs(path.join(REPO_ROOT, 'api/_lib/ai/auth.js'));
    const aiSrc = (f) => readFileSync(path.join(REPO_ROOT, 'api/_lib/ai', f), 'utf8');

    // (1) A refund that lands while a run is waiting on Gemini stays: run
    // never writes ai_sub / ai_evt, the meter is an INCR on its own key.
    {
      const tR = Date.now();
      const vR = await verifyIos(signAppleJws(txFor('otid-race', { signedDate: tR, purchaseDate: tR - 1000 }), chain));
      let release;
      let entered;
      const enteredP = new Promise((r) => { entered = r; });
      global.__DUITFUL_AI_GEMINI_STUB__ = async () => { entered(); await new Promise((r) => { release = r; }); return { payee: 'Grab' }; };
      const inFlight = callAiApi({ op: 'run', token: vR.data?.subToken, ip: nextIp(), body: { task: 'payee-clean', input: { raw: 'PYMT*GRAB 8812 KL' } } });
      await enteredP;
      const tRefund = Date.now();
      const wR = await hook(note('REFUND', 'otid-race', { expiresDate: tR + 30 * 86400000, revocationDate: tRefund }, { signedDate: tRefund }));
      release();
      const runR = await inFlight;
      const afterRun = await subOf('otid-race');
      const stR = await callAiApi({ method: 'GET', op: 'status', token: vR.data?.subToken });
      const runAgain = await callAiApi({ op: 'run', token: vR.data?.subToken, ip: nextIp(), body: { task: 'payee-clean', input: { raw: 'PYMT*GRAB 8812 KL' } } });
      const meter = await kvS.get(aiKv.keys.use(iosSubId('otid-race'), aiKv.currentPeriodKey(), 'text'));
      delete global.__DUITFUL_AI_GEMINI_STUB__;
      const writesSub = (src) => /kv\.set\(\s*keys\.(sub|evt)\(/.test(src);
      check('ai+ security (race): a REFUND that lands while a run waits on Gemini is not undone; run, status and pair never write ai_sub / ai_evt, the webhook never writes ai_sub and verify-sub never writes ai_evt',
        vR.status === 200 && wR.status === 200 && runR.status === 200 && runR.data?.ok
        && afterRun?.active === false && stR.data?.status?.active === false
        && runAgain.status === 403 && runAgain.data?.error === 'inactive-subscription' && Number(meter) === 1
        && !writesSub(aiSrc('run.js')) && !writesSub(aiSrc('pair.js')) && !writesSub(aiSrc('status.js'))
        && !/kv\.set\(\s*keys\.sub\(/.test(aiSrc('webhook.js')) && !/kv\.set\(\s*keys\.evt\(/.test(aiSrc('verify-sub.js'))
        && /kv\.incr\(/.test(aiSrc('entitlement.js')),
        JSON.stringify({ vR: vR.status, wR: wR.data, runR: runR.data?.ok, afterRun, st: stR.data?.status?.active, again: runAgain.data, meter }));
    }

    // (2) A REFUND for a subscription verify-sub never saw leaves a tombstone:
    // the saved, pre-refund JWS is refused later; a newer purchase is not.
    {
      const tBuy = Date.now() - 10000;
      const tRefund = Date.now() - 5000;
      const savedJws = signAppleJws(txFor('otid-tomb', { signedDate: tBuy, purchaseDate: tBuy - 1000 }), chain);
      const wT = await hook(note('REFUND', 'otid-tomb', { expiresDate: tBuy + 365 * 86400000, revocationDate: tRefund, productId: 'duitful_ai_yearly' }, { signedDate: tRefund }));
      const tomb = await kvS.get(aiKv.keys.evt(iosSubId('otid-tomb')));
      const replayT = await verifyIos(savedJws);
      const devAfterReplay = await kvS.get(aiKv.keys.dev(iosSubId('otid-tomb')));
      const wE = await hook(note('EXPIRED', 'otid-tomb2', { expiresDate: tBuy + 1000 }, { subtype: 'VOLUNTARY', signedDate: tRefund }));
      const tomb2 = await kvS.get(aiKv.keys.evt(iosSubId('otid-tomb2')));
      const tNew = Date.now();
      const rebuy = await verifyIos(signAppleJws(txFor('otid-tomb', { signedDate: tNew, purchaseDate: tNew - 500, transactionId: 'otid-tomb-2', expiresDate: tNew + 30 * 86400000 }), chain));
      check('ai+ security (tombstone): REFUND / EXPIRED for an unknown sub is stored inactive, so a replayed pre-refund JWS gets no token, while a purchase signed after it still works',
        wT.status === 200 && wT.data?.tombstone === true && tomb?.active === false && tomb.verified === VERIFIED && tomb.storeEventAt === tRefund
        && replayT.status === 400 && replayT.data?.error === 'sub-inactive' && !replayT.data?.subToken && !devAfterReplay
        && wE.status === 200 && tomb2?.active === false
        && rebuy.status === 200 && rebuy.data?.status?.active === true,
        JSON.stringify({ wT: wT.data, tomb, replay: replayT.data, wE: wE.data, rebuy: rebuy.data?.error || rebuy.status }));
    }

    // (3) Records written before store verification (no `verified` marker,
    // expiry possibly the client's own) count for nothing until re-verified.
    {
      const legacyId = iosSubId('otid-legacy');
      const period = aiKv.currentPeriodKey();
      await kvS.set(aiKv.keys.sub(legacyId), {
        subId: legacyId, platform: 'ios', plan: 'duitful_ai_yearly', active: true, expiresAt: 4102444800000,
        periodKey: period, scansUsed: 3, textUsed: 7, devices: [{ slotId: 'legacySlot0001', label: 'x', addedAt: 1 }],
      });
      const legacyTok = signDeviceToken({ subId: legacyId, slotId: 'legacySlot0001' });
      const lRun = await callAiApi({ op: 'run', token: legacyTok, ip: nextIp(), body: { task: 'payee-clean', input: { raw: 'GRAB KL' } } });
      const lStatus = await callAiApi({ method: 'GET', op: 'status', token: legacyTok });
      const lPair = await callAiApi({ op: 'pair-start', token: legacyTok, ip: nextIp() });
      const tL = Date.now();
      const lVerify = await verifyIos(signAppleJws(txFor('otid-legacy', { signedDate: tL, purchaseDate: tL - 1000 }), chain));
      const lRaw = await kvS.get(aiKv.keys.sub(legacyId));
      const lOldTok = await callAiApi({ method: 'GET', op: 'status', token: legacyTok });
      const lNewTok = await callAiApi({ method: 'GET', op: 'status', token: lVerify.data?.subToken });
      check('ai+ security (legacy records): run / status / pair-start refuse an unverified record with reverify-required; re-verifying replaces it with the store\'s expiry, drops its devices and keeps this month\'s meters',
        lRun.status === 403 && lRun.data?.error === 'reverify-required' && lRun.data?.status?.active === false
        && lStatus.status === 403 && lStatus.data?.error === 'reverify-required'
        && lPair.status === 403 && lPair.data?.error === 'reverify-required'
        && lVerify.status === 200 && lRaw?.verified === VERIFIED && lRaw.expiresAt === t0 + 30 * 86400000 && !('devices' in lRaw)
        && lOldTok.status === 401 && lNewTok.status === 200 && lNewTok.data?.status?.active === true
        && lNewTok.data.status.devicesCount === 1 && lNewTok.data.status.textUsed === 7 && lNewTok.data.status.scansUsed === 3,
        JSON.stringify({ run: lRun.data, status: lStatus.data?.error, pair: lPair.data, verify: lVerify.data?.error || lVerify.status, lRaw, old: lOldTok.status, fresh: lNewTok.data?.status }));
    }

    // (4) Sandbox (App Review / TestFlight) is its own class: own subId, a
    // 24 h hard cap, a small quota.
    {
      process.env.AI_IOS_ALLOW_SANDBOX = '1';
      const tS = Date.now();
      const sbx = await verifyIos(signAppleJws(txFor('otid-sbx2', { environment: 'Sandbox', signedDate: tS, purchaseDate: tS - 1000, expiresDate: tS + 30 * 86400000 }), chain));
      const sbxRaw = await kvS.get(aiKv.keys.sub(iosSubId('otid-sbx2', true)));
      const prodSlot = await kvS.get(aiKv.keys.sub(iosSubId('otid-sbx2')));
      await kvS.set(aiKv.keys.use(iosSubId('otid-sbx2', true), aiKv.currentPeriodKey(), 'text'), aiModels.SANDBOX_QUOTA_LIMITS.text);
      const sbxRun = await callAiApi({ op: 'run', token: sbx.data?.subToken, ip: nextIp(), body: { task: 'payee-clean', input: { raw: 'GRAB KL' } } });
      delete process.env.AI_IOS_ALLOW_SANDBOX;
      const sbxOff = await callAiApi({ method: 'GET', op: 'status', token: sbx.data?.subToken });
      check('ai+ security (Sandbox): with AI_IOS_ALLOW_SANDBOX a Sandbox JWS gets an ios_sbx_ record capped at 24 h with the Sandbox quota (10 scans / 50 text), never the production record, and switching the variable off cuts it at once',
        sbx.status === 200 && sbx.data?.status?.sandbox === true
        && sbx.data.status.expiresAt <= Date.now() + aiModels.SANDBOX_MAX_MS && sbx.data.status.expiresAt > Date.now()
        && sbx.data.status.scansLimit === 10 && sbx.data.status.textLimit === 50
        && sbxRaw?.sandbox === true && !prodSlot && iosSubId('otid-sbx2', true).startsWith('ios_sbx_')
        && sbxRun.status === 429 && sbxRun.data?.error === 'quota'
        && sbxOff.status === 200 && sbxOff.data?.status?.active === false,
        JSON.stringify({ sbx: sbx.data?.status || sbx.data, run: sbxRun.data?.error }));
    }

    // (5) A refund of an earlier period (the sub has renewed since) leaves the
    // running period on; a refund of the running one switches it off.
    {
      const tP = Date.now();
      const vP = await verifyIos(signAppleJws(txFor('otid-past', { signedDate: tP - 2000, purchaseDate: tP - 40 * 86400000, transactionId: 'otid-past-1', expiresDate: tP + 5 * 86400000 }), chain));
      const wRen = await hook(note('DID_RENEW', 'otid-past', { transactionId: 'otid-past-2', purchaseDate: tP - 1500, expiresDate: tP + 35 * 86400000 }, { signedDate: tP - 1500 }));
      const wOld = await hook(note('REFUND', 'otid-past', { transactionId: 'otid-past-0', purchaseDate: tP - 70 * 86400000, expiresDate: tP - 40 * 86400000, revocationDate: tP - 1000 }, { signedDate: tP - 1000 }));
      const afterOld = await subOf('otid-past');
      const reverify = await verifyIos(signAppleJws(txFor('otid-past', { signedDate: tP - 1500, purchaseDate: tP - 1500, transactionId: 'otid-past-2', expiresDate: tP + 35 * 86400000 }), chain));
      const wCur = await hook(note('REFUND', 'otid-past', { transactionId: 'otid-past-2', purchaseDate: tP - 1500, expiresDate: tP + 35 * 86400000, revocationDate: tP - 500 }, { signedDate: tP - 500 }));
      const afterCur = await subOf('otid-past');
      check('ai+ security (refund scope): a REFUND of a past period is ignored and the current JWS still verifies; a REFUND of the running period switches AI+ off',
        vP.status === 200 && wRen.status === 200
        && wOld.status === 200 && wOld.data?.ignored === 'past-period' && afterOld?.active === true && afterOld.expiresAt === tP + 35 * 86400000
        && reverify.status === 200 && reverify.data?.status?.active === true
        && wCur.status === 200 && afterCur?.active === false,
        JSON.stringify({ old: wOld.data, afterOld, reverify: reverify.data?.error || reverify.status, cur: wCur.data, afterCur }));
    }

    // Google Play: verify-sub and RTDN both ask subscriptionsv2.get; the RTDN
    // message's own content is never trusted. Pub/Sub's OIDC token is checked.
    const savedFetch = globalThis.fetch;
    const savedEnv = {
      sa: process.env.GOOGLE_PLAY_SERVICE_ACCOUNT_JSON,
      aud: process.env.AI_RTDN_AUDIENCE,
      email: process.env.AI_RTDN_SERVICE_ACCOUNT,
    };
    const oidc = makeGoogleOidc();
    const rtdnAud = 'https://duitful.app/api/ai/?op=webhook';
    const rtdnEmail = 'rtdn-push@duitful-test.iam.gserviceaccount.com';
    process.env.GOOGLE_PLAY_SERVICE_ACCOUNT_JSON = makePlayServiceAccount();
    process.env.AI_RTDN_AUDIENCE = rtdnAud;
    process.env.AI_RTDN_SERVICE_ACCOUNT = rtdnEmail;
    resetJwksCache();
    const playToken = 'play-token-ai-0001-abcdefghijklmnop';
    let playTruth = null;
    let playCalls = 0;
    let ackCalls = 0;
    let playGate = null; // { entered, wait }: holds the next subscriptionsv2 answer
    globalThis.fetch = async (url, init = {}) => {
      const u = String(url);
      const json = (obj, status = 200) => new Response(JSON.stringify(obj), { status, headers: { 'content-type': 'application/json', 'cache-control': 'public, max-age=3600' } });
      if (u === 'https://oauth2.googleapis.com/token') return json({ access_token: 'test-access-token' });
      if (u === 'https://www.googleapis.com/oauth2/v3/certs') return json(oidc.jwks);
      if (u.startsWith('https://androidpublisher.googleapis.com/') && u.endsWith(`/purchases/subscriptions/duitful_ai/tokens/${encodeURIComponent(playToken)}:acknowledge`) && init.method === 'POST') {
        ackCalls += 1;
        return json({});
      }
      if (u.startsWith('https://androidpublisher.googleapis.com/') && u.endsWith(`/tokens/${encodeURIComponent(playToken)}`)) {
        playCalls += 1;
        const answer = playTruth;
        if (playGate) { const g = playGate; playGate = null; g.entered(); await g.wait; }
        return json(answer);
      }
      return json({ error: 'unexpected' }, 404);
    };
    const truth = (state, expiry) => ({ subscriptionState: state, lineItems: [{ productId: 'duitful_ai', expiryTime: new Date(expiry).toISOString() }] });
    const pubsub = (msg) => ({ message: { data: Buffer.from(JSON.stringify(msg)).toString('base64'), messageId: '1' }, subscription: 'projects/x/subscriptions/y' });
    const rtdnMsg = (type) => pubsub({ version: '1.0', packageName: 'com.aydiljoe.duitful', eventTimeMillis: String(Date.now()), subscriptionNotification: { version: '1.0', notificationType: type, purchaseToken: playToken, subscriptionId: 'duitful_ai' } });
    const bearer = (claims) => ({ authorization: `Bearer ${oidc.sign({ iss: 'https://accounts.google.com', aud: rtdnAud, email: rtdnEmail, email_verified: true, iat: Math.floor(Date.now() / 1000), exp: Math.floor(Date.now() / 1000) + 3600, ...claims })}` });
    const andSub = async () => entOf(androidSubId(playToken));
    try {
      playTruth = truth('SUBSCRIPTION_STATE_ACTIVE', Date.now() + 30 * 86400000);
      const vA = await callAiApi({ op: 'verify-sub', ip: nextIp(), body: { platform: 'android', plan: 'duitful_ai', purchaseToken: playToken } });
      const callsAfterVerify = playCalls;

      // The message says "renewed" (type 2); Google says expired. Google wins.
      playTruth = truth('SUBSCRIPTION_STATE_EXPIRED', Date.now() - 1000);
      const noAuth = await callAiApi({ op: 'webhook', ip: nextIp(), body: rtdnMsg(2) });
      const badAud = await callAiApi({ op: 'webhook', ip: nextIp(), body: rtdnMsg(2), headers: bearer({ aud: 'https://evil.example/' }) });
      const badEmail = await callAiApi({ op: 'webhook', ip: nextIp(), body: rtdnMsg(2), headers: bearer({ email: 'someone@evil.example' }) });
      const afterBadAuth = await andSub();
      const callsAfterBadAuth = playCalls;
      const rExpire = await callAiApi({ op: 'webhook', ip: nextIp(), body: rtdnMsg(2), headers: bearer({}) });
      const afterExpire = await andSub();
      const callsAfterExpire = playCalls;

      const renewedTo = Date.now() + 40 * 86400000;
      playTruth = truth('SUBSCRIPTION_STATE_CANCELED', renewedTo);
      const rBack = await callAiApi({ op: 'webhook', ip: nextIp(), body: rtdnMsg(3), headers: bearer({}) });
      const afterBack = await andSub();
      const wrongPkg = await callAiApi({ op: 'webhook', ip: nextIp(), body: pubsub({ packageName: 'com.example.other', subscriptionNotification: { notificationType: 2, purchaseToken: playToken, subscriptionId: 'duitful_ai' } }), headers: bearer({}) });

      check('ai+ store verify (Android): verify-sub and RTDN re-fetch subscriptionsv2 instead of trusting the message; Pub/Sub OIDC (audience, service account) is required; a cancelled sub keeps AI+ until expiry',
        vA.status === 200 && vA.data?.status?.active && callsAfterVerify === 1
        && noAuth.status === 401 && badAud.status === 401 && badAud.data?.error === 'oidc-bad-audience'
        && badEmail.status === 401 && badEmail.data?.error === 'oidc-bad-email'
        && afterBadAuth?.active === true && callsAfterBadAuth === 1
        && rExpire.status === 200 && afterExpire?.active === false && callsAfterExpire === 2 && playCalls === 3
        && rBack.status === 200 && afterBack?.active === true && afterBack.expiresAt === Date.parse(new Date(renewedTo).toISOString())
        && wrongPkg.status === 400 && wrongPkg.data?.error === 'bundle-mismatch',
        JSON.stringify({ vA: vA.data?.error || vA.status, noAuth: noAuth.data, badAud: badAud.data, badEmail: badEmail.data, rExpire: rExpire.data, rBack: rBack.data, playCalls }));

      // Security review (1.78.0): a verify-sub that asked Google before an
      // RTDN did can't switch the sub back on after the RTDN stored "expired".
      playTruth = truth('SUBSCRIPTION_STATE_ACTIVE', Date.now() + 30 * 86400000);
      let gateEntered;
      let gateRelease;
      const gateEnteredP = new Promise((r) => { gateEntered = r; });
      playGate = { entered: gateEntered, wait: new Promise((r) => { gateRelease = r; }) };
      const slowVerify = callAiApi({ op: 'verify-sub', ip: nextIp(), body: { platform: 'android', plan: 'duitful_ai', purchaseToken: playToken } });
      await gateEnteredP;
      await new Promise((r) => setTimeout(r, 5));
      playTruth = truth('SUBSCRIPTION_STATE_EXPIRED', Date.now() - 1000);
      const rLate = await callAiApi({ op: 'webhook', ip: nextIp(), body: rtdnMsg(13), headers: bearer({}) });
      gateRelease();
      const slow = await slowVerify;
      const afterRace = await andSub();

      // A purchase Google still lists as unacknowledged is acknowledged by the server.
      playTruth = { ...truth('SUBSCRIPTION_STATE_ACTIVE', Date.now() + 30 * 86400000), acknowledgementState: 'ACKNOWLEDGEMENT_STATE_PENDING' };
      const vAck = await callAiApi({ op: 'verify-sub', ip: nextIp(), body: { platform: 'android', plan: 'duitful_ai', purchaseToken: playToken } });
      const acksAfterPending = ackCalls;
      playTruth = { ...truth('SUBSCRIPTION_STATE_ACTIVE', Date.now() + 30 * 86400000), acknowledgementState: 'ACKNOWLEDGEMENT_STATE_ACKNOWLEDGED' };
      const vAcked = await callAiApi({ op: 'verify-sub', ip: nextIp(), body: { platform: 'android', plan: 'duitful_ai', purchaseToken: playToken } });

      // With OIDC configured, the log-visible ?key= secret is no longer accepted.
      process.env.AI_WEBHOOK_SECRET = 'rtdn-shared-secret-for-tests';
      const keyOnly = await callAiApi({ op: 'webhook', ip: nextIp(), body: rtdnMsg(2), query: { key: 'rtdn-shared-secret-for-tests' } });
      delete process.env.AI_WEBHOOK_SECRET;

      check('ai+ security (Android): a verify-sub that asked Google before an RTDN can\'t undo the RTDN\'s "expired"; a pending purchase is acknowledged on the server (once); with OIDC set, ?key= is refused',
        rLate.status === 200 && slow.status === 400 && slow.data?.error === 'sub-inactive' && afterRace?.active === false
        && vAck.status === 200 && acksAfterPending === 1 && vAcked.status === 200 && ackCalls === 1
        && keyOnly.status === 401 && keyOnly.data?.error === 'oidc-missing',
        JSON.stringify({ rLate: rLate.data, slow: slow.data, afterRace, vAck: vAck.data?.error || vAck.status, ackCalls, keyOnly: keyOnly.data }));
    } finally {
      globalThis.fetch = savedFetch;
      for (const [k, v] of [['GOOGLE_PLAY_SERVICE_ACCOUNT_JSON', savedEnv.sa], ['AI_RTDN_AUDIENCE', savedEnv.aud], ['AI_RTDN_SERVICE_ACCOUNT', savedEnv.email]]) {
        if (v === undefined) delete process.env[k]; else process.env[k] = v;
      }
      delete process.env.AI_TEST_APPLE_ROOT_SHA256;
      resetJwksCache();
    }
  }
}
// ── Kira phase 2 (v1.75.0): eyes, taps, celebrations, kind notes, hops,
// first run, the tour and the widgets ─────────────────────────────────────
{
  // Widgets: both platforms draw Kira (static), proud while a streak runs.
  const aWidget = readFileSync(path.join(REPO_ROOT, 'scripts', 'patch-android-widget.mjs'), 'utf8');
  const iWidget = readFileSync(path.join(REPO_ROOT, 'scripts', 'patch-ios.mjs'), 'utf8');
  const iWidgetBody = iWidget.slice(iWidget.indexOf('const WIDGET_SWIFT_BODY'));
  check('Kira (1.75.0): the Android widget draws Kira as a VectorDrawable per mood and theme, proud while a streak runs',
    /duitful_widget_kira_\$\{mood\}_\$\{mode\}\.xml/.test(aWidget)
    && /<vector xmlns:android/.test(aWidget.slice(aWidget.indexOf('const kiraVector')))
    && /R\.drawable\.duitful_widget_kira_proud_pastel/.test(aWidget)
    && /R\.drawable\.duitful_widget_kira_happy_dark/.test(aWidget)
    && (aWidget.match(/setImageViewResource\(R\.id\.duitful_widget_kira, kiraRes\(mode\)\)/g) || []).length === 2
    && /boolean proud = !sLocked && sStreakDays > 0/.test(aWidget));
  check('Kira (1.75.0): the iOS widget draws Kira with SwiftUI Shapes on the medium and large status tiles',
    /private struct DuitfulKiraBody: Shape/.test(iWidgetBody)
    && /private struct DuitfulKiraFace: Shape/.test(iWidgetBody)
    && /\.accessibilityHidden\(true\)/.test(iWidgetBody.slice(iWidgetBody.indexOf('struct DuitfulKiraView')))
    && (iWidgetBody.match(/DuitfulKiraView\(mode: mode, proud: entry\.streakDays > 0\)/g) || []).length === 2);

  // The extra hops: voice, accepted alerts (spend and income), a scanned receipt.
  const src = (f) => readFileSync(path.join(REPO_ROOT, 'app', f), 'utf8');
  const fnBody = (s, name) => { const i = s.indexOf(name); return i < 0 ? '' : s.slice(i, s.indexOf('\n}', i)); };
  check('Kira (1.75.0): Kira hops after a voice entry, an accepted alert (spend and income) and a saved receipt scan — not on statement import',
    /kiraHop\(\)/.test(fnBody(src('voice.js'), 'function voiceSaveConfirmed'))
    && /kiraHop\(\)/.test(fnBody(src('script.js'), 'function acceptPending('))
    && /kiraHop\(\)/.test(fnBody(src('capture.js'), 'function acceptIncomePending('))
    && /kiraHop\(\)/.test(fnBody(src('ocr.js'), 'function applyScanResult('))
    && !/kiraHop/.test(src('statement.js')));

  for (const reduced of [false, true]) {
    const kCtx = await b.newContext({ viewport: { width: 390, height: 844 }, reducedMotion: reduced ? 'reduce' : 'no-preference' });
    const kp = await kCtx.newPage();
    const kErr = [];
    kp.on('pageerror', (e) => kErr.push(e.message));
    await kp.goto(`${BASE}/app/index.html`);
    await kp.waitForTimeout(600);
    await kp.click('#btn-start-open');
    await kp.waitForTimeout(1500);

    // First run: Kira beside each question, the answer celebrates a date.
    const ob = await kp.evaluate(async () => {
      const wait = (ms) => new Promise((res) => setTimeout(res, ms));
      const out = {};
      if (!document.getElementById('onboard-dialog').open) openOnboard();
      await wait(150);
      const k = (n) => document.querySelector(`#onboard-dialog [data-onboard-step="${n}"] .onboard-kira svg.kira`);
      const head1 = document.querySelector('[data-onboard-step="1"] .onboard-head');
      out.s1 = !!k(1) && k(1).classList.contains('kira--happy') && k(1).classList.contains('is-waving') && !!head1.querySelector('#onboard-title');
      const inp = document.getElementById('onboard-income').getBoundingClientRect();
      const kr = k(1).getBoundingClientRect();
      out.inputAboveKeyboard = inp.bottom <= innerHeight - 336;
      out.kiraNotOverInput = kr.bottom <= inp.top || kr.top >= inp.bottom;
      document.getElementById('onboard-income').value = '4500';
      document.querySelector('[data-onboard-step="1"] [data-onboard="next"]').click();
      await wait(100);
      out.s2 = !!k(2) && k(2).classList.contains('kira--proud');
      document.querySelector('[data-onboard-step="2"] [data-onboard="next"]').click();
      await wait(100);
      out.s3 = !!k(3) && k(3).classList.contains('kira--happy');
      out.neverWorried = !document.querySelector('#onboard-dialog svg.kira--worried');
      out.onePerStep = [1, 2, 3, 4].every((n) => document.querySelectorAll(`#onboard-dialog [data-onboard-step="${n}"] svg.kira`).length <= 1);
      document.querySelector('[data-onboard-debt="card"]').click();
      await wait(50);
      document.querySelector('#onboard-debt-rows .onboard-debt-balance').value = '6000';
      document.querySelector('#onboard-debt-rows .onboard-debt-monthly').value = '400';
      document.querySelector('#onboard-debt-rows .onboard-debt-monthly').dispatchEvent(new Event('input', { bubbles: true }));
      document.getElementById('onboard-debt-next').click();
      await wait(150);
      out.answerParty = !!k(4) && k(4).classList.contains('kira--party');
      out.answerBurst = document.querySelectorAll('[data-onboard-step="4"] .onboard-kira .kira-burst i').length;
      // Back to step 3, drop the debt: the answer is left-to-spend, proud Kira.
      document.querySelector('[data-onboard-step="4"]').hidden = true;
      onboardShowStep(3);
      document.getElementById('onboard-debt-rows').innerHTML = '';
      onboardSyncDebtStep();
      document.getElementById('onboard-debt-next').click();
      await wait(150);
      out.answerProud = !!k(4) && k(4).classList.contains('kira--proud');
      closeOnboard();
      return out;
    });
    await kp.evaluate(() => document.querySelectorAll('dialog[open]').forEach((d) => d.close()));
    await kp.evaluate(() => { state.debts = []; state.expenses = []; state.income = []; state.extraMonthly = 0; save(); renderAll(); });

    // Eyes follow a real pointerdown and come back; a tap on Kira squishes
    // without reaching anything around it.
    await kp.evaluate(() => document.querySelector('.tab[data-tab="savings"]').click());
    await kp.waitForTimeout(300);
    const kb = await kp.evaluate(() => { const r = document.querySelector('#savings-list .empty-block-kira svg.kira').getBoundingClientRect(); return { x: r.x, y: r.y, w: r.width, h: r.height }; });
    await kp.mouse.click(6, kb.y + kb.h / 2);
    await kp.waitForTimeout(200);
    const eyesLeft = await kp.evaluate(() => document.querySelector('#savings-list .kira-eyes').style.transform);
    await kp.mouse.click(384, kb.y + kb.h / 2);
    await kp.waitForTimeout(200);
    const eyesRight = await kp.evaluate(() => document.querySelector('#savings-list .kira-eyes').style.transform);
    await kp.waitForTimeout(1500);
    const eyesRest = await kp.evaluate(() => document.querySelector('#savings-list .kira-eyes').style.transform);
    const tap = await kp.evaluate(() => {
      window.__kiraClicks = 0;
      const block = document.querySelector('#savings-list .empty-block');
      block.querySelectorAll('button').forEach((btn) => btn.addEventListener('click', () => { window.__kiraClicks++; }));
      const svg = block.querySelector('svg.kira');
      const r = svg.getBoundingClientRect();
      // Outside the receipt's own paper (the SVG's empty corner) the pointer
      // passes through; on the paper it is Kira.
      const corner = document.elementFromPoint(r.left + 1, r.top + 1);
      return {
        cornerNotKira: !corner || !corner.closest('svg.kira'),
        paperIsKira: !!document.elementFromPoint(r.left + r.width / 2, r.top + r.height * 0.55)?.closest('svg.kira'),
        notFocusable: svg.getAttribute('focusable') === 'false' && !svg.hasAttribute('tabindex') && svg.getAttribute('aria-hidden') === 'true',
      };
    });
    await kp.mouse.click(kb.x + kb.w / 2, kb.y + kb.h * 0.55);
    await kp.waitForTimeout(120);
    const tapped = await kp.evaluate(() => {
      const svg = document.querySelector('#savings-list svg.kira');
      return { cls: svg.classList.contains('is-tapped'), anim: getComputedStyle(svg).animationName, hehe: !!svg.querySelector('.kira-hehe'), clicks: window.__kiraClicks, dialog: !!document.querySelector('dialog[open]') };
    });
    await kp.waitForTimeout(600);
    const tapDone = await kp.evaluate(() => !document.querySelector('#savings-list svg.kira').classList.contains('is-tapped') && !document.querySelector('.kira-hehe'));
    // The AI sheet's counting Kira is never poked.
    const aiLeftAlone = await kp.evaluate(() => { const s = document.querySelector('#ai-think svg.kira--counting'); kiraTap(s); return !s.classList.contains('is-tapped'); });

    const r = await kp.evaluate(async () => {
      const wait = (ms) => new Promise((res) => setTimeout(res, ms));
      const out = {};
      document.querySelector('.tab[data-tab="dashboard"]').click();
      // A debt paid off: party Kira beside the seal, a burst, once.
      state.debts.push({ id: 'kd1', name: 'Kad', type: 'card', balance: 500, apr: 18, minPayment: 50 });
      state.debts.push({ id: 'kd2', name: 'Pinjaman', type: 'personal', balance: 9000, apr: 6, minPayment: 100 });
      save(); renderAll();
      await wait(50);
      state.debts[0].balance = 0; save(); renderAll();
      await wait(600);
      const dlg = document.getElementById('debt-paid-dialog');
      out.debtSheet = dlg.open;
      out.debtKira = !!document.querySelector('#debt-paid-kira svg.kira--party');
      out.debtBurst = document.querySelectorAll('#debt-paid-kira .kira-burst i').length;
      out.kiraNotOnTitle = !document.getElementById('debt-paid-title').contains(document.querySelector('#debt-paid-kira'));
      await wait(1500);
      out.debtBurstGone = !document.querySelector('#debt-paid-kira .kira-burst');
      dlg.close();
      renderAll();
      await wait(500);
      out.debtOnce = !dlg.open;
      document.querySelectorAll('dialog[open]').forEach((d) => d.close());
      // The first goal reached: the milestone sheet with party Kira. (The
      // suite turns milestone sheets off by default; this check needs one.)
      window.DUITFUL_MILESTONE_SHEETS = true;
      state.savings.push({ id: 'kg1', name: 'Umrah', target: 1000, current: 100 });
      save(); renderAll();
      await wait(50);
      state.savings[0].current = 1000; save(); renderAll();
      await wait(1500);
      const ms = document.getElementById('milestone-dialog');
      out.goalSheet = ms.open && !!document.querySelector('#milestone-kira svg.kira--party');
      out.goalSheetBurst = document.querySelectorAll('#milestone-kira .kira-burst i').length;
      document.querySelectorAll('dialog[open]').forEach((d) => d.close());
      await wait(1200);
      document.querySelectorAll('dialog[open]').forEach((d) => d.close());
      window.DUITFUL_MILESTONE_SHEETS = false;
      // A later goal: a toast and party Kira with a burst on it, once.
      state.savings.push({ id: 'kg2', name: 'Telefon', target: 2000, current: 10 });
      save(); renderAll();
      await wait(50);
      state.savings[1].current = 2500; save(); renderAll();
      await wait(550);
      const hop = document.querySelector('.kira-hop--party');
      out.goalToast = /Telefon/.test(document.getElementById('toast').textContent);
      out.goalHop = !!hop && !!hop.querySelector('svg.kira--party');
      out.goalBurst = hop ? hop.querySelectorAll('.kira-burst i').length : 0;
      await wait(1600);
      out.goalHopGone = !document.querySelector('.kira-hop');
      renderAll();
      await wait(700);
      out.goalOnce = !document.querySelector('.kira-hop');
      // Over budget: worried Kira beside one kind line, under the figures.
      const m = currentMonthISO();
      state.income.push({ id: 'ki1', name: 'Gaji', amount: 1000, month: m, repeatNext: true });
      state.budgetPools.push({ id: 'kp1', name: 'Makan', limit: 100, color: '#c8704b', createdAt: Date.now(), active: false });
      state.dailyExpenses.push({ id: 'kx1', createdAt: Date.now(), kind: 'expense', date: todayISO(), amount: 1500, category: 'Food', note: '', budgetPoolId: 'kp1', budgetPoolName: 'Makan' });
      save(); renderAll();
      await wait(150);
      const note = document.getElementById('hero-kira-note');
      out.heroNote = !note.hidden && !!note.querySelector('.kira-note-mark svg.kira--worried') && /bit over/i.test(note.textContent);
      const overlaps = (a, b2) => { const x = a.getBoundingClientRect(), y = b2.getBoundingClientRect(); return x.width && y.width && x.left < y.right && x.right > y.left && x.top < y.bottom && x.bottom > y.top; };
      const figures = ['stat-net', 'hero-progress-text', 'hero-target'].map((id) => document.getElementById(id));
      const heroKira = note.querySelector('svg.kira');
      out.heroNotOnFigures = figures.every((f) => !f.contains(note) && !note.contains(f) && !overlaps(heroKira, f) && !overlaps(note, f));
      out.oneKiraHome = [...document.querySelectorAll('#tab-dashboard svg.kira')].filter((s) => s.getBoundingClientRect().width > 0).length === 1;
      const pnote = document.getElementById('pool-kira-note');
      out.poolNote = !pnote.hidden && !!pnote.querySelector('svg.kira--worried') && !document.getElementById('budget-pool-list').contains(pnote);
      // Back under: the notes go away.
      state.dailyExpenses = state.dailyExpenses.filter((e) => e.id !== 'kx1');
      save(); renderAll();
      out.notesGone = note.hidden && pnote.hidden && !note.querySelector('svg');
      // More hops: an accepted alert (spend and income) and a voice entry.
      document.querySelectorAll('.kira-hop').forEach((n) => n.remove());
      state.pendingTxns = [{ id: 'kpt1', amount: 12, merchant: 'Kedai', createdAt: Date.now() - 120000 }];
      acceptPending('kpt1');
      await wait(60);
      out.hopAlert = !!document.querySelector('.kira-hop svg.kira--proud');
      await wait(1000);
      state.pendingTxns = [{ id: 'kpt2', kind: 'income', amount: 30, providerName: 'Bank', createdAt: Date.now() - 120000 }];
      acceptIncomePending('kpt2');
      await wait(60);
      out.hopIncome = !!document.querySelector('.kira-hop svg.kira--proud');
      await wait(1000);
      openVoiceEntry('RM 9 nasi lemak');
      await wait(200);
      voiceSaveConfirmed();
      await wait(60);
      out.hopVoice = !!document.querySelector('.kira-hop svg.kira--proud');
      document.querySelectorAll('dialog[open]').forEach((d) => d.close());
      return out;
    });

    // The tour: Kira in the mark, a peeking Kira looking at the spotlight.
    const tour = await kp.evaluate(async () => {
      const wait = (ms) => new Promise((res) => setTimeout(res, ms));
      const out = {};
      openGuide({ firstRun: false });
      await wait(300);
      out.mark = !!document.querySelector('#guide-mark.has-kira svg.kira--happy');
      for (let i = 0; i < 6 && document.getElementById('guide-spotlight').hidden; i++) {
        document.getElementById('guide-next').click();
        await wait(700);
      }
      await wait(500);
      const eyes = document.querySelector('#guide-tooltip-kira svg.kira .kira-eyes');
      out.peek = !!eyes;
      out.peekLooks = !!eyes && eyes.dataset.hold === '1' && /translate\(/.test(eyes.style.transform);
      // Ring centre vs. Kira's eyes: the gaze points toward it.
      const ring = document.getElementById('guide-spot-ring').getBoundingClientRect();
      const svg = document.querySelector('#guide-tooltip-kira svg.kira').getBoundingClientRect();
      const m = /translate\(([-\d.]+)px, ([-\d.]+)px\)/.exec(eyes ? eyes.style.transform : '') || [];
      const dx = (ring.left + ring.width / 2) - (svg.left + svg.width / 2);
      const dy = (ring.top + ring.height / 2) - (svg.top + svg.height * 0.5);
      out.peekTowardRing = m.length === 3 && (Number(m[1]) * dx + Number(m[2]) * dy) > 0;
      // Last step: party.
      for (let i = 0; i < 20 && guideStep < GUIDE_STEPS.length - 1; i++) {
        (document.getElementById('guide-spotlight').hidden ? document.getElementById('guide-next') : document.querySelector('.guide-action-next')).click();
        await wait(250);
      }
      await wait(400);
      out.lastParty = !!document.querySelector('#guide-tooltip-kira svg.kira--party, #guide-mark svg.kira--party');
      closeGuide();
      return out;
    });

    const tag = reduced ? 'reduced motion' : 'motion';
    if (!reduced) {
      check('Kira (1.75.0): first run — happy waving Kira beside the income question (field above a 336px keyboard), proud on bills, happy on debts (never worried), party with a burst for a debt-free date, proud for left-to-spend',
        ob.s1 && ob.inputAboveKeyboard && ob.kiraNotOverInput && ob.s2 && ob.s3 && ob.neverWorried && ob.onePerStep
        && ob.answerParty && ob.answerBurst >= 20 && ob.answerProud, JSON.stringify(ob));
      const lx = Number((/translate\(([-\d.]+)px/.exec(eyesLeft) || [])[1]);
      const rx = Number((/translate\(([-\d.]+)px/.exec(eyesRight) || [])[1]);
      check('Kira (1.75.0): the eyes follow a tap (left, then right, at most 1.6 units) and ease back to centre',
        lx < -0.5 && lx >= -1.6 && rx > 0.5 && rx <= 1.6 && eyesRest === '', JSON.stringify({ eyesLeft, eyesRight, eyesRest }));
      check('Kira (1.75.0): tapping Kira squishes, blinks and sparkles once; only the paper takes the pointer; no neighbouring button fires; never focusable; the AI sheet\'s Kira is left alone',
        tap.cornerNotKira && tap.paperIsKira && tap.notFocusable && tapped.cls && tapped.anim === 'kira-squish' && tapped.hehe
        && tapped.clicks === 0 && !tapped.dialog && tapDone && aiLeftAlone, JSON.stringify({ tap, tapped, tapDone, aiLeftAlone }));
      check('Kira (1.75.0): a debt paid off shows party Kira and a confetti burst in the paid-off sheet, once',
        r.debtSheet && r.debtKira && r.debtBurst >= 20 && r.kiraNotOnTitle && r.debtBurstGone && r.debtOnce, JSON.stringify(r));
      check('Kira (1.75.0): the first goal gets the milestone sheet with party Kira; a later goal gets a toast with party Kira and a burst, once',
        r.goalSheet && r.goalSheetBurst >= 15 && r.goalToast && r.goalHop && r.goalBurst >= 20 && r.goalHopGone && r.goalOnce, JSON.stringify(r));
      check('Kira (1.75.0): over budget shows worried Kira beside one kind line under the hero figures (never on them) and under Budget Pools; both go when back under',
        r.heroNote && r.heroNotOnFigures && r.oneKiraHome && r.poolNote && r.notesGone, JSON.stringify(r));
      check('Kira (1.75.0): Kira hops after an accepted alert (spend and income) and a voice entry',
        r.hopAlert && r.hopIncome && r.hopVoice && kErr.length === 0, JSON.stringify({ ...r, kErr }));
      check('Kira (1.75.0): the tour shows Kira in the mark, a peeking Kira looking toward the spotlight, and party Kira on the last step',
        tour.mark && tour.peek && tour.peekLooks && tour.peekTowardRing && tour.lastParty, JSON.stringify(tour));
    } else {
      check('Kira (1.75.0): reduce motion — no eye tracking, no tap squish, no confetti; celebrations and kind notes still show Kira standing still',
        eyesLeft === '' && eyesRight === '' && !tapped.cls && !tapped.hehe
        && r.debtKira && r.debtBurst === 0 && r.goalSheet && r.goalSheetBurst === 0 && !r.goalHop
        && ob.answerParty && ob.answerBurst === 0 && r.heroNote && !r.hopAlert && !r.hopVoice && kErr.length === 0,
        JSON.stringify({ eyesLeft, eyesRight, tapped, r, ob, kErr, tag }));
    }
    await kCtx.close();
  }
}

// ── Kira phase 3 (v1.76.0): Festive Kira ─────────────────────────────────
{
  await import(pathToFileURL(path.join(REPO_ROOT, 'app', 'kira-seasons.js')).href);
  const K = globalThis.KiraSeasons;
  const S = (d, o) => K.seasonFor(d, o);
  const brief = (s) => (s ? { id: s.id, look: s.look, calm: s.calm, flag: s.flag, names: s.names } : null);

  // The table is the verified list, row for row.
  const verified = JSON.parse(readFileSync(path.join(REPO_ROOT, 'docs/plans/kira-holidays-2026-2028.json'), 'utf8'));
  const keyMap = { ramadan_start: 'ramadan', raya_aidilfitri: 'raya', raya_haji: 'haji', awal_muharram: 'muharram', maulidur_rasul: 'maulid' };
  const tableDiff = [];
  for (const [y, rows] of Object.entries(verified)) for (const [k, v] of Object.entries(rows)) {
    const row = K.TABLE[y] && K.TABLE[y][keyMap[k] || k];
    if (!row || row[0] !== v.date || row[1] !== v.days || row[2] !== (v.status === 'gazetted' ? 'g' : 'e')) tableDiff.push(`${y}.${k}`);
  }
  check('Festive Kira (1.76.0): the holiday table matches docs/plans/kira-holidays-2026-2028.json (dates, days, gazetted vs expected)',
    tableDiff.length === 0 && Object.keys(K.TABLE).length === 3, JSON.stringify(tableDiff));
  const thisYear = new Date().getFullYear();
  check('Festive Kira (1.76.0): the holiday table runs at least to next year — add the next year\'s dates to app/kira-seasons.js before this fails',
    K.lastTableYear() >= thisYear + 1, `last ${K.lastTableYear()}, now ${thisYear}`);

  const cases = {
    ordinary: S('2026-11-26'), july: S('2026-07-15'),
    newyearEve: S('2026-12-31'), xmas: S('2026-12-25'), xmasFirst: S('2026-12-20'), xmasBefore: S('2026-12-19'),
    cny2027: S('2027-02-06'), cnyInRamadan: S('2027-02-08'), ramadan: S('2027-02-21'), nuzul: S('2027-02-24'),
    rayaEve: S('2027-03-09'), raya: S('2027-03-10'), rayaLast: S('2026-04-04'), rayaAfter: S('2026-04-05'),
    kaamatan: S('2026-05-30'), wesakKaamatan: S('2026-05-31'), agongGawai: S('2026-06-01'), gawai: S('2026-06-02'),
    merdekaMonth: S('2026-08-10'), maulidMerdeka: S('2026-08-25'), merdeka: S('2026-08-31'), mDay: S('2026-09-16'), mDayLead: S('2026-09-03'),
    deepavali: S('2026-11-05'), thaipusamInRamadan: S('2028-02-09'), haji: S('2027-05-18'),
  };
  const c = cases;
  check('Festive Kira (1.76.0): an ordinary day has no outfit; windows open and close on the spec\'s days (Christmas 20–26 Dec, Raya to day +14, New Year from 31 Dec)',
    !c.ordinary && !c.july && !c.xmasBefore && !c.rayaAfter && c.xmas.id === 'christmas' && c.xmasFirst.id === 'christmas'
    && c.newyearEve.id === 'newyear' && c.rayaLast.id === 'raya' && c.deepavali.id === 'deepavali' && c.haji.look === 'haji' && c.haji.calm,
    JSON.stringify({ ordinary: brief(c.ordinary), xmasBefore: brief(c.xmasBefore), rayaAfter: brief(c.rayaAfter), haji: brief(c.haji) }));
  check('Festive Kira (1.76.0): 2027-02-08 — CNY lingering into the first day of Ramadan keeps CNY\'s calm props (no party), and the greeting names both',
    c.cnyInRamadan.id === 'cny' && c.cnyInRamadan.calm === true && JSON.stringify(c.cnyInRamadan.names) === '["cny","ramadan"]'
    && !/kf-orange/.test(K.props(c.cnyInRamadan).front + K.props(c.cnyInRamadan).inner) && /kf-red/.test(K.props(c.cnyInRamadan).inner)
    && c.cny2027.calm === false && c.cny2027.strong && /kf-orange/.test(K.props(c.cny2027).front),
    JSON.stringify({ inRamadan: brief(c.cnyInRamadan), cny: brief(c.cny2027) }));
  check('Festive Kira (1.76.0): Ramadan is calm with a crescent and pelita; Nuzul is Ramadan\'s look with a star, under Ramadan\'s greeting; Raya\'s eve is calm Raya (no ketupat) with Raya\'s greeting alone; Raya day is strong',
    c.ramadan.look === 'ramadan' && c.ramadan.calm && c.nuzul.look === 'nuzul' && c.nuzul.id === 'ramadan' && c.nuzul.key === c.ramadan.key
    && c.rayaEve.id === 'raya' && c.rayaEve.calm && JSON.stringify(c.rayaEve.names) === '["raya"]' && !/kf-ketupat/.test(K.props(c.rayaEve).front)
    && c.raya.calm === false && c.raya.strong && /kf-songkok/.test(K.props(c.raya).inner) && /kf-ketupat/.test(K.props(c.raya).front)
    && c.thaipusamInRamadan.id === 'thaipusam' && c.thaipusamInRamadan.calm,
    JSON.stringify({ ramadan: brief(c.ramadan), nuzul: brief(c.nuzul), eve: brief(c.rayaEve), raya: brief(c.raya) }));
  check('Festive Kira (1.76.0): national beats state — 2026-05-31 is Wesak (Kaamatan\'s 2nd day), 2026-06-01 (Agong + Gawai\'s first day) is the neutral festive look naming both, 2026-05-30 and 06-02 are Kaamatan and Gawai',
    c.wesakKaamatan.id === 'wesak' && c.agongGawai.id === 'shared' && c.agongGawai.look === 'festive'
    && JSON.stringify(c.agongGawai.names) === '["agong","gawai"]' && c.kaamatan.id === 'kaamatan' && c.gawai.id === 'gawai',
    JSON.stringify({ w: brief(c.wesakKaamatan), shared: brief(c.agongGawai), k: brief(c.kaamatan), g: brief(c.gawai) }));
  check('Festive Kira (1.76.0): Merdeka month flies the flag (big on 31 Aug and 16 Sep); another holiday inside it keeps its own look plus a small flag (Maulidur Rasul 2026-08-25)',
    c.merdekaMonth.look === 'merdeka' && c.merdekaMonth.flag === 'normal' && c.merdeka.flag === 'big' && c.mDay.id === 'malaysia_day' && c.mDay.flag === 'big'
    && c.mDayLead.id === 'malaysia_day' && c.maulidMerdeka.look === 'maulid' && c.maulidMerdeka.flag === 'small' && c.maulidMerdeka.calm
    && /kf-flag-blue/.test(K.props(c.maulidMerdeka).front) && (K.props(c.merdeka).inner.match(/kf-flag-white/g) || []).length === 1
    && (/<path class="kf-flag-white" d="([^"]+)"/.exec(K.props(c.merdeka).inner)[1].match(/M/g) || []).length === 7
    && (/kf-flag-yellow" d="(M[^"]+)"/g.test(K.props(c.merdeka).inner)),
    JSON.stringify({ month: brief(c.merdekaMonth), maulid: brief(c.maulidMerdeka), day: brief(c.merdeka), mday: brief(c.mDay) }));
  // After the table: Intl calendars (Raya 2029 from islamic-umalqura, CNY from chinese).
  const h29 = K.holidaysOf(2029);
  const near = (iso, want, d) => Math.abs((Date.parse(iso) - Date.parse(want)) / 864e5) <= d;
  const k29 = S('2029-02-14');
  check('Festive Kira (1.76.0): after 2028 the dates come from Intl (Raya 2029 ≈ 14 Feb, CNY 2029 = 13 Feb, Merdeka fixed); Thaipusam, Wesak and Deepavali are skipped; Raya meeting CNY is Kongsi Raya',
    !!h29.raya && near(h29.raya[0][0], '2029-02-14', 1) && h29.cny && h29.cny[0][0] === '2029-02-13' && h29.merdeka[0][0] === '2029-08-31'
    && !h29.thaipusam && !h29.wesak && !h29.deepavali && k29 && k29.id === 'kongsi_raya' && JSON.stringify(k29.names) === '["raya","cny"]'
    && /kf-songkok/.test(K.props(k29).inner) && /kf-red/.test(K.props(k29).inner),
    JSON.stringify({ raya: h29.raya, cny: h29.cny, k29: brief(k29) }));
  // Deepa Raya, from a table where the two meet.
  const t = JSON.parse(JSON.stringify(K.TABLE));
  t[2026].deepavali = ['2026-03-22', 1, 'g'];
  const dr = S('2026-03-22', { table: t });
  check('Festive Kira (1.76.0): Raya meeting Deepavali is Deepa Raya (songkok, diya, kolam); the nearest first day wins otherwise',
    dr && dr.id === 'deepa_raya' && /kf-diya/.test(K.props(dr).front) && /kf-kolam/.test(K.props(dr).under), JSON.stringify(brief(dr)));

  // In the app.
  for (const reduced of [false, true]) {
    const fctx = await b.newContext({ viewport: { width: 390, height: 844 }, reducedMotion: reduced ? 'reduce' : 'no-preference' });
    await fctx.addInitScript(() => { window.DUITFUL_KIRA_DATE = '2027-03-10'; });
    const fp = await fctx.newPage();
    const fErr = [];
    fp.on('pageerror', (e) => fErr.push(e.message));
    await fp.goto(`${BASE}/app/index.html`);
    await fp.waitForTimeout(500);
    await fp.click('#btn-start-open');
    await fp.waitForTimeout(1500);
    await fp.evaluate(() => document.querySelectorAll('dialog[open]').forEach((d) => d.close()));
    const r = await fp.evaluate(async () => {
      const wait = (ms) => new Promise((res) => setTimeout(res, ms));
      const out = {};
      const greet = document.getElementById('kira-greet');
      out.greet = !greet.hidden && document.getElementById('kira-greet-text').textContent;
      const gk = greet.querySelector('svg.kira');
      out.greetKira = !!gk && gk.classList.contains('kira--festive') && gk.classList.contains('kira-look-raya') && !!gk.querySelector('.kf-songkok');
      out.oneKiraHome = document.getElementById('today-kira').innerHTML === '';
      out.greetNotOnFigures = greet.getBoundingClientRect().bottom <= document.getElementById('stat-net').getBoundingClientRect().top;
      out.debtsKira = !!document.querySelector('#list-debt .empty-block-kira svg.kira--festive .kf-songkok');
      // Counting keeps the sempoa; a hat at most.
      const ai = document.createElement('div');
      ai.innerHTML = kiraSvg('counting', { ai: true });
      out.countingHat = !!ai.querySelector('.sempoa') && !!ai.querySelector('.kf-songkok') && !ai.querySelector('.kf-hand, .kf-ground, .kf-under, .kf-flag, .kf-moon');
      // Flicker on the Deepavali diya, motion-safe.
      window.DUITFUL_KIRA_DATE = '2026-11-08';
      kiraRefreshAll();
      const diya = document.querySelector('#list-debt svg.kira .kf-flicker');
      out.flicker = diya ? getComputedStyle(diya).animationName : 'missing';
      // Christmas: a new season greets again; dismiss keeps it away.
      window.DUITFUL_KIRA_DATE = '2027-12-25';
      renderAll();
      out.xmas = !greet.hidden && document.getElementById('kira-greet-text').textContent;
      document.getElementById('kira-greet-close').click();
      await wait(50);
      renderAll();
      out.xmasDismissed = greet.hidden && JSON.parse(localStorage.getItem('duitful.kiraGreet'))['christmas-2027-12-25'] === 'x';
      out.todayBack = document.getElementById('today-kira').innerHTML !== '';
      // Raya again on its next day: already greeted this season.
      window.DUITFUL_KIRA_DATE = '2027-03-11';
      renderAll();
      out.rayaOnce = greet.hidden;
      // Ramadan: calm — no party, no confetti, no food; the greeting is Salam Ramadan.
      window.DUITFUL_KIRA_DATE = '2027-02-21';
      kiraRefreshAll(); renderAll();
      out.ramadanGreet = document.getElementById('kira-greet-text').textContent;
      const slot = document.createElement('span');
      slot.className = 'celebrate-kira';
      document.body.appendChild(slot);
      kiraCelebrate(slot);
      out.ramadanNoParty = !!slot.querySelector('svg.kira--proud') && !slot.querySelector('.kira--party, .kira-confetti, .kira-burst');
      out.ramadanNoFood = !document.querySelector('svg.kira .kf-orange, svg.kira .kf-ketupat');
      slot.remove();
      // CNY lingering into Ramadan: calm CNY props.
      window.DUITFUL_KIRA_DATE = '2027-02-08';
      kiraRefreshAll();
      const cny = document.querySelector('#list-debt svg.kira');
      out.cnyCalm = cny.classList.contains('kira-look-cny') && !!cny.querySelector('.kf-hand ellipse.kf-red') && !cny.querySelector('.kf-orange');
      // Merdeka day: the flag.
      window.DUITFUL_KIRA_DATE = '2026-08-31';
      kiraRefreshAll(); renderAll();
      out.flag = !!document.querySelector('#list-debt svg.kira .kf-flag .kf-flag-blue') && document.getElementById('kira-greet-text').textContent;
      // Switch off: plain Kira everywhere, no greeting; on again: back.
      const box = document.getElementById('pref-festive-kira');
      out.switchDefaultOn = box.checked;
      box.checked = false;
      box.dispatchEvent(new Event('change', { bubbles: true }));
      renderAll();
      out.offPlain = document.querySelectorAll('svg.kira.kira--festive').length === 0 && document.querySelectorAll('svg.kira').length > 0
        && greet.hidden && localStorage.getItem('duitful.festiveKira') === 'off';
      box.checked = true;
      box.dispatchEvent(new Event('change', { bubbles: true }));
      out.onAgain = document.querySelectorAll('svg.kira.kira--festive').length > 0;
      return out;
    });
    if (!reduced) {
      check('Festive Kira (1.76.0): on Raya the Home greeting says "Selamat Hari Raya Aidilfitri, Maaf Zahir Batin" with Kira in a songkok, above the figures; the Today row leaves Kira out; the Debts empty state wears it too',
        r.greet === 'Selamat Hari Raya Aidilfitri, Maaf Zahir Batin' && r.greetKira && r.oneKiraHome && r.greetNotOnFigures && r.debtsKira, JSON.stringify(r));
      check('Festive Kira (1.76.0): counting Kira keeps the sempoa and may only add a hat',
        r.countingHat, JSON.stringify(r));
      check('Festive Kira (1.76.0): one greeting per season per device — a new season greets, Dismiss keeps it away, the same season the next day stays quiet',
        r.xmas === 'Merry Christmas' && r.xmasDismissed && r.todayBack && r.rayaOnce, JSON.stringify(r));
      check('Festive Kira (1.76.0): Ramadan is calm (party becomes proud, no confetti, no food props, "Salam Ramadan"); CNY inside Ramadan keeps a lantern, not mandarins; Merdeka flies the flag',
        r.ramadanGreet === 'Salam Ramadan' && r.ramadanNoParty && r.ramadanNoFood && r.cnyCalm && r.flag === 'Happy Merdeka', JSON.stringify(r));
      check('Festive Kira (1.76.0): Settings → Festive Kira is on by default; off draws plain Kira everywhere and hides the greeting (this device only); on brings the outfits back',
        r.switchDefaultOn && r.offPlain && r.onAgain && fErr.length === 0, JSON.stringify({ r, fErr }));
      check('Festive Kira (1.76.0): the Deepavali diya flickers (motion-safe)', r.flicker === 'kf-flicker', r.flicker);
    } else {
      check('Festive Kira (1.76.0): reduce motion — outfits and the greeting still show, nothing flickers',
        r.greetKira && r.flicker === 'none' && fErr.length === 0, JSON.stringify({ flicker: r.flicker, fErr }));
    }
    await fctx.close();
  }

  // 360px in English, Malay and Chinese, on the longest greeting (Kongsi Raya).
  const nctx = await b.newContext({ viewport: { width: 360, height: 780 } });
  await nctx.addInitScript(() => { window.DUITFUL_KIRA_DATE = '2029-02-14'; });
  const np = await nctx.newPage();
  await np.goto(`${BASE}/app/index.html`);
  await np.waitForTimeout(500);
  await np.click('#btn-start-open');
  await np.waitForTimeout(1500);
  await np.evaluate(() => document.querySelectorAll('dialog[open]').forEach((d) => d.close()));
  const fit = {};
  for (const lang of ['en', 'ms', 'zh']) {
    await np.evaluate((l) => { localStorage.setItem('duitful.lang', l); }, lang);
    await np.reload();
    await np.waitForTimeout(1500);
    await np.evaluate(() => document.querySelectorAll('dialog[open]').forEach((d) => d.close()));
    fit[lang] = await np.evaluate(() => {
      const out = [];
      const card = document.getElementById('kira-greet');
      if (card.hidden) out.push('greeting hidden');
      const c = card.getBoundingClientRect();
      for (const el of card.querySelectorAll(':scope > *')) {
        const r = el.getBoundingClientRect();
        if (r.width && (r.left < c.left - 1 || r.right > c.right + 1)) out.push(el.id || el.className);
      }
      if (document.documentElement.scrollWidth > 360) out.push('page scrolls sideways');
      out.push('text:' + document.getElementById('kira-greet-text').textContent);
      return out;
    });
  }
  check('Festive Kira (1.76.0): at 360px the Kongsi Raya greeting fits its card in English, Malay and Chinese (greeting rows translated)',
    Object.values(fit).every((v) => v.length === 1 && v[0].startsWith('text:Selamat Hari Raya Aidilfitri, Maaf Zahir Batin · '))
    && /Happy Chinese New Year$/.test(fit.en[0]) && /Selamat Tahun Baru Cina$/.test(fit.ms[0]) && /新年快乐，恭喜发财$/.test(fit.zh[0]),
    JSON.stringify(fit));
  await nctx.close();

  // The split friend page and the landing pages wear the same outfit.
  const sctx = await b.newContext({ viewport: { width: 390, height: 844 } });
  await sctx.addInitScript(() => { window.DUITFUL_KIRA_DATE = '2027-03-10'; });
  const sp = await sctx.newPage();
  await sp.goto(`${BASE}/split/#DFS1.x`);
  await sp.waitForTimeout(800);
  const split = await sp.evaluate(() => ({
    n: document.querySelectorAll('svg.mascot.is-festive').length,
    all: document.querySelectorAll('svg.mascot').length,
    songkok: document.querySelectorAll('svg.mascot .kf-songkok').length,
    key: document.querySelector('svg.mascot')?.getAttribute('data-season'),
  }));
  await sp.evaluate(() => localStorage.setItem('duitful.festiveKira', 'off'));
  await sp.reload();
  await sp.waitForTimeout(600);
  const splitOff = await sp.evaluate(() => document.querySelectorAll('svg.mascot.is-festive').length);
  await sp.evaluate(() => localStorage.removeItem('duitful.festiveKira'));
  await sp.goto(`${BASE}/index.html`);
  await sp.waitForTimeout(600);
  const landing = await sp.evaluate(() => {
    const k = document.querySelector('.hero-kira');
    return { aria: k && k.getAttribute('aria-hidden'), key: k && k.querySelector('svg').getAttribute('data-season'), songkok: !!(k && k.querySelector('.kf-songkok')), pos: k && getComputedStyle(k).position };
  });
  check('Festive Kira (1.76.0): the split friend page\'s receipt friends wear the season (songkok on Raya) and stay plain when Festive Kira is off',
    split.n === split.all && split.all >= 3 && split.songkok === split.all && split.key === 'raya-2027-03-10' && splitOff === 0, JSON.stringify({ split, splitOff }));
  check('Festive Kira (1.76.0): the landing hero has a small decorative Kira (aria-hidden, absolutely placed) in the season\'s outfit',
    landing.aria === 'true' && landing.key === 'raya-2027-03-10' && landing.songkok && landing.pos === 'absolute', JSON.stringify(landing));
  await sctx.close();
}

// Maybank / Maybank Islamic Current & Savings account statements (DD/MM dates,
// trailing +/-, leading-dot ".01+", overdrawn "DR" balances, multi-line payees).
{
  const vm = await import('node:vm');
  const ctx = { window: {}, document: { getElementById: () => null }, console };
  vm.runInNewContext(readFileSync(path.join(REPO_ROOT, 'app/statement.js'), 'utf8'), ctx);
  const lines = [
    'Maybank Islamic',
    'TARIKH PENYATA',
    'STATEMENT DATE : 31/10/26',
    'PREMIER MUDHARABAH ACCOUNT',
    'URUSNIAGA AKAUN / ACCOUNT TRANSACTIONS',
    'BEGINNING BALANCE 50.00',
    '07/10 TRANSFER TO A/C 400.00+ 450.00',
    'SAMPLE SENDER*',
    '10/10 DUITNOW PAYMENT 10.50- 439.50',
    'Kedai Air Contoh*',
    '22/10 TRANSFER FR A/C 1,000.00- 560.50DR',
    'SAMPLE RECIPIENT*',
    '22/10 PAYMENT CREDIT - APS/OTHERS 2,000.00+ 1,439.50',
    'SAMPLE EMPLOYER*',
    '24/10 PAYMENT FR A/C 25.00- 1,414.50',
    'Kedai Makan Contoh*',
    '31/10 DIVIDEND PAID .01+ 1,414.51',
    'ENDING BALANCE : 1,414.51',
    'TOTAL DEBIT : 1,035.50',
    'TOTAL CREDIT : 2,400.01',
  ].map((text, i) => ({ page: 1, y: 100 + i * 10, text, items: [] }));
  const parsed = ctx.parseStatement({ lines, scanned: false });
  const rec = ctx.reconcileStatement(parsed);
  check('statement (maybank-account): parses DD/MM dates, .01+ cents, overdrawn DR balances, multi-line payees, and reconciles ok',
    parsed.layout === 'maybank-account' && parsed.bank === 'Maybank' && parsed.rows.length === 6
    && parsed.rows[2].balance === -560.5 && parsed.rows[5].amount === 0.01 && parsed.rows[4].payee === 'Kedai Makan Contoh'
    && rec.status === 'ok',
    JSON.stringify({ layout: parsed.layout, count: parsed.rows.length, rec }));
}

await b.close();
if (server) server.kill();
dropVendorLink();

console.log('\n✅ PASS (' + ok.length + ')');
ok.forEach(o => console.log('  ✓ ' + o));
if (bad.length) { console.log('\n❌ FAIL (' + bad.length + ')'); bad.forEach(x => console.log('  ✗ ' + x)); }
if (errors.length) { console.log('\n⚠ JS errors:'); errors.forEach(e => console.log('  ' + e)); }
process.exit(bad.length || errors.length ? 1 : 0);
